import type { CRDocument } from '../types';

export const docs: CRDocument[] = [
  {
    id: "synax-baramhat-1",
    title: { en: "Baramhat 1", ar: "1 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "استشهاد القديسين مقرنيوس وتكلا" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار استشهاد القديسين مقرنيوس وتكلا ، صلاته تكون معنا ولربنا المجد دائما آمين ." } },
      { kind: 'heading', text: { en: "The Departure of St. Narcissus.", ar: "نياحة القديس نركيسوس" } },
      { kind: 'reading', text: { en: "On this day of the year, 222 A.D., departed the father St. Narcissus, Bishop of Jerusalem. This father came to Jerusalem during the reign of Alexander Caesar, who loved the Christians, in the year 190 A.D. This father was holy and unblemished in all his conduct. He shepherded his people with the best of care. Later, Alexander died and after him Maximianus Caesar reigned who incited persecution against the Christians. He slew many of the bishops and the remaining fled leaving their parishes. God granted this father the gift of performing wonders. On the eve of the feast of Easter, the oil in the lamps ran out, so he ordered the lamps to be filled with water and were lit. They all illuminated that night also by the light of his teachings.", ar: "في مثل هذا اليوم من سنة 222 م تنيح الأب القديس نركيسوس أسقف بيت المقدس ، وهذا الأب قدم إلى بيت المقدس في سنة 190 م في عهد الكسندروس قيصر الذي كان محبا للنصارى . وكان هذا الأب قديسا كاملا في جميع تصرفاته ، فرعى شعبه أحسن رعاية ، ولم يلبث قليلا على كرسيه حتى مات الكسندروس ، وقام بعده مكسيميانوس قيصر ، وهذا أثار الاضطهاد على المسيحيين ، وقتل عدداً كبيرا من الأساقفة وغيرهم ، وهرب البعض تاركا كرسيه أما هذا الأب فقد منحه الله موهبة صنع العجائب ، ففي ليلة عيد القيامة كان الزيت قد نفذ من القناديل ، فأمر أن تملأ ماء فأضاءت. واستنار الجميع فى تلك الليلة من ضوء تعاليمه أيضا . ولكن عدو الخير لم يسكت ، فحرك البعض ضده ، فاتهموه بخطية النجاسة ، وكان جزاء الله مرا على أولئك الكاذبين ، إذ مات أحدهم محروقا ، واندلقت أمعاء آخر ، وذاب جسم الثالث من دوام المرض ، وقتل رابع ، وتاب الخامس ذارفا الدموع معترفا بذنبه ." } },
      { kind: 'reading', text: { en: "The enemy of the good did not stop but, moved some people against him. They accused him of committing the sin of infidelity. God's punishment for those liars was bitter. One of them burned to death, and the bowels of another poured out and died, the body of the third wasted out from a long sickness, the fourth was killed and the fifth repented with tears confessing his sins. As for the saint, he went to the desert and disappeared there, lest his stay be a stumble to others.", ar: "أما القديس فذهب إلى البرية واختفى فيها لئلا يكون بقاؤه سببا في عثرة أحد ، وأذ لم يعرف من أمره شيئا ، اختاروا عوضه آنسانا اسمه ديوس ، فقام زمانا ثم تنيح فقدموا آخر اسمه غوردينوس . ولما انقضى زمان الاضطهاد عاد الأب نركيسوس إلي أورشليم فقابله شعبه بفرح عظيم . وطلب إليه غورينوس أن يتسلم كرسيه فلم يقبل وآثر الوحدة . فألح عليه أن يبقى معه بالقلاية فأقام معه سنة تنيح على أثرها غورينوس ، فتسلم القديس نركيسوس كرسيه . وكان قد كبر وضعف جدا ، فطلب من أبنائه أن يختاروا أسقفا آخر عليهم فأبوأ . وحث أن الكسندروس أسقف القبادوقية حضر إلي بيت المقدس ليصلى ويعود ، ولما هم بالرجوع بعد العيد اذا بالشعب يسمع صوتا عظيما في كنيسة القيامة يقول &quot; اخرجوا إلي باب المدينة الفلانى ، وأول من يدخل منه فهذا امسكوه وأبقوه مع نركيسوس ليساعده . فكما خرجوا إلي الباب التقوا بالأسقف الكسندروس فرجوه أن يقيم مع الأب نركيسوس ، فقبل بعد تمنع شيد ، ولبث معه الى أن تنيح ، وكانت مدة جلوس هذا الأب على كرسى الأسقفية سبعا وثلاثين سنة ، وجملة حياته مائة وست عشرة سنة. صلاته تكون معنا آمين ." } },
      { kind: 'reading', text: { en: "Since nothing was known of St. Narcissus whereabouts, another man was chosen in his place whose name was Dius. Dius remained for a short period of time; he then departed. Upon Dius' departure they chose another called Ghordinus. When the time of persecution was over, Abba Narcissus returned to Jerusalem where he was greeted by his people with great joy. Ghordinus asked him to take over his Chair but, he refused preferring the solitary life. Ghordinus insisted that he stays with him in his cell. St. Narcissus stayed with him for one year at the end of which Ghordinus departed and St. Narcissus acquired his Chair. He had aged and was very week so, he asked his people to choose another bishop, but they refused.", ar: "" } },
      { kind: 'reading', text: { en: "Alexander, Bishop of Cappadocia, came to Jerusalem to visit the Holy Land and pray. When he was about to return, after the feast, the people heard a great voice in the church of the Resurrection saying: \"Go to the gate of the city, the first one to enter it, seize him, make him stay to assist Narcissus.\" When, they went to the gate, they met the Bishop Alexander, and pleaded with him to stay to assist Abba Narcissus. After much resistant, Bishop Alexander decided to accept and stay until the departure of St. Narcissus.", ar: "" } },
      { kind: 'reading', text: { en: "This father remained on the Episcopal Chair for thirty seven years, and all the years of his life were one hundred and sixteen years.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Alexandrus.", ar: "استشهاد القديس الكسندروس الجندى" } },
      { kind: 'reading', text: { en: "On this day also St. Alexandrus, the soldier, was martyred during the reign of the infidel Emperor Maximianus. When this saint refused to raise incense for the idols, the Emperor punished him. The Emperor ordered him hung by his hands and a large heavy stone tied to his feet. He ordered him to be beaten, his sides burned, and placed lit torches against his face. When all these tortures did not dissuade him, the Emperor ordered him beheaded and he received the crown of martyrdom.", ar: "في مثل هذأ اليوم استشهد القديس الكسندروس الجندى ، في أيام الملك الوثنى مكسيميانوس . ولما امتنع هذا القديس عن التبخير للأصنام عاقبه الملك بأن علقه من يديه ، وربط فى رجليه حجرا ثقيلا ، وأمر بضربه وحرق جنبيه وجعل مشاعل نار عنى وجهه . واذ لم تثنه هذه العذابات أمر الملك بضرب رقبته ونال إكليل الشهادة شفاعته تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "May his intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نوة الحسوم : جنوبية غربية بأمطار غزيرة سبعة أيام" } },
      { kind: 'reading', text: { en: "", ar: "في اشهر الشتاء تتعرض الأجزاء المطلة علي البحر المتوسط لظاهرة تولد الانخفاضات الجوية الإعصارية التي تميز الأحوال المناخية في إقليم البحر المتوسط وتعرف في الإسكندرية باسم النوات." } },
      { kind: 'reading', text: { en: "", ar: "هي اضطرابات جوية تنشأ عنها دوامة هوائية دائرية أو بيضاوية ذات ضغط منخفض وسط مساحة ضغطها مرتفع وتندفع فيها الرياح علي شكل حلزوني نحو مركز منخفض بحيث يكون سيرها ضد اتجاه عقارب الساعة ." } },
      { kind: 'heading', text: { en: "Commemoration of Anba Marcura.", ar: "" } },
      { kind: 'reading', text: { en: "Today also is the commemoration of Anba Marcura, the Bishop.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-2",
    title: { en: "Baramhat 2", ar: "2 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Macrobius (Makrawy) the Bishop.", ar: "نياحة الانبا مكراوى الاسقف من اشمون" } },
      { kind: 'reading', text: { en: "On this day the blessed Saint Anba Makrawy (Macrobius) the bishop was martyred. This father was of the nobles of Ashmun Grais (Ashmun Kharirat) and he was ordained bishop for Nikiu (Nakiyos). When persecution against Christians started, Youfanyous, the Governor, sent for the Saint to appear before him. Before he went to the Governor, he went before the Holy Altar, lifted up his hands and prayed. He hid the Altar accessories (Utensils) and the service vestments in a place in the altar. He prayed again to the Lord Christ to guard His church. Then he went with the messengers to the Governor who asked him about his name and his hometown. When the Governor realized that he was the Bishop of the city, he ordered him to be beaten and humiliated. They mixed lime with vinegar and poured it down his throat. Nevertheless, God guarded him and he was unharmed.", ar: "شهادة القديس مكراوى الأسقف قي مثل هذا اليوم استشهد القديس الطوباوي الأنبا مكراوى الأسقف . وهذا الأب كان من أكابر أهل اشمون جريس . ورسم أسقفا على نقيوس وحدث ان ثار اضطهاد على المسيحيين ، فاستدعاه يوفانيوس (ورد في مخطوط بشبين الكوم &quot; لوقيانوس &quot;) الوالي للمثول بين يديه ،وقبل أن يذهب إليه دخل الى المذبح المقدس ورفع يديه وصلى . ثم وضع أوانى المذبح وبدله التقديس في مكان من الهيكل . وصلى ثانية الى السيد المسيح أن يحرس كنيسته ، ثم توجه مع الرسل الى أتوالى الذي تقصى منه عن اسمه ومدينته ، وعلم أنه أسقف المدينة ، أمر أن يضرب ويهان ، وأن يذاب جير في خل ويصب في حلقه . ففعلوا به ذلك ، ومع هذا حفظه الله ولم بنله أى أذى . وبعد ذلك أرسله هذا الوالي الى أرمانيوس والى الإسكندرية . وهذا أودعه السجن فأجرى الله على يديه آيات كثيرة . منها أن أوخارسطوس بن يوليوس الاقفهصى ، مدون أخبار الشهداء ، كان مصابا بالفالج فصلى عليه هذا القديس فشفاه الله بصلاته . وقدس في بيت يوليوس وناولهم واتفق معه أن يهتم بجسده ويكتب سيرته ، وبلغ الى مسامع أرمانيوس ما يعمله هذا القديس من الآيات ، فأمر أن بعذب بأنواع العذابات ، بأن يعصر وتقطع أعضاؤه ، ويلقى للأسد الضارية ، ويغرق في البحر ويوضع في أتون النار ، ولكن الرب كان يقويه فلم تؤذه تلك العذابات . وكانت لهذا القديس أخت عذراء تقوم بخدمة الكنيسة تدعى مريم وشقيقان يدعى أحدهما يؤنس والآخر اسحق ، فحضروا جميعا إليه وهو في السجن وبكوا أمامه قائلين : لقد كنت لنا أبا بعد أبينا ، فكيف تمضى وتتركنا يتامى . فعزاهم وشجعهم وواساهم وطلب إليهم أن يمضوا بسلام . وأخيرا أشار يوليوس الاقفهصى على الوالي قائلا &quot; أكتب قضية هذا الشيخ تسترح منه &quot; . فسمع لقوله وأمر بقطع رأسه فأخذ يوليوس جسده ولفه في لفائف فاخرة مذهبة . ووضع صليبا من ذهب على صدره. وأرسله في سفينة صحبة غلمانه الى مقر كرسيه في نقيوس . فسارت حتى وصلت بلدة أشمون جريس ووقفت دون أن تتحرك كما لو كانت مربوطة بسلاسل ، وعبثا حاولوا تحريكها . وبينما هم كذلك إذا بصوت يخرج من الجسد قائلا : &quot; هذا هو الموضع الذي سر الرب أن يوضع جسدي فيه &quot; . وقد أعلموا أهل البلد بذلك فخرجوا إليهم حاملين سعف النخل ، وحموه بإكرام عظيم الى بلدهم . وكانت جملة حياته مائة وإحدى وثلاثين سنة ، منها ثلاثون سنة قسا ، وتسع وثلاثون سنة أسقفا . وأكمل جهاده - الحسن ونال اكليل الحياة . بركة صلاته تكون معنا ولربنا المجد آمين ." } },
      { kind: 'reading', text: { en: "Later, the Governor sent him to Armenius, the Governor of Alexandria, who casted him into prison. The Lord made, through his hands, many signs. Eucharistos, the son of \r\n, was paralytic. St. Macrobius prayed over him and God healed him through his prayers. He celebrated the Divine Liturgy in Julius home, administered the Holy Mysteries to them, and asked Julius to care for his body and to write his biography.", ar: "" } },
      { kind: 'reading', text: { en: "When Armenius heard what this Saint was performing signs and wonders, he ordered him to be tortured with different kinds of tortures: to be squeezed with the wheel, to cut off his members, to cast him to ferocious lions, to throw him into the sea, and to cast him into hot fire. The Lord strengthened him and all these tortures did not harm him.", ar: "" } },
      { kind: 'reading', text: { en: "This Saint had a virgin sister called Mariam who served the church and two brothers named Yoannis and Isaac. They came to him while he was in prison and wept before him saying: \"You have been a father to us, after our father; so how can you depart and leave us orphans?\" He comforted, encouraged, consoled, and asked them to leave in peace.", ar: "" } },
      { kind: 'reading', text: { en: "Finally, not wanting to see the Saint tortured any more, Julius EL-Akfahsi advised the governor saying: \"Write the decree of this old man and get rid of him\" The Governor listened to him and ordered his head to be cut off. Julius took his body and swathed it in wrappings embroidered in gold. He placed a golden cross on his chest and sent the body with his men in a ship to his Episcopal seat in Nikiu. The ship sailed until it arrived to the city of Ashmun Grais (Ashmun Kharirat). It stopped as if it had been tied with chains and all attempts to move it failed. While they were trying to do that, a voice came out of the body saying: \"This is the place wherein God is pleased that my body shall rest.\" When they told the people of the city, they came out to the ship carrying palm branches. They carried the body with great honor to their city. He lived for one-hundred thirty one years; thirty of them as a priest, thirty nine as a bishop, and he completed his good strife and received the crown of life.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-3",
    title: { en: "Baramhat 3", ar: "3 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Cosmas, the Fifty-Eighth Pope of Alexandria.", ar: "نياحة البابا قزما الاسكندرى 58" } },
      { kind: 'reading', text: { en: "On this day of the year 648 A.M. (27th of February 932 A.D.) the blessed father Anba Cosmas, the Fifty-Eighth Pope of Alexandria, departed. This father was righteous, pure, merciful, chaste, and knowledgeable of the books of the church and in the interpretations thereof.", ar: "فى مثل هذا اليوم من سنة 648 ش ( 27 فبراير 932 ميلادية ) تنيح الأب المغبوط الأنبا قزما الثامن والخمسون من باباوات الكرازة المرقسية . وكان هذا الأب بارا ، طاهرا ، عفيفا ، كثير الرحمة ، ملما بما فى كتب البيعة واستيعاب معانيها. . ولما اختير للبطريركية فى 4 برمهات سنة 636 ش ( 28 فبراير سنة 920 ) رعى رعيته بخوف الله وحسن التدبير ، وكان يوزع ما يفضل عنه على المساكين وعلى تشييد الكنائس ، إلا أن الشيطان لم يدعه بلا حزن لما رأى سيرته هذه . فحدث أنه لما رسم مطرانا لأثيوبيا من الرهبان اسمه بطرس أوفده إلى هناك ، فقابله ملكها بفرح عظيم . وبعد زمن مرض الملك ، وشعر بدنو أجله ، فأستحضر ولديه ، ودعا المطران إليه ، ورفع التاج عن رأسه وسلمه لمطران قائلا &quot;أنا ذاهب الى المسيح والذي ترى أنه يصلح من ولدى للملك بعدى فتوجه &quot; ولما توفى الملك رأى المطران والوزراء أن الابن الأصغر أصلح للملك ، فألبسوه التاج . وحدث بعد قليل أن وصل إلى أثيوبيا راهب من دير الأنبا انطونيوس اسمه بقطر ومعه رفيق له اسمه مينا ، وطلبا من المطران مالا فلم يعطهما ، فأغواهما الشيطان ليبرا مكيدة ضده . فلبس أحدهما زى الأساقفة ولبس الآخر زى تلميذاً له ، وزورا كتابا من الأب البطريرك إلى رجال الدولة يقول فيه &quot; بلغنا أنه قد حضر عندكم إنسان ضال اسمه بطرس ، وادعى أننا أوفدناه مطرانا عليكم وهو في ذلك كاذب . والذي يحمل إليكم هذا الكتاب هو المطران الشرعي مينا . وقد بلغنا أن بطرس المذكور قد توج ابن الملك الصغير دون الكبير ، مخالفا في ذلك الشرائع الدينية والمدنية ، فيجب حال وصوله أن تنفوا كلا من المطران والملك ، وأن تعتبروا الأب مينا حامل رسائلنا هذه مطرانا شرعيا . وتسمحوا له أن يتوج الابن الأكبر ملكا&quot;. وقدم الراهبان الكتاب لابن الملك الأكبر فلما قرأه جمع ، الوزراء وأكابر المملكة وتلاه عليهم . فأمروا بنفي المطران بطرس ، وأجلسوا مينا مكانه وبقطر وكيلا له ونزعوا تاج الملك من الابن الصغير وتوجوا أخاه الكبير بدلا منه ، غير انه لم تمض على ذلك مدة حتى وقع نفور بين المطران الزائف ووكيله الذي انتهز فرصة غياب مطرانه ، وطرد الخدم ، ونهب كل ما وجده ، وعاد إلى مصر وأسلم . ولما وصلت هذه الأخبار آلي البابا قزما حزن حزنا عظيما ، وأرسل كتابا إلى أثيوبيا بحرم مينا الكاذب . فغضب الملك على مينا وقتله ، وطلب المطران بطرس من منفاه فوجده قد تنيح ، ولم يقبل الأب البطريرك أن يرسم لهم مطرانا عوضه ، وهكذا فعل البطاركة الأربعة الذين تولوا الكرسى بعده . وكانت أيام هذا الأب كلها سلاما وهدوءا ، لولا هذا الحادث . وقد قضى على الكرسى المرقسى اثنتي عشرة سنة وتنيح بسلام صلاته تكون معنا آمين ." } },
      { kind: 'reading', text: { en: "When he was chosen Patriarch, on the 4th of Baramhat 636 A.M. (28th of February 920 A.D.), he shepherded his flock in the fear of God and with wisdom. He distributed to the poor, the needy and to building churches, all of the church revenue after the little he used. The evil one, however, did not leave St. Cosmas without grief when he saw his pure life. He ordained a Metropolitan for Ethiopia from the monks, whose name was Peter, and sent him there. The king received him with great joy. A short while later, the king fell sick and felt that his end was near, so he brought his two sons and asked the Metropolitan to come to him. The king took off his crown and handed it to the Metropolitan saying: \"I am going to my Lord Christ and whomever you see fit from my sons to rule the kingdom enthrone him.\"", ar: "" } },
      { kind: 'reading', text: { en: "When the King departed to the Lord, the Metropolitan and the Cabinet saw that the younger son was more suitable for ruling the kingdom, so they crowned him. Shortly afterwards, a monk from the monastery of Anba Antonius called Victor and along with him a companion named Mina came to Ethiopia. They asked the Metropolitan for money; but he refused to give it to them. The devil enticed them to scheme against him. One of them put on the garb of the bishops and the other one as his disciple. They falsified a letter from the father, the Patriarch, to the nobles of the government saying in it: \"We have been informed that a deceptive man called Peter came to you claiming that we have sent him as a Metropolitan for you and he is lying in that. The one who is carrying this massage to you is the legitimate Metropolitan Mina. We have been informed also that Peter has enthroned the younger son of the king instead of his older brother, against the church and civic laws. On the arrival of this message, you should exile both the Metropolitan and the king, consider Abba Mina the carrier of our message to be your legitimate metropolitan and to allow him to enthrone the older son a king.\"", ar: "" } },
      { kind: 'reading', text: { en: "The two monks handed the forged letter to the older son of the king. When he read the letter he gathered the cabinet and the nobles of the government and read it to them. They ordered the exile of Metropolitan Peter and seated Mina in his place. They then took away the crown from the younger son and crowned his older brother. Nevertheless, a dispute occurred between the false Metropolitan and his assistant, who took the liberties of the absence of his Metropolitan and expelled the servants, plundered all what he found, returned to Egypt, and became a Moslem.", ar: "" } },
      { kind: 'reading', text: { en: "When the news reached Pope Cosmas, he grieved exceedingly. He sent a letter to Ethiopia excommunicating Mina the liar. The King of Ethiopia was outraged from Mina's actions and slew him. He asked for the return of Metropolitan Peter from his exile but found that he had departed to his Lord and Savior. The father, the Patriarch, refused to ordain for them another Metropolitan and so the four Patriarchs that followed him.", ar: "" } },
      { kind: 'reading', text: { en: "The days of this father were peaceful and tranquil, if not for this accident. He occupied the throne of St. Mark for twelve years and departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Hadid the priest.", ar: "نياحة الانبا حديد القس" } },
      { kind: 'reading', text: { en: "On this day also, the blessed father and the lover of God Anba Hadid the priest departed. He was righteous and virtuous. The Lord granted him the gift of performing miracles and wonders and granted him the spirit of prophecy and knowing the hidden things. He revealed what was in the hearts of his visitors and healed those who were sick. It was said that he raised a dead man through his prayers. He departed, when he was one hundred years old, in a good old age.", ar: "وفى مثل هذا اليوم تنيح الأب الطوباوي المحب للإله أنبا حديد القس ، وكان تقيا فاضلا ، فمنحه الله موهبة عمل الآيات والعجائب ، وأعطاه روح النبوة ومعرفة السرائر ، حتى أنه كان يكشف ما فى القلوب ، ويشفى أمراض المترددين عليه . وقيل انه أقام ميتا بصلاته . وبعد أن بلغ من العمر مئة سنة تنيح بشيخوخة صالحة صلاته تكون معنا ولربنا المجد دائما آمين ." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Porphyry.", ar: "استشهاد القديس برفوريوس ." } },
      { kind: 'reading', text: { en: "On this day also St. Porphyry (Porphorius) was martyred. He was one of the most nobles of Banias, most charitable and caring for the poor. He visited those in prison because of their debts and paid off their obligations. When the era of persecution started, it was called in every place to worship the idols. The Saint heard that the prince was passing by, he stood in front of his house and shouted in his face, saying: \"I am Christian.\" After many failed trials from the prince to dissuade him on changing his faith, the prince ordered his neck to be cut off. The Saint received the crown of life, and the people of his town took his body, and shrouded it with expensive shrouds.", ar: "فى مثل هذا اليوم استشهد القديس برفوريوس وكان من كبار أغنياء بانياس ، وأكثرهم صدقة وعطفا على الفقراء ، وافتقاد المحبوسين في سبيل ديونهم وايفاء ما عليهم . ولما جاء زمان الاضطهاد ، ونودى في كل مكان بالسجود للأصنام ، وسمع هذا القديس بمرور الأمير ، وقف على باب بيته ، وصاح في وجهه قائلا &quot; أنا نصراني &quot; وبعد محاولات فاشلة من الأمير لاقناعه بالعدول عن إيمانه أصدر أمره بقطع رأسه. فنال إكليل الحياة ، وأخذ أهل بلده جسده وكفنوه بأكفان غالية صلاته تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-4",
    title: { en: "Baramhat 4", ar: "4 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "Assembly of the Holy Council on the island of Bani-Omar.", ar: "مجمع الاربعة عشرية بجزيرة عمر" } },
      { kind: 'reading', text: { en: "On this day a Holy Council convened on the island of Bani-Omar against those people called the Fourteenthians. The Fourteenthians celebrated the feast of the Holy Easter with the Jews on the fourteenth of the crescent of Neesan (April) which was on any day of the week. The Bishop of the island excommunicated them, and sent to Serapion Patriarch of Antioch, Democratus Bishop of Rome, Demetrius Patriarch of Alexandria, and Symmachus Bishop of Jerusalem to inform them of the heresy of these people. Each one of them sent an epistle indicating in it that Easter was only to be celebrated on the Sunday that follows the feast of the Jews and ordered to excommunicate everyone that contradict and disobey that.", ar: "فى مثل هذا اليوم اجتمع بجزيرة بنى عمر مجمع على قوم يقال لهم الاربعتعشرية ، وهؤلاء كانوا يعملون عيد الفصح المجيد مع اليهود فى اليوم الرابع عشر من هلال نيسان فى أي يوم اتفق من أيام الأسبوع . فحرمهم أسقف الجزيرة، وأرسل الى سرابيون بطريرك إنطاكية ، ودمقراطس أسقف روما ، وديمتريوس بطريرك الإسكندرية ، وسيماخس" } },
      { kind: 'reading', text: { en: "A council of eighteen bishops convened and these holy epistles were read to them. They brought those heretics and read before them these epistles, some of them returned from their wrong opinion and the others insisted on their error. They prevented and excommunicated them from the Holy Church. Also, they decided to celebrate Easter as the order of the Holy Apostles saying:\n\"Any one that celebrate Easter on any other day than Sunday, had shared the Jews in their feasts and separated from the Christians.\"", ar: "أسقف بيت المقدس ، وأعلمهم ببدعة هؤلاء القوم . فأرسل كل منهم رسالة حدد فيها أن لا يعمل الفصح إلا فى يوم الأحد الذي يلي عيد اليهود . وأمر بحرم كل من يتعدى هذا ويخالفه . واجتمع مجمع من ثمانية عشر أسقفا ، وتليت عليهم هذه الرسائل المقدسة . فاستحضروا هؤلاء المخالفين ، وقرأوا عليهم الرسائل . فرجع قوم عن رأيهم السيىء ، وبقى الآخرون على ضلالهم . فحرموهم ومنعوهم ، وقرروا عمل الفضح كأوامر الرسل القديسين القائلين : ان من يعمل يوم القيامة فى غير يوم الأحد ، فقد شارك اليهود فى أعيادهم ، وافترق من المسيحيين . أما الخلاف بسبب عيد الفصح المسيحي (القيامة) فقد بدأ بين آسيا الصغرى وروما ، فجاهر بوليكربس أسقف أزمير المحافظة على يوم 14 نيسان لذكرى الصلب ، و 16 نيسان لذكرى القيامة ( وهما التاريخان اللذان حدث فيهما الصلب والقيامة بدون نظر الى اليوم فى الأسبوع . وسار معه فى رأيه مسيحيو ما بين النهرين وكيليكيا وسوريا . أما فكتور أسقف روما فجاهر بضرورة ملاحظة أن يكون الصلب يوم الجمعة والقيامة يوم الأحد . ( باعتبار أن يوم الجمعة هو اليوم الذي حدث فيه الصلب ، والأحد هو اليوم الذي حدث فيه القيامة ) . وقد شايعه فى ذلك مسيحيو مصر والعرب وبنطس واليونان . واشتد الخلاف بين الأسقفين ، إلا أن المودة كانت قائمة . وتدخلت الإسكندرية فى هذا الموضوع ، وحاول أسقفها يمتريوس الكرام التوفيق بين الرأيين (أن تكون ذكرى الصلب يوم الجمعة والقيامة يوم الأحد ) ، على أن يرتبطا بيوم 14 نيسان ( الفصح اليهودي ) . وجمع لهذا الغرض علماء الإسكندرية الفلكيين ، وبينهم بطليموس الفلكي الفرماوى ، ووضع بواسطتهم حساب الابقطى ، المشهور بحساب الكرمة ، والذي بموجبه أمكن معرفة يوم عيد الفصح اليهودي ( ذبح الخروف ) فى أية سنة من السنوات المصرية القبطية ، وحدد يوم الأحد التالي له عيدا للقيامة . وبهذا ينفذ ما أوصى به الرسل ألا يكون الفصحان اليهودي والمسيحي فى يوم واحد . وقد أقر المجمع المسكوني الأول المنعقد فى نيقية سنة 325 م هذا الرأي وكلف الإسكندرية بإصدار منشور عن العيد كل سنة . الرب يحرسنا من غواية الشيطان ببركة صلاة القديسين . آمين ." } },
      { kind: 'reading', text: { en: "The dispute on the feast of the Christian Passover (Easter) started between Asia Minor and Rome. Polycarp, Bishop of Smyrna, publicly announced the need of keeping the 14th of Neesan to commemorate the Crucifixion and the 16th of Neesan to commemorate the Resurrection (These were the original dates that the Crucifixion and Resurrection fall on regardless what day of the week they fell on) and the Christians of Mesopotamia, Cilicia, and Syria followed his opinion.", ar: "" } },
      { kind: 'reading', text: { en: "Victor, Bishop of Rome, publicly announced the importance of putting into consideration that the Crucifixion be on a Friday and the Resurrection be on a Sunday, (since Friday is the day of the Crucifixion and Sunday is the day of the Resurrection). The Christians of Egypt, Greece, Pontus and Arabia agreed with him in that. The dispute between the two bishops intensified, nevertheless their friendship remained unchanged.", ar: "" } },
      { kind: 'reading', text: { en: "Alexandria intervened in this subject, and its Patriarch Anba Demetrius the vine dresser (El-Karram), tried to mediate between these two opinions (By making the commemoration of the Crucifixion on Friday and the Resurrection on Sunday), and to be linked to the day 14th of Neesan (The Jewish Passover).", ar: "" } },
      { kind: 'reading', text: { en: "Pope Demetrius gathered the Alexandrian astronomers, among them was Ptolemy the astronomer which was from Farma, and with their help the Patriarch established the reckoning of the Epacts, which is known by the reckoning of El-Karmah. The reckoning of the Epacts was able to determine the day of the Jewish Passover (The slaughter of the Lamb) in any Egyptian Coptic year, and fix the Sunday after to be the Feast of Resurrection. This way he fulfilled what the Apostles commend that the Jewish Passover and the christian one not to be on the same day.", ar: "" } },
      { kind: 'reading', text: { en: "The first Universal council that convened in Nicea, 325 A.D. approved that view and asked the Alexandrian Pope to issue a message on the feast and its date every year.", ar: "" } },
      { kind: 'reading', text: { en: "May the Lord Guard us against the enticement of Satan, with the blessing of the prayers of the saints. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Haboulyous (Hanulius) the prince.", ar: "استشهاد القديس هانوليوس الأمير" } },
      { kind: 'reading', text: { en: "On this day also St. Haboulyous (Hanulius) the prince of the city of Perga in Pamphylia was martyred. The love of this prince for Christ made him publicly confess his faith. Barnabakhas the Governor arrested him at Diocletian's command. He confessed the Lord Christ before him giving the Lord the honor with glorious hymns then he cursed the idols. The Prince became raged and ordered him to be crucified. The Saint praised Christ that made him worthy to be martyred in His Name. Then he delivered his soul in the hand of the Lord and received the crown of martyrdom.", ar: "في مثل هذا اليوم استشهد القديس الطوباوي هانوليوس الأمير فى مدينة برجة (أنظر أع 13 : 13،14 : 25) من أعمال بمفيلية . وهذا الأمير دفعته محبته للمسيح أن يجاهر بأيمانه . فقبض عليه بارنباخس الأمير من قبل دقلديانوس فاعترف أمامه بالسيد المسيح معطيا إياه المجد بالتراتيل البهية . ثم ذم الأصنام ولعنها . فغضب عليه الأمير وأمر أن يصلب على خشبه فسبح المسيح الذي أهله للشهادة علي اسمه. ثم أسلم روحه بيد الرب ونال إكليل الشهادة. صلاته تكون معنا . ولربنا المجد دائم . آمين ." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God for ever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-5",
    title: { en: "Baramhat 5", ar: "5 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of Anba Serapamon, Archpriest of Abba Yehnis (John) monastery.", ar: "نياحة الانبا صرابامون أسقف دير انبا يحنس" } },
      { kind: 'reading', text: { en: "On this day the ascetic holy father Anba Serapamon the Archpriest of Abu-Yehnis (John) monastery departed. This Saint became a monk in his youth at the monastery of the saint Abu-Yehnis. He stayed there for thirty two years in worshipping God and serving the elders. Then he was promoted to be the archpriest (Heagomain) of the monastery and was delegated to manage it. He added to his works of righteousness and ascetism, and he spent his day fasting from the day of his monkshood until the day of his departure. After spending twenty years in running the monastery, he shut himself up in a church and no one saw him for a period of ten years. During this period he only ate on Saturday and Sunday.", ar: "فى مثل هذا اليوم تنيح الأب القديس الناسك العابد الأنبا صرابامون قمص دير أبو يحنس . وقد ترهب هذا القديس منذ صغره فى دير القديس أبو يحنس . ومكث فى العبادة وخدمة الشيوخ اثنتين وثلاثين سنة ، ثم رسم قمصا على الدير وأوكلوا إليه أمر تدبيره ، فتزايد فى بره ونسكه ، وكان يقضى نهاره صائما ، من يوم ترهبه إلي يوم نياحته ، وبعد أن قضى فى تدبير الدير عشرين سنة حبس نفسه فى إحدى (الكنائس ولم يعد يراه أحد مدة عشر سنوات . وكان فى هذه المدة لا يفطر إلا فى يومي السبت والأحد فقط . ولما دنت أيام وفاته ظهر له ملاك الرب أ! وقدم له صليبا من نار قائلا من نار قائلا : &quot;( خذ هذا بيدك &quot; . فقال له : * كيف أستطيع أن أمسك النار بيدي ! . فاجابه الملاك قائلا : &quot; لأتخف فلا يجعل المسيح سلطانا لها عليك. فمد يده وتناول الصليب من الملاك . ثم قال له الملاك : ( تقو وتقرب من الأسرار وبعد ثلاثة أيام آتي وآخذك &quot; . ولما استيقظ من نومه اعلم الشيوخ بالرؤيا فبكوا وودعوه طالبين منه أن يذكرهم .فطلب منهم أن يذكروه فى صلواتهم . وتنيح فى اليوم الثالث ، والشيوخ حوله . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "When the time of his departure drew near, the angel of the Lord appeared to him in a vision and gave him a cross of fire saying: \"Take this cross in your hand\". The saint replied: \" How can I hold fire in my hands.\" The angel said: \"Do not be afraid for Christ have not given the fire dominion over you.\" The Saint extended his hand and took the cross from the angel. Then the angel told him: \"Be strong, partake of the Holy Mysteries and after three days I shall come and take you\".", ar: "" } },
      { kind: 'reading', text: { en: "When he woke up from his sleep, he told the elders about his vision. They wept, bid him farewell, and asked him to remember them. He asked them to remember him in their prayers. He departed on the third day and the elders were around him.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "Commemoration of the Martyrdom of St. Eudexia (Eutychia).", ar: "استشهاد القديسة ادوكسية" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of St. Eudexia which is interpreted \"happiness\". This Saint was Samaritan by race and religion, from the city of Baalbek. The name of her father was Younan and the name of her mother was Hakeemah. She lived her early life in immorality. With the beauty of her face and physical appearance, she stumbled many and made them to fall into sin acquiring thereby great wealth.", ar: "فى مثل هذا اليوم تذكار القديسة أوذوكسية التى تفسيرها مسرة. هذه القديسة كانت سامريه المذهب ، من أهل بعلبك ، واسم أبيها يونان ، واسم أمها حكيمة . وعاشت أوذوكسية فى أول عمرها غير طاهرة . حيث كانت بجمال وجهها وحسن قوامها تعثر الكثيرين ، وتوقعهم فى الخطية ، حتى أقتنت مالا كثيرا . وسمع بها راهب قديس من أهل القدس يسمى جرمانس فذهب إليها ووعظها بالأقوال الرهيبة المخيفة ، وذكر لها جهنم والدود والظلمة وأنواع العذابات المؤلمة . فسألته : &quot; وهل بعد الموت تقام هذه الأجساد بعد أن تصير ترابا وتحاسب ؟ ) فقال لها : &quot; نعم . قالت : &quot; وما دليل قولك! ولم تذكره التوراة التى أعطاها الله لموسى النبي ، ولا قال به آبائي ؟ فأوضح لها ذلك بالبراهين الكتابية والعقلية ، حتى ثبت قوله فى عقلها، واقتنعت ، ثم قالت له : وهل إذا رجعت عن أفعالى الذميمة هذه يقبلني الله إليه ؟ ، فأجابها : &quot; ان أنت آمنت بالسيد المسيح انه قد جاء الى العالم ، وانه حمل خطايانا بصلبه عنا وتبت الآن توبة صادقة ، وتعمدت ، فأنه يقبلك ، ولا يذكرلك شيئا مما صنعت ، بل تكونين كأنك ولدت الآن من بطن أمك &quot; : فانفتح قلبها للأيمان ، وطلبت منه إتمام ذلك . فأخذها الى أسقف بعلبك . وأقرت أمامه بالثالوث المقدس وبتجسد الكلمة وصلبه . وحينما وقف يصلى على الماء لتعميدها ، فتح الرب عقلها ، فرأت ملاكا يجذبها الى السماء ، وملائكة آخرين مسرورين بذلك . ثم رأت شخصا مفزعا أسود قبيح المنظر يجتذبها منهم وهو حانق عليها . فزادها مار أته رغبة فى العماد والتوبة . ولما تعمدت فرقت ما كانت جمعته من ثمرة الآثم على الفقراء والمساكين ، وذهبت الى دير الراهبات ، ولبست زي الرهبنة وهناك جاهدت جهادا كاملا . فدخل الشيطان فى بعض أصدقائها ، وأعلموا الأمير بأمرها ، فاستحضرها ، ولما حضرت وجدت فى بيته جنازة وبكاء على ابنه .فدخلت إليه وصلت على ابنه ، وطلبت من السيد المسيح من أجله فأقامه من الموت . فآمن الأمير بالمسيح على يدها . وسمع بها أمير آخر يدعى ديوجانس ، فاستحضرها فأبصرت أمامه جنديا فاقد بصر إحدى عينيه . فصلت وصلبت عليها، فأبصر فأطلق الأمير سراحها . وبعد مدة تولى أمير آخر يسمى بيكفيوس (ورد فى مخطوط بشبين الكرم ( بلنفيوس ) وبلغه خبرها فاستحضرها ، فسالت السيد المسيح أن يجعل لها حظا مع الشهداء . فأمر الأمير بقطع رأسها بالسيف ، ونالت إكليل الشهادة . شفاعتها تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "A saintly monk from Jerusalem called Germanus heard about her. He went to her, preached her with solemn and frightful words, mentioning to her hell, worms, darkness, and the fearful punishments which are therein. She asked him: \"Does the body rise after death, and after it becomes dust to be judged?\" He replied \"Yes\". She asked him: \"What are the proofs on what you said, since the Torah that God gave to\nand my fathers did not mention this?\" He explained to her with biblical and logical proofs until she was convinced. She asked him: \"If I go back on my evil works would God accept me?\" He replied: \"If you believed that the Lord Christ had come to the world, took away our sins by His Crucifixion, repented now a sincere repentance, and been baptized, He will accept you, and will not mention any of what you have done, but you will be as if you just have been borne.\"", ar: "" } },
      { kind: 'reading', text: { en: "Her heart opened to the faith and asked him to help her to fulfil that. He took her to the bishop of Baalbek and she confessed before him the Holy Trinity, the incarnation of the Word and His Crucifixion. While the Bishop was praying over the water to baptize her, the Lord opened her mind, she saw an angel attracting her to the water and the other angels were rejoicing for her. Then she saw an ugly terrifying looking person trying to drag her away from them and he was in wrath with her. What she saw increased her desire for repentance and baptism.", ar: "" } },
      { kind: 'reading', text: { en: "After her baptism, she gave all what she gained as fruit of her sin to the poor and needy. She entered a convent of nuns, she put on the garb of monasticism, and fought a good and perfect fight. Satan entered into some of her friends who informed the Governor about her. The Governor commanded his men to bring her. When she came into his house she found great lamentation and weeping for the governor's son had just died. She came to where the son was laid, prayed entreating the Lord Christ for his sake and He raised him up from death. The Prince believed in Christ through her. Another prince called Diogenes heard about her. He brought her before him, and she saw a soldier standing before him, who was blind in one eye, she prayed and made the sign of the cross over the eye, and it was opened. The prince released her instantly.", ar: "" } },
      { kind: 'reading', text: { en: "Shortly after this, another Prince called Bekeyfius was appointed, and he heard about her and had her brought to him. She asked the Lord Christ to give her a portion with the martyrs. The Prince commanded to cut off her head, and she received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "May her intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Peter the priest.", ar: "نياحة القديس بطرس القس" } },
      { kind: 'reading', text: { en: "On this day also the honorable presbyter St. Peter departed. This father spent his life fasting, he shut himself in and was disciplined in praying days and nights. The Lord granted him the gift of knowing the future, healing the sick through the water and oil after praying over them. He was ordained a priest, after much reluctance, and he was forced to obey the order. He offered the incense and celebrated the Liturgy daily. The people of the city rejoiced saying: \"May the Lord grant us the forgiveness of our sins with his prayers and supplications.\" He had a wonderful power of reconciling persons at variance.", ar: "فى مثل هذا اليوم تنيح القس الجليل القديس بطرس وكان هذا الأب يقضى كل زمانه صائما وكان يحبس نفسه ويلتزم إقامة الصلوات فى الليل والنهار فوهبه الله نعمة العلم بالغيب ، وشفاء المرضي بالماء والزيت بعد الصلاة عليهما . وقد رسم قسا بعد امتناع كبير ، حتى اضطر الى الخضوع للأمر . وكان يقوم برفع البخور واقامة القداس يوميا . وكان أهل المدينة فرحين به قائلين ان الله يهبنا مغفرة خطايانا بصلاته وتضرعاته . وكان من عاداته المأثورة أنه إذا سمع بان اثنين من أبناء الكنيسة متخاصمان أسرع الى إقامة الصلح بينهما . وكان متحليا بالصفات الكاملة . وفى أثناء صلاته ذات ليلة ظهر له بطرس الرسول ، وقال له : &quot; السلام لك يأمن حفظت الكهنوت بلا عيب . السلام لك وعليك يأمن صعدت صلواته وقداساته كرائحة الطيب العطرة &quot; . أما هو فلما رآه فزع وخاف منه . فقال له : &quot;( أنا بطرس الرسول ، لا تخف ولا تجزع ، لأن الرب أرسلني لأعزيك وأعرفك أنك ستنتقل من هذه الدنيا المتعبة الى الملكوت الأبدى . فأبشر بذلك وتعز ! ففرح القس بذلك وقال : &quot; اذكرني يا أبى &quot; ولما قال هذا تنيح بمجد وكرامة وسعادة . رحمنا الله بصلواته وبركاته . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "During his prayer one night, St. Peter the apostle appeared to him and told him: \"Hail to you for you have kept the priesthood without blemish. Hail to you for your prayers and masses had ascended as sweet aroma.\" When the Saint saw him, he was terrified. St Peter told him: \"I am the apostle Peter, do not be afraid for the Lord has sent me to comfort you and to inform you that you are leaving this toilsome world to the Eternal kingdom, so rejoice and be comforted.\" The priest rejoiced for that and said \"Remember me O My Father.\" When he said that he departed in happiness, glory and honor.", ar: "" } },
      { kind: 'reading', text: { en: "May the Lord have mercy on us with his prayers and blessings and Glory be to God for ever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-6",
    title: { en: "Baramhat 6", ar: "6 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Dioscorus.", ar: "استشهاد ديسقورس فى زمن العرب" } },
      { kind: 'reading', text: { en: "On this day, St. Dioscorus was martyred at the time of the Arabs. He was from Alexandria, and was brought up as Christian but for unexplained reason he left the faith of his fathers and adopted the faith of the Arabs. He had a married sister in the city of Fayyum. When she knew what her brother did, she sent a letter to him saying: \"I would have preferred that the news had come to me telling me that you had died a Christian, and I would have rejoiced, than that the news that reached me, that you are not dead, and you have abandoned the Faith of Christ your God.\" At the end she said: \"Know that this letter marks the end of the relation between you and me. From this time on do not show me your face and do not write me.\"", ar: "فى مثل هذا اليوم استشهد القديس ديسقورس فى زمان العرب وكان من مدينة الإسكندرية ، وحدث له ما دعا الى خروجه من دين آبائه ودخوله فى دين العرب . . ومكث كذلك مدة من الزمان . وكانت له أخت متزوجة بمدينة الفيوم . إذ علمت بما صار إليه أرسلت له قائلة : &quot; لقد كنت اشتهى أن يأتيني خبر موتك وأنت مسيحي ، فكنت أفرح بذلك ، ولا يأتيني خبرك بأنك قد تركت المسيح إلهك &quot; . وختمت كلامها بقولها : &quot; واعلم أن هذا الكتاب آخر صلة بيني وبينك ، فمن الآن لاتعد ترينى وجهك ولا تكاتبنى ، . فلما قرأ كتاب أخته بكى بكاءا مرا ، ولطم وجهه ونتف لحيته ثم قام مسرعا وشد وسطه بزنار ، وصلى متضرعا بحرارة ، ورشم نفسه بعلامة الصليب ، وخرج يسير فى المدينة . وأبصره الناس على هذه الحال فاقتادوه الى الوالي وهذا قال له : &quot; لقد تركت دين النصارى ودخلت فى ديننا ، فما الذي جرى ! ؟ فأجابه قائلا : &quot; أنا ولدت مسيحيا وأموت مسيحيا ، ولا أعرف دينا غير هذا &quot; . فهدده كثيرا وضربه ضربا موجعا ، فلم يرجع عن رأيه ، فأودعه السجن ، وأرسل الى ملك مصر يعرض عليه حالته أمره أن يعرض عليه الخروج من دين النصارى والدخول فى دين الملك . فان أطاع وهبه هبات جزيلة ، وإلا فيحرقه . فأخرجه من الحبس وعرض عليه الجحود فأبى قائلا : &quot; لقد قلت سابقا ولدت مسيحيا وأموت مسيحيا &quot; . فأمر بحرقه . فحفروا له خارج المدينة حفرة كبيرة ، وملأوها بالحطب وأوقدوها . ولما علا لهيبها فى طرحوه فيها بعد أن ضربه أهل البد ضربا موجعا وطعنوه بالسكاكين . فنال إكليل الشهادة في ملكوت السموات. صلاته تكون معنا . آمين . 2 – وفى مثل هذا اليوم أيضا : تذكار نياحة القديس ثاؤضوطس (ورد فى مخطوط بشبين الكوم &quot; طاوطوس &quot;) أسقف مدينة قورنثية التي في جزيرة قبرص . وقد عذب كثيرا أيام الاضطهاد . وذلك أن يوليوس حاكم هذه الجزيرة من قبل دقلديانوس استحضر هذأ القديس وطلب ! منه أن ينكر المسيح ، ويقدم البخور للأصنام . وإذ لم يذعن لأمره نزع عنه ثيابه ، وضربه ضربا شديدا موجعا بسياط من جلد البقر ، ثم علقه ومشط جسمه بأمشاط من حديد ثم سمر جسمه بالمسامير وجروه الى الحبس . فمكث فيه الى أن أهلك الله دقاديانوس وتملك قسطنطين البار . فأطلقه مع جملة المحبوسين . فرجع الى كرسيه ورعى رعيته التى أؤتمن عليها الى أن تنيح بسلام . شفاعته تكون معنا. ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "When he had read his sister's letter, he wept bitterly, and he smote his face and tore his beard. Then he rose in haste and girded up his loins, prayed entreating God fervently and made the sign of the cross over himself. He went out of his house and wandered about in the city.", ar: "" } },
      { kind: 'reading', text: { en: "When the Muslims saw him in this condition, they brought him to the Governor who asked him: \"You have left Christianity and joined our religion, so what happened to you?\" He replied saying \"I have been born Christian, and I shall die Christian, and I do not know except this.\" The Governor threatened him, beat him and inflicted great pain upon him and when he did not change his opinion, he shut him up in prison. The Governor sent to the Khalifa of Egypt presenting his case to him. The Khalifa ordered the governor to offer him leaving the faith of the Christians and entering the faith of the Khalifa, if he obeyed to give him much money and to reward him, otherwise to burn him. The Governor brought him out of jail and asked him to deny his faith but he refused saying: \"I told you before that I have been born Christian, and I shall die Christian.\" He ordered him to be burnt. They dug a large pit outside the city, and they filled it with wood and they set fire in it. When the flames of the fire mounted up to a great height, they casted him in the pit after they had beaten him sorely and gashed his body with knives. He received the crown of martyrdom in the kingdom of heaven.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Theodotus, the bishop.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the departure of St. Theodsius the confessor, Bishop of Corinth which on the island of Cyprus. Julius, the Governor of this island, who had been appointed by Diocletian, had him brought before him. He demanded from him to deny the Lord Christ and to raise incense to the idols. When he did not obey his orders, he removed off the Saint's garments and lashed him painfully with whips made of buffalo hide, hanged him from his arms, and combed his body with steel combs inflicting him with gashes all over his body. Then they tied to his legs long iron bands, and dragged him to prison. He remained in prison until God perished Diocletian and Constantine the righteous Emperor reigned, who released him among all those who had been jailed for the sake of faith. St. Theodsius returned to his Episcopal Seat, and tended his flock, that he was entrusted with, well until he departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his intercession be with us and Glory be to God for ever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-7",
    title: { en: "Baramhat 7", ar: "7 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of Sts. Philemon and Apollonius.", ar: "استشهاد انبا فليمون المغنى وانبا ابلابيوس" } },
      { kind: 'reading', text: { en: "On this day Sts. Philemon and Apollonius were martyred. Philemon was the jester and singer, and Apollonius was the musician for the governor of Ansena (Antinoe). They were very close friends and they wished to receive the crown of martyrdom. One day, Philemon went to the Governor and confessed the Lord Christ before him, so he ordered to shoot him with arrows. After that, Apollonius came before the Governor and he also confessed the Lord Christ. When the Governor recognized him he became angry and ordered to shoot him also with arrows. While they were shooting Apollonius, one of the arrows glanced back and struck the Governor's eye and destroyed it. Sts. Philemon and Apollonius completed their strife and received the crown of martyrdom.", ar: "في مثل هذا اليوم استشهد القديسان فيليمون وابلانيوس . وفيليمون هذا كان مغنيا لأريانوس والى انصنا ، وكان ابلانيوس مزمرا ، وكانا صديقين حميمين . واشتهيا أخذ اكليل الشهادة فدخل فيليمون يوما على الوالي واعترف بالسيد المسيح أمامه فأمر أن يرموه بالسهام . وحدث أن دخل بعده القديس ابلانيوس وفى يده المزمار ، واعترف هو أيضا بالسيد المسيح . فلما عرفه الوالي غضب جدا وأمر أن يرموه بالسهام هو الآخر . وفى أثناء ذلك رجعت السهام الى ناحية الوالي فأصابت عينه فقلعتها . أما القديسان فقد أكملا جهادهما ونالا اكليل الشهادة . صلاتهما تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Mary the Israelite.", ar: "استشهاد مريم الاسرائيلية" } },
      { kind: 'reading', text: { en: "On this day also St. Mary the Israelite was martyred. This Saint did not know the Lord Christ and she lived an evil life. When she wished to repent and to return to the righteous life, the Lord sent to her a holy man who preached her, and revealed to her", ar: "فى مثل هذا اليوم استشهدت القديسة مريم الإسرائيلية . ولم تكن هذه القديسة تعرف السيد المسيح ، وكانت رديئة السيرة ، ولما أرادت التوبة والرجوع الى السيرة الصالحة أرسل لها الرب رجلا قديسا قام بوعظها ، وعرفها طريق الخلاص بالإيمان بالسيد المسيح وقال لها ان النفس لابد أن تعطى جواب عن جميع أعمالها في يوم القيامة وانها بعد الموت وفراق هذا. العالم ستحاسب عما فعلت. فقالت له : (&quot; ما هو الدليل على قولك هذا الذي نحم تذكره التوراة الذي أعطاه الله لموسى النبي ، كما لم يقل بهذا آبائي فأثبت لي صحة قولك بالبراهين الشرعية والعقلية فأثبت لها ما طلبت . ولما ثبتت أقواله في عقلها قالت : &quot; ان تبت عن أعمالي النجسة فهل يقبلني الله ؟ فأجابها&quot; ان آمنت بأن المسيح جاء الى العالم لخلاص البشر ،وسلكت سبيل التوبة ، يقبلك الله ا . فآمنت وتابت . ثم لما بلغ خبرها للوالى أحضرها أمامه فأصرت علي مسيحيتها فأمر بقطع رأسها بحد السيف . ونالت اكليل الشهادة . شفاعتها تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "the way of salvation by believing in the Lord Christ. He told her that the soul has to give an answer about all her deeds on the day of Resurrection. After death and departing of this world every one will be rewarded according to his deeds and explained to her the fearful punishments for the evil doers. She asked him: \"What are the proofs on what you said, since the Torah that God gave to\nand also my fathers did not mention this? so confirm to me the truth of what you said with biblical and logical proofs\".", ar: "" } },
      { kind: 'reading', text: { en: "After he explained and confirmed to her all these facts she became convinced in her heart and mind. She asked him: \"If I repent on my evil works would God accept me?\" He replied: \" If you believed that Christ had come to the world for the salvation of the human race, and walked in the way of repentance, God will accept you\" and she believed and repented. When the Governor knew about her, he brought her before him. When she insisted on her Christianity, he ordered her beheaded by the sword and she received the crown of martyrdom.", ar: "" } },
      { kind: 'reading', text: { en: "May her intercession be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "تذكار استشهاد مينا فى زمن العرب" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار استشهاد مينا فى زمن العرب . صلاته تكون معنا و لربنا المجد دائما ابديا امين ." } }
    ],
  },
  {
    id: "synax-baramhat-8",
    title: { en: "Baramhat 8", ar: "8 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Julian, the Eleventh Pope of Alexandria.", ar: "استشهاد البابا يوليانوس الاسكندرى" } },
      { kind: 'reading', text: { en: "On this day also of the year 188 A.D. (3rd of march) the holy father Pope Julian the Eleventh Pope of Alexandria departed. This father was a student in the seminary established by St. Mark, and was ordained priest in the city of Alexandria. He surpassed many in knowledge, righteousness, and purity so he was ordained Patriarch on the\n9th of Baramhat (Year 178 A.D.) After his enthronement he saw that the pagans did not allow the bishops to leave the city of Alexandria, so he used to leave the city in secret to ordain priests everywhere.", ar: "فى مثل هذا اليوم من سنة 188 م ( 3 مارس ) تنيح الأب القديس يوليانوس البابا إلحادي عشر من باباوات الكرازة المرقسية . كان هذا الأب طالبا بالكلية الاكليريكية التى أسسها مار مرقس ، ورسم قسا بمدينة الإسكندرية ، وقد فاق الكثيرين بعلمه وعفافه وتقواه . فرسم بطريركا في 9 برمهات ( سنة 178 م ) .وبعد اختياره رأى أن الوثنيين لا يسمحون للأساقفة بالخروج عن مدينة الإسكندرية . فكان هو يخرج سرا منها ليرسم كهنة في كل مكان . وقبل انتقاله أعلنه ملاك الرب أن الكرام الذي يأتيه بعنقود عنب ، هو الذي سيخلفه في كرسى البطريركية . وفى ذات يوم بينما كان ديمتريوس الكرام يشذب أشجاره ، عثر على عنقود عنب في غير أوانه ، وقدمه للبطريرك فسر من هذه الهدية ، وقص على الأساقفة الرؤيا، وأوصاهم بتنصيب الكرام بطريركا بعده . وقد وضع هذا الأب مقالات وميامر كثيرة، وكان مداوما على تعليم الشعب ووعظه وافتقاده ، وأقام على الكرسى الرسولى عشر سنين . ثم تنيح بسلام . صلاته تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "Before his departure the angel of the lord announced to him that the one who will bring him a cluster of grapes, is the one to succeed him on the Patriarchal Chair. One day, while Demetrius the vine dresser was trimming his trees, he found a cluster of grapes and was not in season. He took the cluster and gave it to the Patriarch Abba Julian who was pleased with the present. He gathered the bishops and told them about the vision and commanded them to enthrone him Patriarch after him.", ar: "" } },
      { kind: 'reading', text: { en: "This father composed many homilies and discourses, he taught the people continually, preached and visited them. He stayed on the Apostolic Chair for ten years then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Matthias, the apostle.", ar: "استشهاد متياس الرسول" } },
      { kind: 'reading', text: { en: "On this day St. Matthias, the apostle was martyred about 63 A.D. He was born in Bethlehem, followed the apostles and was chosen in place of Judas Iscariot in the upper room on the mount of Zion. Peter stood up in the midst of the disciples (altogether the number of names was about a hundred and twenty), and said, \"Men and brethren, this Scripture had to be fulfilled, which the Holy Spirit spoke before by the mouth of\nconcerning Judas, who became a guide to those who arrested Jesus; \"for he was numbered with us and obtained a part in this ministry.\" (Now this man purchased a field with the wages of iniquity; and falling headlong, he burst open in the middle and all his entrails gushed out. And it became known to all those dwelling in Jerusalem; so that field is called in their own language, Akel Dama, that is, Field of Blood.) \"For it is written in the book of Psalms: 'Let his habitation be desolate, and let no one live in it'; and, 'Let another take his office.' \"Therefore, of these men who have accompanied us all the time that the Lord Jesus went in and out among us, \"beginning from the baptism of John to that day when He was taken up from us, one of these must become a witness with us of His resurrection.\" And they proposed two: Joseph called Barsabas, who was surnamed Justus, and Matthias. And they prayed and said, \"You, O Lord, who know the hearts of all, show which of these two You have chosen \"to take part in this ministry and apostleship from which Judas by transgression fell, that he might go to his own place.\" And they cast their lots, and the lot fell on Matthias. And he was numbered with the eleven apostles. (Acts 1:15-26)", ar: "في مثل هذا اليوم تنيح القديس متياس الرسول حوالى سنة 63 م . ولد في بيت لحم ، وكان من المرافقين للرسل ؟ وهو الذي اختير عوض يهوذا الاسخريوطي في اجتماع علية صهيون عندما قال بطرس الرسول &quot;- أيها الرجال الاخوة ؟ كان ينبغي أن يتم هذا المكتوب الذي سبق الروح القدس فقاله بفم داود عن يهوذا الذي صار دليلا للذين قبضوا على يسوع . إذ كان معدودا بيننا وصار له نصيب في هذه الخدمة . فان هذا اقتنى حقلا من أجرة الظلم وأذ سقط على وجهه من الوسط فانسكبت أحشاؤه كلها. وصار معلوما عند جميع سكان أورشليم حتى دعي ذلك الحقل في لغتهم حقل دم . لأنه مكتوب في المزامير لتصر داره خرابا ولا يكن فيها ساكن وليأخذ وظيفته آخر . فينبغى أن الرجال الذين اجتمعوا معنا كل الزمان الذي فيه دخل إلينا الرب يسوع وخرج . منذ معمودية يوحنا إلى اليوم الذي ارتفع فيه عنا يصير واحد منهم شاهدا معنا بقيامته . فأقاموا اثنين يوسف الذي يدعى بارسابا الملقب يوستس ( آي عادل ) ومتياس . وصلوا قائلين : أيها الرب العارف قلوب الجميع عين أنت من هذين الاثنين أيا اخترته ، ليأخذ قرعة هذه الخدمة والرسالة التى تعداها يهوذا ليذهب إلى مكانه . ثم ألقوا قرعتهم فوقعت القرعة على متياس فحسب مع الأحد عشر رسولا &quot; (مت 27 : 8 و أع 1 :15 - 26) . وبعد ذلك امتلأ متياس من الروح القدس . وذهب يكرز بالإنجيل حتى وصل إلى بلاد قوم يأكلون لحوم البشر . ومن عادتهم أنهم عندما يقع في أيديهم غريب يضعونه في السجن ، ويطعمونه من الحشائش مدة ثلاثين يوما ، ثم يخرجونه ويأكلون لحمه . فلم وصل اليهم القديس متياس ونادى فيهم ببشارة المحبة قبضوا عليه ، وقلعوا عينيه ، وأودعوه السجن . ولكن قبل أن تنتهى المدة أرسل إليه الرب اندراوس وتلميذه . فذهبا إلى السجن ورأيا المسجونين وما بعمل بهم . فأوعز الشيطان إلى أهل المدينة أن يقبضوا عليهما أيضا ويقتلوهما . ولما هموا بالقبض عليهما ا صلى القديسان إلى الرب فتفجرت عين ماء من تحت أحد أعمدة السجن . . وفاضت حتى بلغت إلى الأعناق . فلما ضاق الآمر بأهل المدينة ، ويئسوا من الحياة أتوا إلى الرسولين ، وبكوا معترفين بخطاياهم . فقال لهم الرسولان آمنوا بالرب يسوع المسيح وأنتم تخلصون . فأمنوا جميعهم وأطلقوا القديس متياس وهذا تولى مع اندراوس وتلميذه تعليمهم سر تجسد المسيح بعد أن انصرفت عنهم تلك المياه بصلاتهم وتضرعهم ثم عمدوهم باسم الثالوث المقدس . وصلوا إلى السيد المسيح فنزع منهم الطبع الوحشي ، ورسموا لهم أسقفا وكهنة ، وبعد أن أقاموا عندهم مدة تركوهم ، وكان الشعب يسألونهم سرعة العودة . أما متياس الرسول فانه ذهب إلى مدينة دمشق ونادى فيها باسم المسيح فغضب أهل المدينة عليه وأخذوه ووضعوه على سرير حديد وأوقدوا النار تحته فكم تؤذه ، بل كان وجهه يتلألأ بالنور كالشمس . فتعجبوا من ذلك عجبا عظيما وآمنوا كلهم بالرب يسوع المسيح على يدى هذا الرسول ، فعمدهم ورسم لهم كهنة . وأقام عندهم أياما كثيرة وهو يثبتهم على الأيمان . وبعد ذلك تنيح بسلام في إحدى مدن اليهود التى تدعى فالاون . وفيها وضع جسده صلاته تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "Afterwards he was filled with the Holy Spirit, and went to preach the Gospel until he came to the country of cannibals. The custom of those people was whenever they seized a stranger, they put him in prison for thirty days feeding him grass, then they bring him out and eat him. When St. Matthias came to them and preached among them the massage of love they seized him, plucked out his eyes and put him in prison. Before the thirty days were over God sent to him\nand his disciple. They came to the prison and saw the prisoners and what abominable things the people of the city did to them. Satan inspired the people of the city to seize them also and kill them.", ar: "" } },
      { kind: 'reading', text: { en: "When they were about to seize them, the two Saints prayed to the Lord, and a stream of water flowed from under one of the pillar of the prison. The water flowed out into the city, and rose up until it reached the necks of the people. When the people of the city gave up all hope of saving their lives, they came to the apostles, and wept before them confessing their sins. The apostles told them \"Believe in the Lord Jesus Christ, and you shall be saved.\" They all believed and they released St. Matthias.", ar: "" } },
      { kind: 'reading', text: { en: "St. Matthias, along with St. Andrew and his disciple taught them the mystery of the Incarnation of the Lord Christ. The Apostles prayed and entreated God Who made the water to cease then they baptized them in the Name of the Holy Trinity. They also prayed to The Lord Christ Who removed from them their barbaric nature. The Apostles appointed over them bishops and priests. They tarried with them for a while during which they instructed them and confirmed them in the faith, then they left. The people of the city entreated them to come back to them speedily.", ar: "" } },
      { kind: 'reading', text: { en: "St. Matthias went to the city of Damascus and preached there in the Name of the Lord Christ. The people of the city became angry so they took him and laid him upon an iron bed, they lighted a fire under it which did not harm him but his face was shining with light like the sun. They marvelled exceedingly and they all believed on the Lord Christ through St. Matthias the apostle who baptized them, and appointed priests for them. He tarried many days with them confirming them in the faith. Afterward he departed in peace in one of the city of the jews called Falawon (Pilawon) where his body was laid.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Arianus, the Governor of Ansena.", ar: "استشهاد اريانوس والى انصنا" } },
      { kind: 'reading', text: { en: "On this day also St. Arianus, the governor of Ansena was martyred. When he ordered to shoot\nwith arrows, and one of the arrows glanced back and struck his eye and destroyed it, as it is mentioned in the Seventh day of Baramhat, one of the believers told him: \"If you take some of his blood and smear your eye with it, you will receive your sight.\" The Governor took some of his blood, smeared his eye, and immediately he was able to see. Arianus believed on the Lord Christ, with great sorrow for all the evil things which he had done to the holy martyrs and the severity with which he tortured them. Then he rose up, destroyed his idols, and he refrained from torturing any of the believers.", ar: "في مثل هذا اليوم استشهد القديس اريانوس والى انصنا . وذلك لما أمر برمى القديس ابلانيوس بالسهام وقد ارتدت إلى عينه فقلعتها كما هو مذكور في اليوم السابع من برمهات قال له أحد المؤمنين : &quot; لو أخذت من دمه ووضعت عينك لأبصرت &quot; فأخذ من دمه ووضعه على عينه فأبصر للوقت ، وآمن بالسيد المسيح وندم كثيرا على ما فرط منه في تعذيب القديسين . ثم قام وحطم أصنامه ، ولم يعد يعذب أحدا من المؤمنين . فلما اتصل خبره بالملك دقلديانوس استحضره واستعلم منه عن السبب الذي رده عن عبادة آلهته . فبدأ القديس يقص عليه الآيات والعجائب التى أجراها الله على أيدي قديسيه ، وكيف أنهم في حاك عذابهم وتقطيع أجسامهم كانوا يعودون أصحاء . . فاغتاظ الملك من هذا القول ، وآمر أن يعذب عذابا شيدا ، وأن يطرح في جب ويغطى عليه حتى يموت . فأرسل السيد المسيح ملاكه ، وحمله من ذلك الجب ، وأوقفه عند مرقد الملك . ولما استيقظ الملك ورآه وعرف أنه أريانوس ، ارتعب ودهش . ولكنه عاد فآمر بوضعه في كيس شعر وطرحه في البحر . ففعلوا به كذلك . وهنا أسلم الشهيد روحه داخل الكيس . وكان القديس عندما ودع أهله أخبرهم بأن الرب قد أعلمه في رؤيا الليل أنه سيهتم بجسده ، ويعيده إلى بلده ، وانهم سيجدونه في ساحل الإسكندرية . وحدث أن أمر الرب حيوانا بحريا فحمله إلى الإسكندرية وطرحه على البر ، فأخذه غلمانه وأتوا به إلى انصنا ، ووضعوه مع أجساد القديسين ئ فيليمون وأبلانيوس ، وهكذا أكمل جهاده ونال الإكليل السمائى . صلاته تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "When Diocletian heard the report of Arianus, he brought him, and asked him why he had forsaken the worship of his idols. Arianus began to tell him about the signs and wonders which God was working by the hands of the holy martyrs, and how, in spite of the tortures which he had inflicted upon them, and the cutting of their bodies, they rose up again whole. The Emperor became furious with him because of what he said and ordered him to be tortured severely, and to cast him into a pit and to cover it until he dies.", ar: "" } },
      { kind: 'reading', text: { en: "The Lord Christ sent His angel, who brought him out from the pit, and took him by the bed of the Emperor. The Emperor woke up from his sleep, and when he saw and recognized that he was Arianus, he was amazed and terrified. Diocletian again ordered him to be placed into a hair sack, and to cast him into the sea, so they did. Arianus the martyr delivered up his soul while he was in the hair sack. The Saint had told his kinsfolk when he bid them farewell that the Lord had told him in a vision of the night that He would take care of his body, return it to his town, and they could find it on the shore of Alexandria.", ar: "" } },
      { kind: 'reading', text: { en: "The Lord ordered a sea creature who carried the Saint, and brought him to the city of Alexandria, where it casted him on the shore. His men took his body, brought it to Ansena, and laid it with the bodies of the Saints Philemon and Apollonius. Thus, he finished his good fight and received the heavenly crown.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-9",
    title: { en: "Baramhat 9", ar: "9 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "نياحة القديس كوش المجاهد العظيم" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم تنيح القديس المجاهد كونن . كان هذا القديس من ضيعة أنيطانيوس من بلاد سوريا من أب - اسمه نسطر وأم اسمها ثاؤذورا ، كانا يعبدان الكواكب . وكان ذلك وقت تبشير التلاميذ باسم السيد المسيح له المجد . ولما كبر كونن ظهرت منه فضائل كثيرة كالعفة والطهارة والورع والرحمة . . وأراد والداه أن يزوجاه فأبي . ولكنهما أرغماه على ذلك وزوجاه . فلم يكن يهوى أن يعرف امرأته . فمكث الاثنان على ذلك الحال أبكارا . وكان كثيرا ما يقول في صلاته : أيها الإله أرشدني إلى معرفتك الحقيقية . فظهر له ملاك الرب ميخائيل ، وأمره أن يذهب إلي أحد الرسل . فمضى إليه وتعلم منه فرائض الدين المسيحى وتعمد وتناول السرائر الإلهية . ثم داوم * على سماع تعاليم الرسل . فازداد طهارة وعفة ونسكا وورعا وصلاة فمنحه الله موهبة عمل المعجزات والسلطان على الشياطين . فاجتذب أبويه وزوجته أيضا ووالديها إلى الإيمان بالسيد المسيح . ولما دخل أحد الكفار مرة إلى إحدى المغارات ليذبح للشيطان ، وعلم به هذا القديس صرخ فى الشيطان وانتهره أن يقر أمام الناس من هو ؟ فاعترف أنه شيطان وليس إلها . فصرخ الحاضرون قائلين : &quot; واحد هو اله القديس كونن &quot; . ثم آمنوا واعتمدوا . فسمع بخبره نائب الوالى كلوديوس قيصر، فاستحضره فأقر أمامه بالمسيح ، فربطه وضربه ضربا شيدا . وسمع بذلك أهل بلده ولمحبتهم له هرعوا إليه يريدون قتل الوالى فهرب منهم .أما هم فحلوا القديس بن رباطه وغسلوه من دمائه . وحملوه الى بلدهم . فعاش عدة سنين وانتقل الى الرب . فجعل المؤمنون داره كنيسة ووضعوا جسده فيها . وظهرت منه آيات وعجائب كثيرة . صلاته تكون .معنا . آمين" } },
      { kind: 'heading', text: { en: "", ar: "استشهاد القديسين أندريانوس ومرتا زوجته واوسابيوس والأربعين \r\nشهيدا" } },
      { kind: 'reading', text: { en: "", ar: "فى مثل هذا اليوم استشهد القديسون اندريانوس ومرتا زوجته وأوسابيوس وأرمانيوس وأربعون شهيدا ، بعد عذابات شديدة على اسم ربنا يسوع المسيح . صلاتهم تكون معنا ولربنا المجد دائما . آمين ." } },
      { kind: 'heading', text: { en: "The Departure of St. Konan.", ar: "" } },
      { kind: 'reading', text: { en: "On this day the fighter St. Konan departed. This Saint was from a city called Antanyos in the country of Syria during the days when the Apostles were preaching the Name of the Lord Christ to Whome is the glory. His father's name was Nestor, his mother's name was Theodora, and they worshipped the stars. When this Saint grew and became a man, the virtues of purity, chastity, piety, and mercy were manifested in his life.", ar: "" } },
      { kind: 'reading', text: { en: "His parents wished to wed him but he refused. They forced him to get married, but he refused to have any relation with his wife and both remained virgins. Often he prayed saying: \" O God lead me to Your true Knowledge.\" Michael, the angel of the Lord appeared to him and ordered him to go to one of the apostles. Konan went to him, learned from him all the Laws of the Christian Faith, was baptized and received the Divine Mysteries. He went on listening to the teachings of the Apostles and he increased in purity, chastity, ascetism, and praying. God granted him the gift of performing miracles and the authority over the devil, and he attracted his parents to the faith in the Lord Christ.", ar: "" } },
      { kind: 'reading', text: { en: "Once, one of the unbelievers went to one of the temples to offer a sacrifice to satan. St. Konan knew this man, and he cried out against satan, rebuked him and commanded him to confess before the people telling them whom he was. The devil confessed that he was satan and was not a god. All the people were present cried out saying: \"One is the God of St. Konan,\" and they believed and were baptized.", ar: "" } },
      { kind: 'reading', text: { en: "When the Governor, who had been appointed by Claudius Caesar, heard about this Saint, he had him brought before him, and the saint confessed his faith in the Lord Christ. The Governor commanded him to be bound and beaten very severely. When the people of the city heard that, and because of their love to the Saint, they wanted to kill the Governor but he fled from them. They released the Saint from his fetters, washed the blood off him, and carried him to their town. He lived for many years then departed to the Lord. The believers made his house a church and laid his body in it, from which many signs and wonders were manifested.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of Sts. Abrianus, Amrata his wife, Eusebius, Armanius, and the Forty Martyrs.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also was the martyrdom of Sts. Abrianus, Amrata his wife, Eusebius, Armanius, and the Forty Martyrs after they had been tortured severely in the Name of Our Lord Jesus Christ.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-10",
    title: { en: "Baramhat 10", ar: "10 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "Commemoration Of the Appearance Of The Glorious Cross.", ar: "ظهور الصليب على يد القديسة هيلانة الملكة سنة 326 م" } },
      { kind: 'reading', text: { en: "The church celebrates the appearance of the glorious Cross of Our Lord and Saviour Jesus Christ twice:", ar: "تحتفل الكنيسة بظهور الصليب الكريم الذي لربنا ومخلصنا يسوع المسيح : الأول فى اليوم السادس عشر من شهر توت سنة 326 م على الملكة البارة القديسة هيلانة ، والدة الإمبراطور قسطنطين الكبير ، لأن هذه القديسة - وقت أن قبل ابنها قسطنطين الإيمان بالمسيح - نذرت أن تمضى الى أورشليم . فأعد ابنها البار كل شئ لإتمام هذه الزيارة المقدسة . ولما وصلت أورشليم ومعها عسكر عظيم وسألت عن مكان الصليب لم يعلمها به أحد فأخذت شيخا من اليهود ، وضيقت عليه بالجوع والعطش ، حتى اضطر الى -الإرشاد عن المكان الذي يحتمل وجود الصليب فيه بكيمان الجلجثة . –فأشارت بتنظيف الجلجثة ، فعثرت على ثلاثة صلبان ، وذلك فى سنة 326 م . ولما لم يعرفوا الصليب الذي صلب عليه السيد المسيح أحضروا ميتا ووضعوا عليه أحد الصلبان فلم يقم ، وكذا عملوا فى الآخر ، ولكنهم لما وضعوا عليه الثالث قام لوقته . فتحققوا بذلك أنه صليب السيد المسيح فسجت له الملكة ، وكل الشعب المؤمن ، وأرسلت جزءا منه الى ابنها قسطنطين مع المسامير ، وأسرعت فى تشييد الكنائس المذكورة فى اليوم السادس عشر من شهر توت المبارك . والاحتفال الثاني الذي تقيم فيه الكنيسة تذكار الصليب فى اليوم العاشر من شهر برمهات . وكان على يد الإمبراطور هرقل فى سنة 627 ميلادية . وذلك أنه لما ارتد الفرس منهزمين من مصر الى بلادهم أمام هرقل ، حدث أنه عند مرورهم على بيت المقدس أحد أمراء الفرس كنيسة الصليب التى شيدتها الملكة هيلانة . فرأى ضوءا ساطعا يشع من قطعة خشبية موضوعة على مكان محلى بالذهب . فمد الأمير يده إليها ، فخرجت منها نار وأحرقت أصابعه . - فأعلمه النصارى أن هذه قاعدة لصليب المقدس ، كما قصوا عليه أيضا أمر اكتشافه ، وأنه لا يستطيع . أن يمسها إلا المسيحى . فاحتال على شماسين كانا قائمين بحراستها ، وأجزل لهما العطاء على أن يحملا هذه القطعة ويذهبا بها معه إلي بلاده ، فأخذاها ووضعاها في صندوق وذهبا بها معه إلي بلاده مع من سباهم من شعب أورشليم وسمع هرقل ملك الروم بذلك ، فذهب بجيشه إلي بلاد الفرس وحاربهم وخذلهم وقتل منهم كثيرين . وجعل يطوف في تلك البلاد يبحث عن هذه القطعة فلم يعثر عليها . لأن الأمير كان قد حفر في بستانه حفرة وأمر الشماسين بوضع هذا الصندوق فيها وردمها ثم قتلهما . ورأت ذلك إحدى سباياه وهي ابنة أحد الكهنة، وكانت تتطلع من طاقة بطريق الصدفة فأسرعت الى هرقل الملك وأعلمته بما كانت قد رأته فقصد ومعه الاساقفة والكهنة والعسكر الى ذلك الموضع . وحفروا فعثروا علي الصندوق بما فيه فأخرجوا القطعة المقدسة فى سنة 628 م ولفوها فى ثياب فاخرة وأخذها هرقل الى مدينة القسطنطينية وأودعها. هناك . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "The First on the , 326 A.D. by the hands of the righteous Empress St. Helen, the mother of \r\n. This Saint when her son Constantine accepted the Faith in the Lord Christ, she vowed to go to Jerusalem. Her righteous son prepared everything needed to fulfill this holy visit.", ar: "لا تصلى صلوات السواعى في رفع بخور عشية عيد الصليب لأنه يقع دائما في الصوم الكبير" } },
      { kind: 'reading', text: { en: "When she arrived to Jerusalem with multitude of soldiers, she asked about the place of the Cross but no one would tell her. She took one of the jewish elders and pressured him by hunger and thirst until he was forced to direct them to the place where they might find the Cross at the hill of Golgotha. She ordered them to clear out the site of Golgotha where they found three crosses and that was in the year 326 A.D. However, they did not know the cross upon which Our Lord Christ was crucified, they brought a dead man and they laid upon him one of the crosses and then the other but he did not rise up but when they laid the third cross upon him he rose up immediately, then they realized that this was the Cross of Our Lord Christ. The Empress and all the believers kneeled down before the Holy Cross, and she sent a piece of it with the nails to her son Constantine. Immediately after, she built the churches that were mentioned on the \r\n.", ar: "" } },
      { kind: 'reading', text: { en: "The Second celebration that the church commemorates the Cross is on the Tenth day of the month of Baramhat by the hands of Emperor Heraclius, in 627 A.D. When the Persians were defeated by Heraclius they retreated from Egypt to their country. On their way back they passed through Jerusalem, a persian prince entered the church of the Cross which was built by Empress Helen. He saw a great light shinning from a piece of wood located on a place decorated with gold. He thrust his hand to it and there went forth from it fire which burned his fingers. The Christians told him that this is the base of the Holy Cross and they told him how it was discovered and no one was able to touch it except a Christian. He deceived the two deacons who were standing to guard it and gave them much money so they would carry this piece and go with it with him to his country. They took it and put it in a box and went with him to his country along with those who were captured from the city of Jerusalem.", ar: "" } },
      { kind: 'reading', text: { en: "When Emperor Heraclius heard that, he went with his army to Persia, fought with them and slew many of them. He traveled about this country searching for this piece of the Holy Cross but he could not find it, for the Persian prince had dug a hole in his garden and ordered the two deacons to put the box in it and buried it and then he killed them.", ar: "" } },
      { kind: 'reading', text: { en: "One of the captives of that Persian prince which was the daughter of one of the priests, was looking out of the window by chance and saw what happened. She went to Heraclius the Emperor and told him what she saw. He went with the bishops, priests and the soldiers to the place. They dug there and found the box, they took the piece of the Holy Cross out, in 628 A.D., wrapped it in magnificent apparel and Heraclius took it to the city of Constantinople and kept it there.", ar: "" } },
      { kind: 'reading', text: { en: "May the blessings of the Holy Cross be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نوة الشمس الكبرى : شرقية سبعة أيام" } },
      { kind: 'reading', text: { en: "", ar: "في اشهر الشتاء تتعرض الأجزاء المطلة علي البحر المتوسط لظاهرة تولد الانخفاضات الجوية الإعصارية التي تميز الأحوال المناخية في إقليم البحر المتوسط وتعرف في الإسكندرية باسم النوات." } },
      { kind: 'reading', text: { en: "", ar: "هي اضطرابات جوية تنشأ عنها دوامة هوائية دائرية أو بيضاوية ذات ضغط منخفض وسط مساحة ضغطها مرتفع وتندفع فيها الرياح علي شكل حلزوني نحو مركز منخفض بحيث يكون سيرها ضد اتجاه عقارب الساعة ." } }
    ],
  },
  {
    id: "synax-baramhat-11",
    title: { en: "Baramhat 11", ar: "11 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom Of St. Basil (Basilaos) The Bishop.", ar: "استشهاد باسيلاؤس الاسقف" } },
      { kind: 'reading', text: { en: "On this day St. Basil (Basilaos) the bishop was martyred. In the year 298 A.D., Abba Armon, Patriarch of Jerusalem, ordained this holy man among others to be bishops without stated Sees. He sent them to preach the Kingdom of Heaven in pagan cities. This Saint preached in many cities where they beat him and drove him out.", ar: "فى مثل هذا اليوم استشهد القديس باسيلاؤس الأسقف . وهذا القديس رسم أسقفا مع آخرين علي غير كراس فى سنة 298 م من القديس هرمون بطريرك أورشليم الذي أرسلهم يكرزون ببشارة الملكوت فى البلاد التى ليس فيها مؤمنون . فكرز هذا القديس فى بلاد كثيرة فضربوه وطردوه . ولما دخل شرصونة بالشام ونادى بالبشرى آمن به قوم من أهلها ، فغضب الآخرون وطردوه . فخرج الى خارج المدينة وسكن فى مغارة مداوما الابتهال والصلاة الى الله أن يؤمنوا به . واتفق أن ابن والى المدينة مات وكان وحيده . فحزن عليه كثيرا . وحدث فى الليلة التى دفن فيها أن الوالد رأى ابنه فى رؤيا الليل واقفا أمامه وهو يقول له : استدع القديس باسيلاؤس وأسال أن يصلى الى المسيح من أجلى ، فإني فى ظلمة عظيمة &quot; . فانتبه من نومه وأخذ عظماء المدينة وأتي الى مغارة القديس وطب منه أن يدخل المدينة ليصلى من أجل ابنه -. فأجاب سؤلهم وذهب معهم الى حيث قبر ابنه . وابتهل الى الله بصلاة حارة . فقام الولد حيا بقوة الله . فآمن الأمير وأهله وأكثر أهل المدينة ، وتعمدوا من يد هذا القديس . وكان بالمدينة جماعة من اليهود . فحسدوا القديس واجتمعوا بالذين لم يؤمنوا من أهل البلد ووثبوا جميعا عليه ، وضربوه وجروه الى أن أسلم روحه بسلام . . بركة صلاته تكون معنا . ولربنا المجد دائما. آمين ." } },
      { kind: 'reading', text: { en: "When he entered the city of Sharsunah, in Syria, he preached the Gospel, some of its people believed but the others became angry and drove him out. He went outside the city and dwelt in a cave where he gave himself to perpetual prayers and supplications to God that the people of the city might believe in Christ.", ar: "" } },
      { kind: 'reading', text: { en: "The son of the Governor of that city died, he was his only child, and he grieved on him exceedingly. On the day that the Governor buried his son, he saw him in a vision at night, standing before him saying: \"Call St. Basilaos and ask him to pray to the Lord Christ on my behalf because I am in great darkness.\" The Governor woke up from his dream and took the nobles of the city, went to the cave of St. Basilaos and asked him to enter the city to pray for his son. The Saint agreed to their request and went with them to where the Governor's son was buried. He prayed to God with fervent supplication and the son rose up alive with the power of God.", ar: "" } },
      { kind: 'reading', text: { en: "The Governor, his household, and many of the people of the city believed, and were baptized by the hands of this Saint. There were in the city a congregation of Jews who were envious of the Saint. They joined with the men of the city who did not believe, and rose up against the Saint and beat him and dragged him until he yielded up his soul in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-12",
    title: { en: "Baramhat 12", ar: "12 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the revealing of the virginity of St. Demetrius the Twelfth Pope of Alexandria.", ar: "ظهور بتولية البابا ديمتريوس الاسكندرى ال 12" } },
      { kind: 'reading', text: { en: "On this day also the church celebrates the commemoration of the revealing of the virginity of St. Demetrius the Twelfth Pope of Alexandria. The angel of the Lord appeared to\n, before his departure and said: \"You are going to the Lord Christ, the one who will bring you tomorrow a cluster of grapes, is the one fit to be a Patriarch after you.\" On the morrow, this saint came with a cluster of grapes, Abba Julian held him and told the people: \"This is your Patriarch after me,\" and told them what the angel told him. After the departure of Abba Julian they took him and ordained him Patriarch on the\n(March 4th., 188 A.D.) and he was married.", ar: "فى مثل هذا اليوم تعيد الكنيسة بتذكار ظهور بتوليه القديس العظيم الأنبا ديمتريوس بابا الكرازة المرقسية الثاني عشر . وذلك أن القديس يوليانوس البابا إلحادي عشر ليلة نياحة ظهر له ملاك الرب وقال له : &quot; أنت ماض الى السيد المسيح فالذي يدخل إليك غدا ومعه عنقود عنب ، هو الذي يصلح أن يكون بطريركا بعدك ! . فلما كان الغد دخل هذا القديس ومعه عنقود عنب فأمسكه الأب يوليانوس وقال للشعب : &quot; هذا بطريرككم بعدى &quot; . ثم عرفهم بما قاله له الملاك . فأمسكوه وأقاموه بطريركا فى 9 برمهات ( 4 مارس سنة 188 م ) وكان متزوجا + ولم يكن رسم على كرسى الإسكندرية بطريرك متزوج قبل هذا الأب . فدخل الشيطان فى قلب عامة الناس وجعلتهم يتحدثون بأمره ويذمونه هو ومن قدمه . فظهر له ملاك الرب وأعلمه بذلك ب !. وأمره أن ينزع الشك من القلوب بإظهار آمرة مع امرأته أمام الشعب فامتنع أولا . فقال له الملاك : (&quot; يجب أن لا تخلص نفسك فقط وتدع غيرك يهلك بسببك . ولأنك راع فاجتهد فى خلاص شعبك أيضا.فلما كان الغد قام بخدمة القداس ، ثم أمر الشعب بعدم الانصراف بعد نهاية الخدمة ، واستحضر نارا موقدة ، وطلب زوجته من بيت النساء . وكان الشعب يتعجب من ذلك ، وهم لا يدرون ماذا يقصد بذلك . وصلى ووقف على ا لنار بقدميه وهي متقدة ، ثم أخذ منها كمية ووضعها فى ازاره ، ثم وضع كمية أخرى فى ازار زوجته ، ولبث وقتا طويلا وهو يصلى ، ولم يحترق 1 شئ من الازارين . فتعجب الشعب وسألوه عن السبب الذي دفعه لهذا العمل ، فأعلمهم بخبره مع امرأته ، وقال ان أبويهما زواجهما بغير أرادتهما وان لهما ثمان واربعين سنة منذ زواجهما وهما يعيشان عيشة أخ وأخت ، يظللهما ملاك الرب بجناحيه ، وان أحدا لم يعرف ذلك قبل الآن ، الى أن أمره ملاك الرب بإظهار ذلك ." } },
      { kind: 'reading', text: { en: "Since no married Patriarch ever before this father been enthroned over the See of Alexandria, satan entered the hearts of the laity and made them talk and grumble against the Patriarch and the one who recommended him. The angel of God appeared to St. Demetrius and told him about that and ordered him to remove the doubt from their hearts by revealing to them his relation with his wife. When St. Demetrius refused, the angel told him: \"It is not meet that you save your self alone and let others be perished because of you. But because you are a shepherd you should fight to save your people also\".", ar: "فتعجب الشعب مما رأوا وسمعوا وسبحوا الله تعالى طالبين من القديس أن يتجاوز عما فرط منهم ويغفر لهم . .فقبل عذرهم ؟ وغفر لهم ، وباركهم ، ثم صرفهم الى بيوتهم ممجدين الأب والابن والروح القدس ، مذيعين ما رأوه من عجائب هذا القديس . صلاته تكون معنا آمين ." } },
      { kind: 'reading', text: { en: "On the next day, after he had finished celebrating the Divine Liturgy, he asked the people not to leave the church. He brought flamed charcoal, and brought his wife from the place of the women and the congregation wondered at his action, not knowing what he was going to do. He prayed and walked on the blazing fire, he took a piece of the blazing fire and put it in his shawl, then he took another piece and put it in his wife's shawl. He prayed again for a long time and both shawls did not burn. The congregation marvelled and asked him to tell them why he did that. He told them of his strife with his wife, and how his father and her father married them against their will, and\n, the angel of the Lord each night covered them with his wings, and no one knew that before that time until the angel of the Lord ordered him to reveal his secret.", ar: "" } },
      { kind: 'reading', text: { en: "The congregation marvelled for what they had seen and heard, they praised and glorified God asking the Saint to pardon them for what they had done or said and to forgive them. He accepted their apology, forgave them, blessed them, and sent them to their homes glorifying the Father, and the Son, and the Holy Spirit talking about what they saw of wonders from this Saint.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Malachias of Palestine.", ar: "استشهاد القديس ملاخى بأرض فلسطين" } },
      { kind: 'reading', text: { en: "On this day also the righteous St. Malachias was martyred in the land of Palestine.", ar: "فى مثل هذا اليوم أستشهد القديس البار ملاخى المستشهد بأرض فلسطين . صلاته تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Glathinos in Damascus.", ar: "استشهاد القديس جلاذينوس فى دمشق" } },
      { kind: 'reading', text: { en: "On this day the church also celebrates the commemoration of the martyrdom of St. Glathinos (Glazinos) who was in the early part of the reign of Emperor Constantine the great. This Saint was from the city of Marmeen, near Damascus. He was acting with a group of people who were from the city of Heleopolis, Lebanon, and dedicated themselves to worship idols.", ar: "فى مثل هذا اليوم تحتفل الكنيسة بتذكار استشهاد القديس جلاذينوس فى أوائل حكم الإمبراطور قسطنظين الكبير . وكان هذا القديس من مدينة مارمين بالقرب من دمشق ، وعلى بعد ميل منها . وكان يمثل مع جموع من الناس قد كرسوا أنفسهم لعبادة الأوثان وهم من سكان مدينة هليوبوليس فى لبنان فعندما اجتمعوا ذات يوم فى المسرح وجمعوا فيه الممثلين قام الاخيرون بسكب ماء بارد فى حوض نحاسي كبير، وابتدأوا يتكلمون بتهكم عن الذين يذهبون الى معمودية المسيحيين المقدسة ، ثم غطسوا أحد هؤلاء الممثلين فى الماء فعمدوه . ثم أخرجوه وألبسوه ثوبا أبيض على سبيل التمثيل . ولكن هذا الممثل بعدما أخرج من الماء ، امتنع عن الاستمرار فى التمثيل ، وأعلن أنه يفضل الموت مسيحيا علي اسم السيد المسيح . وأضاف الى ذلك قائلا : &quot; عندما كنتم تهزأون أثناء تجديد ماء المعمودية المقدسة شاهدت معجزة عجيبة &quot; . وعند ذلك ابتعدت قليلا عن هذه المياه . فاستاء الحاضرون منه ، واستشاطوا غضبا ،لأنهم كانوا وثنيين . وقبضوا على هذا القديس ورجموه ، ففاضت روحه ، ونال إكليل الشهادة الدائم ، ودخل فى عداد الشهداء القديسين . ثم حضر أهله وكثيرون من المسيحيين ، وأخذوا جسده ، ودفنوه فى المدينة ، وبنوا كنيسة عليه . نفعنا الله ببركاته . ولربنا.المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "One day they gathered in the theater, and the actors poured cold water in a large brass basin, and started mocking those who go to the holy Christian baptism. They dipped one of those actors in the water, to act his baptism, when he came out of the water they put on him white cloth.", ar: "" } },
      { kind: 'reading', text: { en: "This actor after he had come out of the water, refused to go on acting, and made it known that he prefered to die Christian on the Name of the Lord Christ, and he added to that saying: \"While you were mocking during my renewal with the Holy Baptism, I have witnessed a wondrous miracle.\" Those who were present became offended, and extremely furious for they were pagans. They seized the Saint, stoned him, and St. Glathinos delivered up his soul and received the crown of martyrdom, and was counted among the holy martyrs. His family and many of the Christians came, took his body, and buried him in the city where they built a church after his name.", ar: "" } },
      { kind: 'reading', text: { en: "May his blessings be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Honorable Angel Michael.", ar: "التذكار الشهري لرئيس الملائكة الجليل ميخائيل" } },
      { kind: 'reading', text: { en: "On this day the church celebrates the commemoration of the head of the heavenly hosts the honorable , the intercessor for the human race.", ar: "فى مثل هذا اليوم تحتفل الكنيسة بتذكار رئيس جند السماء الملاك الجليل ميخائيل الشفيع فى جنس البشر. شفاعته تكون معنا . آمين." } },
      { kind: 'reading', text: { en: "May his intercession be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-13",
    title: { en: "Baramhat 13", ar: "13 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of the Forty Martyrs of Sebastia.", ar: "استشهاد الاربعين شهيدا بسبسطية" } },
      { kind: 'reading', text: { en: "On this day also the holy forty martyrs of the city of Sebastia were martyred.\nthe great had appointed his friend Lecius ruler for the east and commanded him to treat the Christians well. When he arrived to his headquarter, he ordered his subordinate to worship the idols but they refused and cursed his idols. That night some of the soldiers and their children, from the city of Sebastia, made an agreement among themselves to go to the governor confessing their faith. While they were sleeping the angel of the Lord appeared to them, strengthened them and comforted their hearts.", ar: "فى مثل هذا اليوم استشهد القديسون الأربعون شهيدا بمدينة سبسطية . وذلك أن الملك قسطنطين الكبير كان قد ولى ليكيوس صديقه من قبله على الشرق وأوصاه بالمسيحيين خيرا ولكنه لما وصل الى مقر الولاية أمر مرؤوسيه بعبادة الأصنام فامتنعوا وشتموا آلهته . وفى إحدى الليالي اتفق بعض الجنود وأولادهم من مدينة سبسطية على أن يتقدموا إليه معترفين بإيمانهم وبينما هم نائمون ظهر لهم ملاك الرب وشجعهم وثبت قلوبهم . وفى الصباح وقفوا أمام حاجب –الوالي واعترفوا بالسيد المسيح فهددهم –الملك فلم يخافوا . وأمر أن يرجموا بالحجارة ، فكانت الحجارة ترتد على مرسليها. وكان بجوارهم بركة ماء متجمدة . فأمر أن يطرحوا فيه فطرحوهم فتقطعت أعضاؤهم من شدة البرد ." } },
      { kind: 'reading', text: { en: "In the morning they stood before the Governor and confessed their faith in the Lord christ, he threatened them but they were not afraid. He commanded his men to stone them, but the stones came back upon those who stoned them. He ordered to throw them in a nearby lake, which was icy. Their organs were severed because of the excessive cold. One of them whose strength was weakened, went out of the icy water and entered the bath house nearby the lake. The heat in the bath house melted the ice that was on him but he died quickly, and lost his reward.", ar: "وكان بجوار البركة حمام وخارت قوى أحدهم فصعد الى هذا الحمام وأذابت حرارته الجليد الذي كان عليه فانخلت أعصابه ومات بسرعة . وهكذا صار ضمن مصاف الشهداء ." } },
      { kind: 'reading', text: { en: "One of the guards saw angels descending from the heaven and in their hands crowns, they placed them over the heads of the thirty nine martyrs and remained one crown in the hand of the angel. The guard went down into the lake shouting \"I am christian...I am christian.\" He took the crown that was in the hand of the angel and was counted among the martyrs.", ar: "أما الباقون فان أحد الحراس رأى ملائكة نزلت من السماء وبيدهم أكاليل وضعوها على رؤوس الشهداء التسعة والثلاثين . وبقى إكليل بيد الملاك . فأسرع الحارس ونزل الى البركة وهو يصيح : &quot; أنا مسيحي . أنا مسيحي &quot; . فأخذ الإكليل الذي كان معلقا بيد الملاك ، وانضم الى صفوف الشهداء . وكان بين الشهداء بعض صغار السن ، وكانت أمهاتهم تقويهم وتثبتهم . وإذ مكثوا فى البركة زمانا ولم يموتوا ، أراد الملك أن يكسر سيقانهم ، فأخذ الرب نفوسهم وأراحهم . فأمر أن يحطوا على عجلة ويطرحوا فى البحر بعد أن يحرقوا . وكان بينهم صبى صغير لم يمت ، فتركوه فحملته أمه وطرحته على العجلة مع رفقائه فأنزلوه ثانيا لانه حي فأخذته أمه ومات على عنقها . فوضعته معهم . وخرجوا بهم الى خارج المدينة ورموهم فى النار فلم تمسهم بأذى . ثم رموهم فى البحر . وفى اليوم الثالث ظهر القديسون لاسقف سبسية فى رؤيا وقالوا له : هلم الى النهر وخذ أجسادنا . فقام وأخذ الكهنة ووجد الأجساد فحملها باحترام ووضعها فى محل خاص . وشاع ذكرهم فى كل الأقطار . صلواتهم تكون معنا . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "Among the martyrs, were young men, whose mothers encouraged and strengthened them. Because they remained in the lake for a long time and they did not die, the Governor wished to break their legs, but the Lord took their souls and reposed them. He ordered to burn their bodies and to cast them after that into the sea. As they were carrying them out of the lake, they found a young man alive, so they left him. His mother took him and tried to threw him on the wagon with his mates but they put him off the wagon again for he was still alive. His mother took him and he died in her bosom so she put him back on the wagon. They took them outside the city and cast them into the fire which did not harm them, then they casted them into the river.", ar: "" } },
      { kind: 'reading', text: { en: "On the third day those holy martyrs appeared to the Bishop of Sebastia in a vision and told him: \"Go to the river and take our bodies.\" He went with the priests, deacons and the people to the river and found the bodies. They carried\n, and their strife was heard in all the countries.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Abba Dionysius, the Fourteenth Pope of Alexandria.", ar: "نياحة البابا ديونسيوس الاسكندرى ال14" } },
      { kind: 'reading', text: { en: "On this day (March 8th, 264 A.D.) the great father Abba Dionysius, the fourteenth Pope of Alexandria, departed. His parents were stare worshippers of the Sun (Sabians) and they put emphasis on teaching him all the knowledge of that sect.", ar: "فى مثل هذا اليوم . ( 8 مارس سنة 264 ميلادية ) تنيح الأب العظيم الأنبا ديونيسيوس الرابع عشر من باباوات الكرازة المرقسية . وهذا كان ابنا لأبوين على مذهب الصابئة ( عابدي الكواكب ) وقد اهتم والده بتعليمه كل علوم الصابئة ." } },
      { kind: 'reading', text: { en: "One day a Christian old woman passed by him, who had with her some pages of a book containing an Epistle of St. Paul the apostle and offered it to him to buy it. When he read it he found in it strange sayings and unusual knowledge. He asked her: \"For how much will you sell it?\" She said: \"For one dinar of gold.\" He gave her three dinars and asked her to find the rest of the pages of the book and he was willing to pay her double. She went and brought him more pages. Having read them through he found the book to be still incomplete, he asked her to search for the rest of the book. She told him: \"I found these quires among my father's books. If you want to acquire the complete book, go to the church and there you can find it.\"", ar: "وحدث ذات يوم أن مرت به عجوز مسيحية وبيدها بضع أوراق من رسائل بولس الرسول وعرضت عليه شراءها . فلما تناولها واطلع عليها وجد بها شيئا غريبا وعلما عجيبا . فسألها &quot; أتبيعينها &quot; ؟ فأجابته : &quot; نعم بقيراط ذهب فأعطاها ثلاثة قراريط ، وطلب منها أن تبحث عن بقية هذه الأوراق وهو على استعداد أن يضاعف لها الثمن . فذهبت وعادت ببضع أوراق أخرى . وإذ وجد الكتاب ناقصا طلب منها بقيته . فقالت له : &quot; لقد وجدت هذه الأوراق ضمن كتب آبائي . وإذا أردت الحصول على الكتاب كاملا فاذهب الى الكنيسة وهناك تحصل عليه &quot; . فذهب وطلب من أحد الكهنة أن يطلعه على ما يسمي رسائل بولس ؟ فأعطاها له فقرأها ووعاها . ثم قصد القديس ديمتريوس البابا الثاني عشر . فأخذ البابا يعلمه ويرشده الى حقائق الإيمان المسيحي ثم عمده . فتقدم كثيرا في علوم الكنيسة ، حتى أن الأنبا ديمتريوس عينه معلما للشعب" } },
      { kind: 'reading', text: { en: "He went and asked one of the priests to show him what is called the Epistles of Paul. He gave it to him, read it, and memorized it. Then he went to St. Demetrius the twelfth Pope, who taught and instructed him in the facts of the Christian faith then baptized him. He became well rehearsed in the doctrine and knowledge of the church, and Anba Demetrius appointed him a teacher for the people.", ar: "ولما تنيح الأنبا ديمتريوس ورسم الأب ياروكلاس بطريركا جعله نائبا فى الحكم بين المؤمنين . وفوض إليه أمر إدارة البطريركية . ولما تنيح القديس ياروكلاس اتفق رأي كل الشعب على تقدمته بطريركا فى أول طوبة ( 28 ديسمبر سنة 46 2 م ) ، فى زمن الملك فيلبس المحب للنصارى ، فرعى رعيته أحسن رعاية . غير أنه تحمل شدائد كثيرة . وذلك أن داكيوس تغلب علي فيلبس وقتله ولما جلس على أريكة الملك أثار الاضطهاد على المسيحيين ، وقتل كثيرين من البطاركة والاساقفا والمؤمنين . ومات فملك بعده غالوس ، فهدأ الاضطهاد فى مدة ملكه . ولما مات هذا وملك مكانه فاليريانوس أثار من جديد الاضطهاد" } },
      { kind: 'reading', text: { en: "When Anba Demetrius departed and Anba Heraclas (Yaroklas) was enthroned, he appointed him as a deputy to judge among the believers and entrusted him to administer the affairs of the patriarchate.", ar: "على المسيحيين بشدة وقبض على الأب ديونيسيوس وعرض عليه السجود للأصنام فامتنع قائلا * نحن نسجد لله الآب وابنه يسوع المسيح والروح القدس الآلة الواحد &quot; فهدده كثيرا وقتل أمامه جماعة ، فلم يردعه شئ من ذلك . فنفاه ثم استعاده من النفى وقال له : بلغنا أنك تنفرد وتقدس فأجابه : &quot; نحن لا نترك صلاتنا ليلا ولا نهارا &quot; . ثم التفت الى الشعب الذي كان حوله وقال لهم : إ امضوا وصلوا . وأنا وان كنت غائبا عنكم بالجسد فآني حاضر معكم بالروح &quot; . فاغتاظ الملك من ذلك وأعاده الى منفاه . - ولما تغلب عليه سابور ملك الفرس واعتقله ، تسلم الملك ابنه غاليانوس وكان صالحا حليما فأطلق المعتقلين من المؤمنين وأعاد منهم من كان منفيا . وكتب للبطريرك والأساقفة كتاب أمان أن يفتحوا كنائسهم ." } },
      { kind: 'reading', text: { en: "When St. Heraclas departed, all the people agreed to appoint this father Patriarch. He was enthroned on the\n(December 28th, 246 A.D.) during the reign of Emperor Philip who was a lover of the Christians, and he shepherded his flock with the best of care, nevertheless, he suffered much tribulations. When Decius rose up against Philip and killed him, and reigned in his place, he incited persecution against the Christians. Decius slew many of the patriarchs, bishops, and believers. This father endured much suffering during that time. Decius died and Gallus reigned after him, and persecution quieted down during his reign.", ar: "وظهر فى أيام هذا الأب قوم فى بلاد العرب يقولون : ان النفس تموت مع الجسد ، ثم تقوم معه فى يوم القيامة ، . . فجمع عليهم مجمعا وحرمهم . وظهر آخرون على بدعة أوريجانس وسابليوس ، ولما كفر بولس السميساطى بالابن ، واجتمع عليه مجمع بإنطاكية، لم يستطع هذا القديس الحضور إليه لشيخوخته ، فاكتفى برسالة كلها حكمة ، بين فيها فساد رأى هذا المبتدع ، وأظهر صحة المعتقد القويم . وأكمل سعيه الصالح ، وتنيح بشيخوخة صالحة فى ( 8 مارس سنة 264 م ) ، بعد أن أقام على الكرسي الرسولى 17 سنة وشهرين وعشرة أيام . صلاته تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "When Gallus died and Valerian reigned in his place, he renewed the persecution severely against the Christians, and his men seized Abba Dionysius and imprisoned him. They asked him to worship the idols but he refused saying: \"We worship God the Father, and His Son Jesus Christ, and the Holy Spirit the One God.\" They threatened him, killed few men in front of him to terrify him but he was not afraid. They banished him and shortly after, they brought him back and told him: \"We have been informed that you consecrate the offering secretly by yourself.\" He replied: \"We do not forsake our prayers day or night\" then he turned to the people present around him and told them: \"Go and pray and if I am away from you in the body, I shall be with you in spirit.\" The governor became raged and returned him to exile.", ar: "" } },
      { kind: 'reading', text: { en: "When Sapor king of Persia overcame Emperor Valerian and seized him, his son Gallienus, who was wise and gentle, took over the empire. He released all the believers who were in prison and brought back those who were in exile. He wrote to the Patriarch and the bishops a letter to assure their safety in opening the churches.", ar: "" } },
      { kind: 'reading', text: { en: "In the days of this father, certain people arose in the Arabian countries saying: \"That the soul dies with the body, and on the day of Resurrection, it shall be raised up with it.\" He gathered against them a council and anathematized them. When Paul of Samosata denied the Son, a Council assembled against him in Antioch, this Saint was not able to attend for his age. He wrote a letter to the council, rich with wisdom, explained in it the corruptive opinion of this heretic, and stated the true Orthodox belief. He finished his good strife, and departed in a good old age on (March 8th, 264 A.D.), having sat on the Apostolic Throne seventeen years, two month and ten days.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Return of the Great Sts. Anba Macarius the Great and Anba Macarius of Alexandria, from Exile.", ar: "عودة القديسين العظيمين الأنبا مقاريوس الكبير والأنبا مقاريوس \r\nالإسكندري من منفاهما" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the return of the Great Sts. Anba Macarius the Great and Anba Macarius of Alexandria, from exile on an island in Upper Egypt. Emperor Valens the arian had exiled them to this island.", ar: "فى مثل هذا اليوم تذكار عودة القديسين العظيمين الأنبا مقاريوس الكبير والأنبا مقاريوس الإسكندري من منفاهما فى جزيرة بأعلى الصعيد . وكان قد نفاهما إليها الملك والس الاريوسى . &quot;" } },
      { kind: 'reading', text: { en: "The natives of this island worshipped idols, and according to the orders of Valens the two Saints were tortured severely for three years. It came to pass one day that satan entered the daughter of the pagan priest of this island and tortured her. St. Macarius the great came forward and prayed over her and the Lord healed her and subsequently the priest and the people of the island believed on the Lord Christ. The Saints taught them the facts of the Christian faith and baptized them on the eve of the\nchanged the temple into a church, and with a revelation from the Lord Christ they ordained priests and deacons for them.", ar: "وكان أهل تلك الجزيرة يعبدون الأوثان . وبناء على أمر فالنز نال القديسان من أهل تلك الجهة عذابات أليمة مدة ثلاث سنوات . وحدث ذات يوم أن دخل شيطان فى ابنة كاهن الوثن بتلك الجزيرة وأتعبها جدا . فتقدم القديس مقاريوس الكبير وصلى عليها فشفاها الرب فأمن الكاهن وأهل الجزيرة بالسيد المسيح . فعلمهم القديسان حقائق الدين المسيحى وعمداهم فى ليلة الغطاس 11 طوبة وحولوا البربه التى فى الجزيرة إلى كنيسة . وقدس فيها القديسان وناولاهم من الأسرار الإلهية . وبإعلان من السيد المسيح رسما لهم كهنة وشمامسة . وعندما أرادا العودة لم يعرفا الطريق ، فظهر لهما ملاك الرب وسار معهما يرشدهما ، فوصلا الى الإسكندرية ، ومنها إلى جبل شيهيت . فتلقاهما رهبان البرية، وكان عددهم فى ذاك الوقت خمسين ألف راهب ، منهم الأنبا يؤنس القصير والأنبا بشوى ، وفرح الرهبان بلقاء أبيهم . صلوات هؤلاء القديسان تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "When they wished to return they did not know the way, so the angel of the Lord appeared to them, guided them walking, until they reached Alexandria. From there they went to the wilderness of Sheahat (Scetis). The monks of the wilderness came out to meat them, and they were at that time about fifty thousand monks among them were\nand\nAnba Bishoy, and they all rejoiced to meat their fathers.", ar: "" } },
      { kind: 'reading', text: { en: "The prayers of these Saints be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-14",
    title: { en: "Baramhat 14", ar: "14 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Shenouda (Sinouti) El Bahnasawy.", ar: "استشهاد القديس شنودة البهنساوى" } },
      { kind: 'reading', text: { en: "On this day also St. Shenouda (Sinouti) El Bahnasawy was martyred. Certain men laid accusations against him before Maximianus, a governor appointed by Diocletian, that he was Christian. The Governor brought him, and asked him about his faith, and the Saint confessed his faith in the Lord Christ and that He was the True God. He ordered the soldiers to throw him on the ground, to beat him with hammers until his flesh was torn, and his blood flew on the ground, then they casted him into a prison with repulsive odor. The Lord sent Michael the Archangel to him, healed his wounds, encouraged and strengthened him. He told him that he will receive the crown of glory after he had endured what would befall him from severe tortures.", ar: "فى مثل هذا اليوم استشهد القديس شنوده البهنساوى . ذلت أن بعضهم وشى به ، لدى الامير مكسيموس المعين من قبل دقلديانوس ، بأنه مسيحى . فاستحضره وسأله عن معتقده فاقر بإيمانه بالمسيح وبأنه الإله الحقيقي . فآمر الجند أن يطرحوه على الأرض ، ويضربوه بالمطارق ، حتى تهرأ لحمه ، وجرى دمه على الأرض . ثم وضعوه فى سجن كريه الرائحة . فأرسل الرب إليه رئيس الملائكة ميخائيل ، فأبرأه من جراحاته ثم شجعه وقواه ،وبشره باكليل المجد بعد احتمال ما سيحل به من العذاب الشديد . وفى الصباح التالي أمر الأمير الجند أن يفتقدوه فوجدوه واقفا يصلى . ولما أعلموا الأمير بأمره ، وأبصره سالما ، بهت وقال : &quot; انه ساحر &quot; . ثم أمر فعلقوه منكسا وأوقدوا تحته نارا ، فلم تؤثر فيه . فعصروه بالمعصرة . وأخيرا قطعوا رأسه وجسمه إربا أربا ، ورموه للكلاب فلم تقربه . وفى الليل أخذه المؤمنون وسكبوا عليه طيبا كثير الثمن ، ولفوه فى أكفان غالية . ووضعوه فى تابوت ثم دفنوه . صلاته تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "On the next morning the Governor ordered his soldiers to go and look at him, and they found him standing up praying. When they told the Governor about him and when he saw him whole and un-harmed, he was amazed and said: \"He is a sorcerer.\" Then he ordered to crucify him with his head downwards, and to light fire under him, but it did not harm him. They squeezed him with the wheel and finally they beheaded him and hacked his body into pieces with swords and casted him to the dogs which did not come near him. During the night the believers took him and poured over him expensive perfumes, shrouded him in costly wrappings, laid him in a coffin and buried him.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of the Sts. Eugenius, Agathodorus and Elpidius.", ar: "استشهاد الأباء الاساقفة اوجانيوس واغابودوس ولانديوس" } },
      { kind: 'reading', text: { en: "On this day also the Sts. Eugenius, Agathodorus and Elpidius were martyred. These holy men were Christians, through their fathers and forefathers, walking in the way of God, and had a great deal of knowledge about the church subjects. St. Hermon (Armos) Patriarch of Jerusalem ordained them bishops without parishes to go around preaching and teaching the word of God. They went and preached in many cities, and the people of one of the cities went out, beat them very severely, then they stoned them until they departed in peace and received the crown of martyrdom.", ar: "فى مثل هذا اليوم استشهد القديسون أوجانيوس وأغاتودرس والبديوس . هؤلاء القديسون كانوا مسيحيين عن آبائهم وأجدادهم ، سالكين فى طريق الله . حاصلين على جانب عظيم من العلوم الدينية . فرسمهم القديس هرمون بطريرك أورشليم أساقفة بدون كراسى ليجولوا كارزين ومعلمين . فذهبوا وكرزوا فى مدن كثيرة . وفى إحدى المدن خرج عليهم أهلها وضربوهم ضربا شديدا بدون رحمة ، ثم رجموهم بالحجارة الى أن تنيحوا بسلام ، وئالوا أكليل الشهادة . صلاتهم تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Anba Kyrellos (Cyril) the Seventy Fifth Pope of Alexandria.", ar: "نياحة البابا كيرلس أبن لقلق" } },
      { kind: 'reading', text: { en: "On this day of the year 959 A.M. (Marsh 10, 1243 A.D.) departed the holy father Anba Kyrellos, the seventy fifth Pope of Alexandria, who was known as Ebn-Loqloq. This father was enthroned on the twenty third of the month of Baounah, 951 A.M. (June 17th., 1235 A.D.). There were objections at first in choosing him but finally they unanimously agreed on him.", ar: "فى مثل هذا اليوم من سنة 959 ش الموافق 0 1 مارس 1243 تنيح الأب القديس الأنبا كيرلس الخامس والسبعون من باباوات الكرازة المرقسية ، المعروف بابن لقلق . وقد رسم هذا الأب فى الثالث والعشرين من شهر بؤونة سنة 951 للشهداء ( 17 يونية1235 م ) . وحصلت معارضات فى اختياره أولا ، وأخيرا انتهى الإجماع عليه . وفى أيام هذا الأب اجتمع مجمع من سائر أساقفة الكرازة المرقسية ووضعوا قانونا شاملا للكنيسة . وكان الشيخ الاجل العلامة الصفى ابن العسال كاتبا لهذا المجمع . وأقام هذا الأب على الكرسى البطريركى سبع سنين وثمانية أشهر وثلاثة وعشرين يوما . وتنيح بدير الشمع فى سنة 959 للشهداء . ( 10 مارس 1243 م ) . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "During the days of this father a holy council convened, which was attended by all the bishops of the See of St. Mark, and they put down a comprehensive cannons for the church. The honorable scholar El-Safy Ebn El-Assal was the secretary of this council. This father sat on the Patriarchal Chair for seven years, eight month and twenty three days. He departed in El-Shamaa (Wax) monastery in the year 959 A.M. (March 10, 1243 A.D.)", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-15",
    title: { en: "Baramhat 15", ar: "15 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Sarah the nun.", ar: "نياحة القديسة سارة الراهبة" } },
      { kind: 'reading', text: { en: "On this day departed the righteous and ascetic St. Sarah the nun who was a native of Upper Egypt. Her parents, who were exceedingly rich, were Christians and had no other children. They raised her in a christian manner and taught her reading and writing. She was always reading the books of the church and especially the biography and sayings of the fathers the monks. She was influenced by their lives and desired the ascetic life. She went to one of the convents of Upper Egypt and dwelt there for many years serving the virgins.", ar: "في مثل هذا اليوم تنيحت القديسة المجاهدة سارة الراهبة هذه الناسكة كانت من أهالي الصعيد &quot;، وكان أبواها مسيحيين غنيين . ولم يكن لهما ولد سواها . فربياها تربية مسيحية ، وعلماها القراءة والكتابة . وكانت مداومة على قراءة الكتب الدينية وخصوصا أخبار الآباء الرهبان . فتأثرت بسيرتهم الصالحة واشتاقت إلي الحياة النسكية . فقصدت أحد الأديرة التي بالصعيد حيث مكثت فيه سنين كثيرة تخدم العذارى . ثم لبست زي الرهبنة ، ولبثت تجاهد شيطان الشهوة ثلاث عشرة سنة حتى كل الشيطان منها ، وضجر من ثباتها وطهارتها. فقصد إسقاطها في رذيلة الكبرياء فظهر لها وهى قائمة تصلى على سطح قلايتها وقال لها : &quot; بشراك فقد غلبت الشيطان &quot; . فأجابته : &quot; أنني امرأة ضعيفة لا أستطيع أن أغلبك إلا بقوة السيد المسيح &quot; فتوارى من أمامها . ولهذه القديسة أقوال كثيرة نافعة كانت تقولها للعذارى . منها قولها : &quot; أنني لا أضع رجلي على درجة السلم إلا وأتصور أنني أموت قبل أن أرفعها . حتى لا يغرينى العدو بالأمل في طول الحياة ، ومنها ق ولها : &quot; جيد للإنسان أن يفعل الرحمة ، ولو لا رضاء الناس . فسيأتي وقت تكون لا رضاء الله &quot; . ولها أقوال أخرى كثيرة مدونه في كتب سير شيوخ الرهبان . وأقامت هذه القديسة على حافة النهر مدة ستين سنة تجاهد جهادا عظيما لم يبصرها أحد خلالها حتى انتقلت إلي النعيم الدائم بالغة من العمر ثمانين عاما . صلاتها تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "Then she put on the monastic garb, persisting on fighting the lust of Satan for thirteen years until Satan was weary of her. When Satan was exasperated from her steadfastness and purity, he wished to overthrow her by the sin of pride. He appeared to her while she was standing praying on the roof of her cell and said to her: \"Rejoice for you have overcome Satan.\" She replied: \"I am a feeble woman, and I can not conquer you except by the power of the Lord Christ\" and then Satan vanished.", ar: "" } },
      { kind: 'reading', text: { en: "This Saint had many useful sayings that she used to say to the nuns. One of her sayings: \"I never set my foot upon the step of the ladder, and I never go up to the next step without thinking I may die before I raise my leg so that the enemy might not entice me with the hope of a long life.\" And she also said: \" IT is better for a man to show mercy even to satisfy men for the time will come that it will be to satisfy God.\" She also had many other sayings written in the Paradise of the Fathers. She stayed on the banks of the river in a cave for sixty years fighting a great fight and no one saw her until she departed to the eternal bless and she was eighty years old.", ar: "" } },
      { kind: 'reading', text: { en: "May her prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Helias of Hnes.", ar: "استشهاد القديس ايلياس الاهناسى" } },
      { kind: 'reading', text: { en: "On this day also St. Helias of Hnes was martyred.", ar: "فى مثل هذا اليوم استشهد القديس ايلياس الاهناسى . صلاته تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نوة عوة وبرد العجوزة : غربية ستة أيام" } },
      { kind: 'reading', text: { en: "", ar: "في اشهر الشتاء تتعرض الأجزاء المطلة علي البحر المتوسط لظاهرة تولد الانخفاضات الجوية الإعصارية التي تميز الأحوال المناخية في إقليم البحر المتوسط وتعرف في الإسكندرية باسم النوات." } },
      { kind: 'reading', text: { en: "", ar: "هي اضطرابات جوية تنشأ عنها دوامة هوائية دائرية أو بيضاوية ذات ضغط منخفض وسط مساحة ضغطها مرتفع وتندفع فيها الرياح علي شكل حلزوني نحو مركز منخفض بحيث يكون سيرها ضد اتجاه عقارب الساعة ." } }
    ],
  },
  {
    id: "synax-baramhat-16",
    title: { en: "Baramhat 16", ar: "16 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure Of The Saint Anba Khail (Mikhail) The Forty Six Pope Of The See Of St. Mark.", ar: "نياحة البابا ميخائيل &quot;خائيل&quot; ال46" } },
      { kind: 'reading', text: { en: "On this day of the year 483 A.M. (March 12th, 767 A.D.) the holy father Anba Khail (Mikhail), the forty six Pope of the See Of St. Mark, departed. This father was a monk in the monastery of St. Macarius and he was knowledgeable and ascetic. When Pope Theodorus the forty fifth Patriarch, his predecessor, departed the bishops of Lower Egypt (Delta) and the priests of Alexandria gathered in the church of Anba Shenouda in Cairo.", ar: "في مثل هذا اليوم من سنة 483 ش ( 2 1 مارس سنة 767 ميلادية ) تنيح الأب القديس الأنبا خائيل السادس والاربعون من باباوات الكرازة المرقسية. هذا الأب كان راهبا بدير القديس مقاريوس وكان عالما زاهدا . فلما تنيح سلفه البابا ثاؤذوروس الخامس والاربعون اجتمع أساقفة الوجه البحري وكهنة الإسكندرية فى كنيسة الأنبا شنوده بمصر . وحصل خلاف بينهم على من يصلح ، وأخيرا استدعوا الأنبا موسى أسقف أوسيم والأنبا بطرس أسفف مريوط . ولما حضرا وجد الأنبا موسى تعنتا من كهنة الإسكندرية فزجرهم على ذلك وصرف الجمع هذه الليلة حتى تهدأ الخواطر . ولما اجتمعوا فى الغد ذكر لهم اسم القس خائيل الراهب بدير القديس مقاريوس . فارتاحوا الى اختياره بالإجماع . وحصلوا على كتاب من والى مصر الى شيوخ برية شيهيت ( وادي النطرون ) ولما وصلوا الى الجيزة وجدوا القس خائيل قادما مع بعض الشيوخ لتأدية مهمة معينة فامسكوه وقيدوه وساروا به الى الإسكندرية وهناك رسموه بطريركا فى 7 1 توت سنة460 ش ( 4 1 سبتمبر سنة 743 م ) . وحدث أن امتنع المطر عن الإسكندرية مدة سنتين ، ففي هذا اليوم هطلت أمطار غزيرة مدة ثلاثة أيام . فاستبشر الإسكندريون بذلك خيرا . وفى عهد خلافة مروان آخر خلفاء الدولة الأموية وولاية حفص بن الوليد ، جرت على المؤمنين فى أيام هذا الأب شدائد عنيفة ، وهاجر البلاد المصرية عدد كبير من المؤمنين كما بلغ عدد الذين أنكروا المسيح أربعة وعشرين ألفا . وكان البطريرك بسبب ذلك فى حزن شيد جدا الى . أن أهلك الله من كان سبب ذلك . وقد تحمل هذا الأب البطريرك مصائب شديدة من عبد الملك بن مروان الوالي الجديد ، كالضرب والحبس والتكبيل بالحديد ، وغير ذلك من ضروب التعذيب الأليمة . ثم أطلق فمضى الى الصعيد وعاد بما جمعه الى الوالي فأخذه منه ثم ألقاه فى السجن . فلما علم بذلك كرياكوس ملك النوبة استشاط غضبا ، وجهز نحو مئة ألف جندي وسار الى القطر المصري واجتاز الصعيد قاتلا كل من صادفه من المسلمين ، حتى بلغ مصر ، فعسكر حول الفسطاط مهددا المدينة بالدمار . فلما نظر عبد الملك الوالي جيوشه منتشرة كالجراد ، جزع وأطلق سبيل البطريرك بإكرام ، والتجأ إليه أن يتوسط فى أمر الصلح بينه وبين ملك النوبة . فلبى دعواه وخرج بلفيف من الاكليروس الى الملك وطلب منه أن يقبل الصلح من عبد الملك فقبل وانصرف الى حيث أتى فأعز عبد الملك جانب المسيحيين ورفع عنهم الأثقال . وزاد فى اعتبارهم عندما صلى الأب البطريرك من أجل ابنة له كان يعتريها روح نجس ، وبصلاته خرج منها الروح النجس . وحدثت مناقشات بين هذا الأب وقزما بطريرك الملكيين عن الاتحاد . فكتب إليه الأب خائيل رسالة وقع عليها مع أساقفته قائلا : &quot; لا يجب أن يقال ان فى المسيح طبيعتين مفترقتين بعد الاتحاد ولا اثنين ولا شخصين &quot; . واقتنع قزما بذلك ورضى أن يصير أسقفا على مصر تحت رياسة الأب خائيل ، الذي لما أكمل سعيه وجهاده انتقل الى الرب الذي أحبه بعد أن قضى على الكرسى المرقسى ثلاثا وعشرين سنة ونصف . صلاته تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "A Dispute arose among them about who was fit, and finally they called Anba Mousa, Bishop of Ouseem, and Anba Petros, Bishop of Mariout. When they arrived, Anba Mousa found the priests of Alexandria obstinate, he rebuked them for that, and dismissed them that night so their minds and souls might calm down. When they met the next day he mentioned to them the name of the priest Khail the monk in the monastery of St. Macarius. They unanimously agreed to his choice and obtained a decree from the Governor of Egypt to the elders of the wilderness of Sheahat (Wadi El-Natroun) to bring him from the monastery. On their way, when they arrived to Geza they found father Khail coming along with some elders to fulfill a certain task connected with the monastery. They seized him, bound him, and took him to Alexandria where they ordained him Patriarch on the\n, year 460 A.M. (September 14th., year 743 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "It Happened that there was a drought in the city of Alexandria for two years, and on that day the rain fell heavily for three days and the people of Alexandria considered that a good omen.", ar: "" } },
      { kind: 'reading', text: { en: "During the reign of Marawan the last of the Khalifas of the Umayyad rule and during the governorship of Hefs Ebn El-Walid and during the days of this father many great tribulations fell upon the believers.", ar: "" } },
      { kind: 'reading', text: { en: "A large number of the believers fled from Egypt and the number of those who denied Christ was twenty-four thousand, and because of that the Patriarch was in great sorrow until God perished those were responsible for that. This father endured many difficulties from Abdel Malek Ebn-Marawan the new governor. He imprisoned, beaten, chained, and tortured him with many other ways of painful tortures, then he released him. The Patriarch went to Upper Egypt to collect alms and when he came back, the Governor took the money from him and threw him back in prison.", ar: "" } },
      { kind: 'reading', text: { en: "When Keriakos king of Nuba knew that, he was extremely enraged, he prepared one hundred thousand soldiers and marched down to Egypt. Going threw Upper Egypt he slew all the Muslims that he met, until he reached El Fostat (Cairo), he camped around the city threatening to destroy it. When Abdel Malek the Governor saw the army surrounding the city and that all this had taken place for the sake of the Patriarch, he became terrified, so he released him from prison with great honor. The Governor entreated the Patriarch to mediate peace between him and the king of Nuba. The Patriarch agreed to his request, so he went with some of the clergy to meet the king and asked him to accept the peace from abdel Malek which the king accepted and returned back.", ar: "" } },
      { kind: 'reading', text: { en: "Abdel Malek respected the Christians and lifted up all his retribution. When the father the Patriarch prayed for the sake of the Governor's daughter, who was possessed with an unclean spirit, and with his prayers the unclean spirit left her, the Governor increased his respect for the Christians.", ar: "" } },
      { kind: 'reading', text: { en: "This father debated with Cosmas the Melchite Patriarch concerning the Hypostatic Union. Pope Khail wrote him a letter, signed it along with his bishops, which said in it: \"It is not right to say that in Christ two distinct Natures or two distinct Persons after the Hypostatic Union.\" Cosmas was convinced with that and asked to become a bishop under the authority of Anba Khail. When Anba Khail completed his strife, he departed to the Lord whom he loved after he had spent on the Chair of St. Mark twenty-three and half years.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-17",
    title: { en: "Baramhat 17", ar: "17 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of Lazarus, the beloved of the Lord.", ar: "نياحة لعازر حبيب الرب أسقف قبرص" } },
      { kind: 'reading', text: { en: "On this day the righteous Lazarus, the beloved of the Lord Christ, departed. He was the brother of Martha and Mary who anointed the Lord with fragrant oil and wiped His feet with her hair. When Lazarus fell sick the sisters sent to the Lord Christ saying: \"Lord, behold, he whom You love is sick.\" When Jesus heard that, He said, \"This sickness is not unto death, but for the glory of God, that the Son of God may be glorified through it.\" Now Jesus loved Martha and her sister and Lazarus. So, when He heard that he was sick, He stayed two more days in the place where He was\" to magnify the miracle.", ar: "في مثل هذا اليوم تتيح الصديق البار لعازر حبيب الرب يسوع وهو أخو مرثا ومريم التى دهنت الرب بطيب ومسحت رجليه بشعرها . وحدث لما مرض لعازر أنهما أرسلتا الى السيد المسيح قائلتين : ( يا سيد هوذا الذي تحبه مريض . فلما سمع يسوع قال : هذا المرض ليس للموت بل لأجل مجد الله ليتمجد ابن الله به وكان يسوع يحب مرثا وأختها. ولعازر &quot; . ولكنه أقام فى الموضع الذي كان فيه يومين لتعظيم الآية . &quot; ثم بعد ذلك قال لتلاميذه : لنذهب الى اليهودية أيضا . قال له التلاميذ يا معلم الآن كان اليهود يطلبون أن يرجموك وتذهب أيضا الى هناك . أجاب يسوع أليست ساعات النهار اثنتى عشرة ان كان أحد يمشى فى النهار لا يعثر لأنه ينظر نور هذا العالم . ولكن ان كان أحد يمشى فى الليل يعثر لان النور ليس فيه &quot; . وبعد ذلك قال لهم : لعازر حبيبنا قد نام . لكنى أذهب لأوقظه فقالوا : ( ان كان قد نام فهو يشفى . وكان يسوع يقول عن موته . وهم ظنوا أنه يقول عن رقاد النوم . فقال لهم يسوع حينئذ علانية : لعازر مات . وأنا أفرح لأجلكم أنى لم أكن هناك لتؤمنوا . ولكن لنذهب إليه &quot; . فلما أتى السيد الى بيت عنيا القريبة من أورشليم وقف أمام القبر وقال : &quot; ارفعوا الحجر . فقالت له مرثا أخت الميت : يا سيد قد أنتن لأن له أربعة أيام . فقال لها يسوع ألم أقل لك ان آمنت ترين مجد الله . فرفعوا الحجر وصلى الى الأب ثم صرخ بصوت عظيم : لعازر هلم خارجا . فخرج الميت ويداه ورجلاه مربوطات بأقمطة ووجهه ملفوف بمنديل . فقال لهم يسوع حلوه ودعوه يذهب (1) . وكان ذلك لبيان حقيقة موته ، فلا يظن أحد أن ذلك حيلة باتفاق سابق . ولهذا قد عظمت الآية فآمن كثيرون . صلاة هذا البار تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "Then after this He said to the disciples, \"Let us go to Judea again.\" The disciples told Him, \"Rabbi, lately the Jews sought to stone You, and are You going there again?\" Jesus answered, \"Are there not twelve hours in the day? If anyone walks in the day, he does not stumble, because he sees the light of this world. \"But if one walks in the night, he stumbles, because the light is not in him.\" These things He said, and after that He said to them, \"Our friend Lazarus sleeps, but I go that I may wake him up.\" Then His disciples said, \"Lord, if he sleeps he will get well.\" However, Jesus spoke of his death, but they thought that He was speaking about taking rest in sleep. Then Jesus said to them plainly, \"Lazarus is dead. And I am glad for your sakes that I was not there, that you may believe. Nevertheless let us go to him.\"", ar: "" } },
      { kind: 'reading', text: { en: "When the Lord came to Bethany which is nearby Jerusalem He stood before the tomb and said: \"Take away the stone.\" Martha, the sister of him who was dead, said to Him, \"Lord, by this time there is a stench, for he has been dead four days.\" Jesus said to her, \"Did I not say to you that if you would believe you would see the glory of God?\" Then they took away the stone from the place where the dead man was lying. And Jesus lifted up His eyes and prayed then he cried with a loud voice, \"Lazarus, come forth!\" And he who had died came out bound hand and foot with graveclothes, and his face was wrapped with a cloth. Jesus said to them, \"Loose him, and let him go.\" (John 11:1-45)", ar: "" } },
      { kind: 'reading', text: { en: "That was to manifest the reality of his death, so no one would think that this was deception with previous arrangement, for that the miracle was magnified and many believed.", ar: "" } },
      { kind: 'reading', text: { en: "The prayers of this righteous be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Sedhom Bishay in Domiat.", ar: "استشهاد سيدهم بشاى بدمياط" } },
      { kind: 'reading', text: { en: "On this day also the church commemorates the martyrdom of Sedhom Bishay in Domiat on the 17th. of Baramhat year 1565 A.D. (March 25th., 1844 A.D.). He endured the torture for the Name of the Lord Christ and his martyrdom made the rising of the Cross during the Christian funeral processions openly, for it was forbidden before.", ar: "فى مثل هذا اليوم تحتفل الكنيسة بتذكار استشهاد سيدهم بشاى بدمياط فى يوم 17 برمهات سنة1565 ش ( 25 مارس سنة 1844 م ) لاحتماله التعذيب على اسم السيد المسيح حتى الموت . وكان استشهاده سببا فى رفع الصليب علنا فى جنازات المسيحيين . فقد كان هذا الشهيد موظفا كاتبا بالديوان بثغر دمياط فى أيام محمد على باشا والى مصر وقامت ثورة من الرعاع بالثغر ، وقبضوا على الكاتب سيدهم بشاى واتهموه زورا أنه سب الدين الإسلامي وشهد عليه أيام القاضى الشرعي بربري وحمار . فحكم عليه بترك دينه أو القتل . ثم جلده وأرسله الى محافظ الثغر. وبعد أن فحص قضيته حكم عليه بمثل ما حكم به القاضى . فتمسك سيدهم بدينه المسيحي ، واستهان بالقتل ، فجلدوه وجروه على وجهه من فوق سلم قصر المحافظ الى أسفله ، ثم طاف به العسكر بعت أن أركبوه جاموسة بالمقلوب فى شوارع المدينة ، فخاف النصارى وقفلوا منازلهم أما الرعاع فشرعوا يهزأ ون به ويعذبونه بالات مختلفة الى أن كاد يسلم الروح . فأتوا به الى منزله وتزكوه على بابه ومضوا فخرج أهله وأخذوه . وبعد خمسة أيام انتقل الى السماء . وكان موته استشهادا عظيما ، وصار النصارى يعتبرونه من الشهداء القديسين واجتمعوا على اختلاف مذاهبهم ، واحتفلوا بجنازته احتفالا لم يسبق له مثيل ، حيث احتفل بتشييع جثمانه جهرا . فتقلد النصارى الأسلحة ولبس الكهنة - وعلى رأسهم القمص يوسف ميخائيل رئيس شريعة الأقباط بدمياط - ملابسهم واشترك معه كهنة الطوائف الأخرى . وساروا به فى شوارع المدينة وأمامه الشمامسة يحملون أعلام الصليب ثم أتوا به الى الكنيسة وأتموا فروض الجنازة . وصار الناس يستنكرون فظاعة هذا الحادث الأليم ، ويتحدثون بصبر الشهيد سيدهم ، وتحمله ألوان العذاب بجلد وسكون . ثم تداول كبار الشعب المسيحي بثغر دمياط لتلافى هذه الحوادث مستقبلا . فقرروا أن يوسطوا قناصل الدول فى ذلك لعرض الآمر على والى البلاد ،.، والبابا بطريرك الأقباط ، ورفعوا إليهما التقارير المفصلة . وتولى هذا الموضوع الخواجه ميخائيل سرور المعتمد الرسمي لسبع دول بثغر دمياط فاهتم والى مصر بالآمر ، وأرسل مندوبين رسميين لفحص القضية . فأعادوا التحقيق وتبين منه الظلم والجور الذي حل بالشهيد العظيم . واتضح إدانة القاضى والمحافظ . فنزعوا عنهما علامات الشرف ونفوهما بعد التجريد . وطلبوا - للترضية وتهدئة الخواطر - السماح برفع الصليب جهارا أمام جنازات المسيحيين فأذن لهم بذلك فى ثغر دمياط ، الى أن تعمم فى سائر مدن القطر فى عهد البابا كيرلس الرابع . بركة إيمان هذا الشهيد العظيم تكون معنا. ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "This martyr was a clerical employee in the government of the port of Domiat during the days of Mohammed Ali Basha the Governor of Egypt. A revolt of mobs in the port arose, they seized Sidhom Bishay and accused him falsely that he cursed Islam and witnessed against him before the religious judge a low uncivilized person and a donkey driver. The judge decided either he would forsake his faith or be killed, he whipped him and then sent him to the Governor of the city. After the Governor had examined his case he issued the same judgement against him as the judge did. Sidhom was steadfast in his Christian faith, not caring to be killed. They whipped, dragged him on his face down the stairs in the Governor palace, then they put him on a buffalo facing the tail and went around with him in the streets of the city insulting and degrading him. The Christians in the city became afraid and locked themselves in their houses.", ar: "" } },
      { kind: 'reading', text: { en: "The mob continued to insult him and tortured him in different ways until he was about to deliver his soul; so they brought him to the door of his house and left him there. His family went out and brought him inside and five days later he departed to heaven.", ar: "" } },
      { kind: 'reading', text: { en: "His departure was a great martyrdom, and the Christians counted him among the holy martyrs. They gathered regardless of their denomination and joined in his funeral in a celebration that there was nothing like it before. The Christians carried their arms and the priest put on their vestments headed by the Archpriest Yousef Michael who was the head of the Coptic congregation in Domiat and accompanied by the priests of the other denominations. They marched in his funeral in the streets of the city and in front of him the deacons carrying the banners of the Cross, and they arrived to the church where they prayed the funeral rites. The people went on objecting this reprehensible and painful incident and talking about the patience and endurance of the different kinds of torture in silence and the steadfastness of Sidhom the martyr.", ar: "" } },
      { kind: 'reading', text: { en: "The prominent people of the Christian community in Domiat deliberated as how to avoid these incidents in the future. They decided to ask the consuls of the foreign countries to mediate with the ruler of the country and the Pope the Patriarch of the Copts and sent to them detailed reports. Mr Michail Sorour the official representative of seven countries in Domiat was in charge of this mediation.", ar: "" } },
      { kind: 'reading', text: { en: "The ruler of Egypt was concerned about this incident and sent two official representatives to examine the case. So they reopened the inquiry and they realized the injustice and the ill-treatment that befell the great martyr and convicted the judge and the governor for their wrong doing, stripped them from their honor then exiled them. They asked, as a good will and to comfort the people, to allow the raising of the Cross publicly before the Christian funerals, and the ruler allowed that in Domiat. This was allowed later on all over the country during the Papacy of Pope Kyrellos IV.", ar: "" } },
      { kind: 'reading', text: { en: "The blessings of this great martyr be with us and glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Basilius, Bishop of Jerusalem.", ar: "نياحة الأنبا باسيليوس مطران القدس" } },
      { kind: 'reading', text: { en: "On this day also of the year 1615 A.M. (March 26th., 1899 A.D.) the great father Anba Basilius, Metropolitan of Jerusalem, departed. This father was born in the village of El-Dabah, Farshout county, the province of Quena, for righteous parents. They nursed him with the milk of righteousness since his young age, as they taught him reading and writing, so he grew on loving perfection and moral excellence.", ar: "فى مثل هذا اليوم من سنة1615 ش ( 26 مارس 1899 م ) تنيح الأب العظيم الأنبا باسيليوس مطران القدس . ولد هذا الأب سنة 1818 م ببلدة الدابة بمركز فرشوط بمديرية قنا من والدين تقيين ، فأرضعاه لبان الفضيلة من صغره ، كما علماه القراءة والكتابة منذ حداثته . فشب على حب الكمال والفضيلة" } },
      { kind: 'reading', text: { en: "When he was twenty-five years old he went to the monastery of St. Antonios and put on the monastic garb in the year 1559 A.M. He persevered in worshipping and ascetism and because he was adorned with righteousness and piety they ordained him priest in the year 1565 A.M. and archpriest (Hegumen) in the year 1568 A.M., then they appointed him an Abott for the monastery. He managed the monastery well with gentleness, wisdom and meekness that made the blessed Anba \r\nto ordain him Metropolitan for Jerusalem and the parishes that were attached to him: El-Kaliobia, El-Sharkia, El-Dakahlia, El-Gharbia, Suez, Domiat, and Port-Said.", ar: "ولما بلغ خمسا وعشرين سنة قصد دير القديس أنطونيوس ولبس زي الرهبئة فى سنة 1559 للشهداء ، وثابر على العبادة والنسك . ونظرا لما تحلى به من التقوى والورع رسموه قسا سنة 1565 للشهداء وقمصا سنة 1568 ثم أقاموه رئيسا للدير فأحسن الإدارة المقرونة باللطف والوداعة والحكمة ، مما جعل المطوب الذكر الأنبا كيرلس الرابع يرسمه مطرانا على القدس ، وكان يتبعه أبرشيات القليوبية والشرقية والدقهلية والغربية ومحافظات السويس ودمياط وبورسعيد ." } },
      { kind: 'reading', text: { en: "He had shown prudence in managing the affairs of these parishes that made him the center of admiration and pride to the Copts. All his efforts were dedicated for the building of churches all over his parish, buying and renovating properties in Jaffa and Jerusalem. He was loved by all the people of Syria and Palestine, regardless of their religion or political persuasion, especially the rulers of Jerusalem, for his wise policy and straight morals.", ar: "وقد أظهر من الحزم فى تدبير شئون هذه الابرشيات ما جعله موضع فخر وإعجاب الأقباط . وكانت كل مساعيه منصرفة الى بناء الكنائس فى أنحاء أبرشيته ، ومشترى وتجيد الأملاك والعقارات فى يافا والقدس. وله فى ذلك مآثر. جليلة تنطق بفضله وكان محبوبا من جميع سكان الديار الشامية والفلسطينية على اختلاف مشاربهم وأديانهم ، لاسيما حكام القدس ، وذلك لسياسته الحكيمة وأخلاقه القويمة . وفى أيامه حصلت منازعات من الأثيوبيين حيث ادعوا ملكيتهم لدير السلطان بالقدس . وبفضل هذا الأب ويقظته لم يتمكنوا من تثبيت ملكيتهم . وقد حضر رسامة البابا ديمتريوس الثاني وهو إلحادي عشر بعد المائة والبابا كيرلس الخامس وهو الثاني عشر بعد المائة . وقضى أيامه فى سعى متواصل لما فيه خير شعبه وتنيح بسلام . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "During his days a dispute aroused from the Ethiopians where they claimed their ownership for the monastery of El-Sultan in Jerusalem. Because of this father and his vigilance they could not establish an ownership for the monastery. He attended the enthronement of Pope Demetrius II, the hundred eleventh, and Pope Kyrellos V, the hundred twelfth. He spent his days in continuous effort for what was good for his people and departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Sts. George the ascetic, Belasius the martyr, and Anba Joseph the bishop.", ar: "تذكار القديسين جرجس العابد وبلاسيوس الشهيد والأنبا يوسف الأسقف" } },
      { kind: 'reading', text: { en: "On this day also the church celebrates the commemoration of the Sts. George the ascetic, Belasius the martyr, and Anba Joseph the bishop.", ar: "فى مثل هذا اليوم تعيد الكنيسة بتذكار القديسين جرجس العابد وبلاسيوس الشهيد والأنبا يوسف الأسقف. صلاتهم تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-18",
    title: { en: "Baramhat 18", ar: "18 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Isidore, Friend of Sina the Soldier.", ar: "استشهاد ايسيذوروس رفيق سنا الجندى" } },
      { kind: 'reading', text: { en: "On this day St. Isidore the companion of Sina the soldier was martyred. Sina, who was a native of the city of Deknash, was one of the soldiers who accompanied the Governor of Farma. St. Isidore was his friend and he was working as wool maker. Both of them gave alms to the poor and needy with what they earned. One night both saw a vision and it seemed to them that a virgin came to them with crowns which she placed on their heads. When they woke up from their sleep they told each other about what they had seen, and they rejoiced greatly as they believed that the Lord had called them to receive the crown of martyrdom. They went to the Governor and sina unbound the soldier's girdle and cast it down before him and they both confessed the Lord Christ. He ordered their detention but God sent His angel and comforted them.", ar: "فى مثل هذا اليوم استشهد القديس ايسيذورس رفيق سنا الجندي . - هذا كان من أهل دقناش (ورد في مخطوط بشبين الكوم دفناس) من الجنود المرافقين لوالى الفرما . أما القديس ايسيذورس صديق سنا فكان يشتغل بصناعة الصوف وكان الاثنان يتصدقان بما يكسبانه على الفقراء والمعوزين . وذات ليلة أبصر كل منهما فى رؤيا أن فتاة عذراء بيدها إكليل تضعه على رأسيهما . فلما استيقظا من النوم أعلم كل منهما الآخر بما رآه . ففرح الاثنان بذلك لاعتقادهما أن الرب قد دعاهما لنوال إكليل الشهادة فأتيا الى الوالي وحل سنا منطقة الجندية وطرحها أمامه ، واعترف كلاهما بالسيد المسيح . فأمر باعتقالهما فأرسل الرب ملاكه وعزاهما . ثم أرسل الوالي سنا الى الإسكندرية وبقى ايسيذورس سجينا وحده . وبعد قليل أعيد سنا الى الفرما ففرح ايسيذورس بلقائه . وذكر كل منها لرفيقه ما جرى له . ثم أمعن الوالي في تعذيبهما ، وأمر بإلقاء ايسيذورس فى حفرة موقدة . إلا أن القديس استمهل الجند وصلى طالبا من السيد المسيح أن يقبل روحه ويهتم بجسده وسلم نفسه للجند فألقوه فى الحفرة ، فلم يلحق جسده أذى . وكانت أما القديس سنا تبكى لحرمان ولدها من رفيقه ، وبعد قليل أسلم القديس ايسذورس روحه . وفى تلك اللحظة رأت أم القديس سنا جماعة من الملائكة تصعد بالروح . شفاعته تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "The Governor sent St. Sina to Alexandria and St. Isidore remained prisoner alone. After a short period St. Sina was returned back to the Farma and St. Isidore rejoiced at meeting his friend, and they told each other what had happened to them. The Governor tortured them severely and ordered St. Isidore to be cast into a pit with fire therein. St. Isidore asked the soldier to wait and he prayed asking our Lord Christ to accept his soul and to care for his body. He gave himself to the soldiers and they threw him into the pit but his body was not harmed in any way by the fire. The mother of St. Sina was weeping for her son because of his separation from his friend. After a short while St. Isidore delivered up his soul and at that time the mother of St. Sina saw a multitude of angels carrying away St. Isidore's soul.", ar: "" } },
      { kind: 'reading', text: { en: "May his intercession be with us and glory be to God fore ever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-19",
    title: { en: "Baramhat 19", ar: "19 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Martyrdom of St. Aristobulus, the apostle.", ar: "نياحة ارسطوبولس أحد السبعين رسول" } },
      { kind: 'reading', text: { en: "On this day St. Aristobulus, one of the seventy apostles that was chosen and sent to preach by the Lord before His passion, was martyred. He received along with the disciples the gifts of the Spirit the comforter, accompanied, ministered to them and preached with them the Life-giving Gospel. He turned many to the path of salvation, believed in the Lord Christ, baptized them and taught them the Divine commandments.", ar: "في مثل هذا اليوم تنيح القديس ارسطو بولس أحد السبعين رسولا الذين انتخبهم الرب وأرسلهم للكرازة قبل آلامه . وقد نال مع التلاميذ مواهب الروح المعزى، وصحبهم وخدمهم ونادى معهم بالبشارة المحيية ، ورد كثيرين الى طريق الخلاص . فآمنوا بالسيد المسيح . فعمدهم وعلمهم الوصايا الإلهية . وأقامه التلاميذ أسقفا على ابريطانياس فمضى إليها ، وبشر أهلها ، ووعظهم وعمدهم ، وصنع آيات كثيرة . وقد لحقت به إهانات شديدة من اليهود واليونانيين ، وطردوه مرارا عديدة ورجموه بالحجارة . ولما أكمل سعيه تنيح بسلام . وقد ذكره بولس الرسول فى رسالته الى رومية، ( ص 16 : . 1 ) . صلاته تكون معنا . آمين . 2 - وفى مثل هذا اليوم أيضا : تذكار السبعة القديسين الشهداء وهم : الكسندروس المصري ، وأغابيوس من غزة ، وتيمولاؤس من البنطس ، وديوناسيوس من طرابلس ، وروميلوس وبليسوس من قرى مصر : وهؤلاء ارتبطوا بالمحبة المسحية ، وأتوا الى والى قيسارية فلسطين ، واعترفوا أمامه بالسيد المسيح . فنالوا إكليل الشهادة فى زمن دقلديانوس . صلواتهم تكون معنا . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "The disciples ordained him bishop for the city of Abratabias, and he went there, preached it's people, performed many miracles, taught and baptized them. Many tribulations and humiliation befell him from the Jews and the Greeks, who threw him out many times, and cast him with stones. Having finished his strife, he departed in peace. St. Paul had mentioned him in his Epistle to the Romans (Ch.16:10).", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of the Sts. Alexander, Agabius, Alexander, Timol (Timolaos), Dionysius, Romulus, and Blesius (Valesius).", ar: "" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of the seven holy martyrs: Alexander the Egyptian, Agabius and Alexander from the city of Gaza, Timol (Timolaos) from Pontus, Dionysius from the city of Tripoli, and Romulus, and Blesius (Valesius) from the villages of Egypt. These men were joined together with the Christian love, and they came to the Governor of Caesarea, Palestine, and confessed before him the Lord Christ. They all were martyred and received the crown of martyrdom during the days of Diocletian.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-20",
    title: { en: "Baramhat 20", ar: "20 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure Of the St. Anba Khail (Mikhail) the Fifty Six Pope of the See of St. Mark.", ar: "نياحة البابا خائيل الاسكندرى ال56" } },
      { kind: 'reading', text: { en: "On this day of the year 623 A.M. (March 16th., 907 A.D.) the holy father Anba Khail (Mikhail), the fifty six Pope of Alexandria, departed. He was enthroned Patriarch on the 30th. of Baramouda 5296 A.M. (April 25th., year 880 A.D.). This father had nobel qualities, nevertheless a great sorrow came upon him.", ar: "في مثل هذا اليوم من سنة 623 ش ( 16 مارس 907 م ) تنيح الأب القديس الأنبا خائيل السادس والخمسون من باياوإت الكرازة المرقسية -. رسم بطريركا فى 30 برمودة سنة 596ش ( 25 أبريل سنة 880 م ) . وكان ذا خصال حميده غير أن أحزانا شديدة حلت به : منها أن البابا قسما كان قد بنى كنيسة على اسمه الشهيد أبطلماوس ببلدة دنوشر لأسقف سخا . ." } },
      { kind: 'reading', text: { en: "Pope Cosma II built a church on the name of St. Ebtelmaos in the city of Danousher which was under the jurisdiction of the bishop of Sakha. The people of Danousher desired to invite the father the Patriarch Anba Mikhail and some of the neighboring bishops to consecrate this church but the Bishop of Sakha was not pleased with this idea. When they did against his wish and the father the Patriarch along with the bishops came, this bishop refused to stay and he left the church pretending that he was going to check on their meal. When the Bishop did not come back, and the time to start the service had passed, the bishops and the elders asked the father the Patriarch to begin the service. Having urged the Patriarch and pointed out that he was the father of them all and having authority over them, with difficulty he rose up and prayed the prayer of thanks giving and the offering of the Lamb. When the Bishop heard of this, and for his wickedness and his love for the glory of the world, he became enraged with the excuse that the Patriarch had violated the cannons of the church and celebrated the divine Liturgy in a parish without the permission of its bishop. He returned to the church in hast and Satan entered his heart, he transgressed against the holy and pure altar and the offering that was on it, then left the church full of wrath. The father the Patriarch completed the Divine Liturgy with calmness and maturity.", ar: "وحدث أن أهالي دنوشر أرادوا أن يدعوا الأب البطريرك وبعض الاساقفه المجاورين لتكريس هذه الكنيسة . فلم يطب لديه هذا الآمر . ولما عملوا على غير رغبته ، وجاء الأب البطريرك ومعه الأساقفة ، لم يقبل هذا الأسقف البقاء ، فخرج من الكنيسة مدعيا أنه ذهب ليهتم فأمر طعامهم . فلما طال غيابه كثيرا وحان وقت القداس صلي الأب البطريرك صلاة الشكر ورفع القربان بعد إلحاح من الأساقفة وبما له من حقوق الرئاسة . وعلم الأسقف بذلك فدفعه شره وحبه لمجد العالم الى الغضب بدعوى أن البطريرك تعدى القوانين ورفع قربانا في أبرشية بدون إذن صاحبها . وعاد إلى الكنيسة مسرعا إذ دخله الشيطان ودفعه الى الشر وتعدى على المذبح المقدس الطاهر . أما البابا البطريرك فأكمل صلاة القداس بكل هدوء وكمال ." } },
      { kind: 'reading', text: { en: "On the following day the Patriarch held a council from the bishops who were with him, the priests, and the scholars and they excommunicated this bishop and appointed another in his stead. That Bishop became furious, Satan entered his heart and he went to the Governor of Egypt Ahmad Ebn-Tolon and told him: \"The Patriarch is very wealthy, and his churches are filled with vessels, in gold and silver.\"", ar: "وفى (اليوم التالي عقد البطريرك مجمعا من الأساقفة الذبن معه والكهنة والعلماء وحرم ذلك الأسقف وأقام غيره . فازداد غضبا وأضمر سوءا إذ حل الشيطان فى قلبه فقام ومضى الى والى مصر" } },
      { kind: 'reading', text: { en: "This Governor was preparing to go to war and needed funds to finance these preparations. He called the Patriarch and demanded the church funds and its vessels, but the Patriarch refused. He shut him up in prison with a deacon whose name was Ebn El-Monzer for a year during which the Pope ate only bread, salt, and boiled beans. John and Moses, two scribes of the Governor, agreed with the scribes of the Governor's minister John and his son Macarius to free the father the Patriarch and they asked for the minister's help who agreed to their request. He interceded on their behalf before the Governor Ebn-Tolon who agreed on a condition that the Patriarch pay him 20 thousand Dinar. The Patriarch wrote a promissory note to pay the amount on two installments: the first after one month and the second after four month and this way he was able to leave the prison. When the time came to pay the first instalment those scribes paid two thousand dinar, the minister contributed one thousand and Anba Michail paid seven thousands, he collected from the bishops and the believers.", ar: "احمد .أبن طولون وقال له : &quot; ان البطريرك كثير الثروة ، واسع الغنى ، ا وكان هذا الوالي آخذا فئ الاستعداد للذهاب الى الحرب ومحتاجا إلى النفقات فأستدعي الأب البطريرك وطلب منه أموال الكنائس وأوانيها . فأبي أن يعطيها نه فطرحه فى السجن مع شماس اسمه ابن المنذر مدة سنة كاملة ، كان خلالها لا يقتات بغير الخبز والبقول المسلوقة والملح . فاتفق يوحنا وموسى من كتاب الوالي مع كاتبى وزيره يوحنا ومقار ابنه على إنقاذ الأب البطريرك واستغاثوا بالوزير فلبي دعوتهم ، وشفع لدى الوالي على شرط دفع مبلغ 20 ألف دينار لابن طولون . فكتب البطريرك تعهدا على نفسه بدفع المبلغ علي قسطين : الأول بعد شهر ، والثاني بعد أربعة أشهر وبهذا أمكنه الخروج من السجن . فنما جاء ميعاد القسط الأول دفع أولئك الكتاب ألفى دينار ، وتبرع الوزير بألف .. ودفع هذا الأب سبعة آلاف جمعها من الأساقفة والمؤمنين . وأراد أن يتدبر العشرة الآلاف الأخرى قيمة القسط الباقي . فقصد بلدة بلبيس . وبينما هو يفكر فى الأمر إذ براهب رث اللباس مر بتلاميذه وقاك لهم : &quot; امضوا وقولوا لمعلمكم ان الرب سيمزق عنه صك الغرامة بعد أربعين يوما &quot; . فلما علم الأب بذلك طلب الراهب فلم يجده . وفد تم ذلك ، إذ لم تمض تلك المدة حتى توفى ابن طولون ، وتولى مكانه ابنه خمارويه سنة875 م . . فرأى هذا أن يخلى طرف البطريرك -. فاستدعاه وطيب خاطره ثم مزق الصك أما الرجل الشرير الذي سبب هذه المتاعب لقداسة البابا فقد نزل به غضب الله فى الحياة . والممات ، ليكون عبرة لمن يعتبر . وقد قضى هذا الأب على الكرسي المرقسى سبعا وعشرين سنة وشهرا واحدا وتسعة أيام ثم تنيح بسلام . صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "The pope was compelled to travel to collect the sum required for the second instalment. When he was at the city of Belbays, a monk with ragged cloth passed by the Pope's disciples and told them: \"Go and tell your teacher that the lord will relieve him from his fine after forty days.\" When the father heard that he sent for that monk but they could not find him. Before that period had passed Ebn-Tolon died and his son Khamarawaih, who forgave the Patriarch of his debt, took his place year 875 A.M. He called the Patriarch, comforted him and then tore up the promissory note as the monk had prophesied.", ar: "" } },
      { kind: 'reading', text: { en: "The wicked Bishop that caused all these troubles for the holy father Anba Mikhail, the wrath of God came upon him in his life and his death to be an example for others. This father spent twenty seven years on the chair of St. Mark, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "Raising of Lazarus from the dead.", ar: "تذكار إقامة لعازر من الموت" } },
      { kind: 'reading', text: { en: "On this day also the Lord raised the righteous lazarus from the dead and many people believed because of this great miracle.", ar: "في مثل هذا اليوم أقام الرب لعازر الصديق من بين الأموات وآمن به في كثيرون لعظم هذه الآية . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-21",
    title: { en: "Baramhat 21", ar: "21 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "Commemoration of the Theotokos and Ever-Virgin St. Mary", ar: "التذكار الشهري لوالدة الاله القديسة مريم العذراء" } },
      { kind: 'reading', text: { en: "On this day we celebrate the commemoration of the pure, and chaste, Virgin Mary the Theotokos, mother of the merciful, and the compassionate One.", ar: "فى مثل هذا اليوم نعيد بتذكار السيدة العذراء الطاهرة البكر البتول الذكية مرتمريم والدة الإله الكلمة أم الرحمة، الحنونة شفاعتها تكون معنا . آمين ." } },
      { kind: 'reading', text: { en: "May her intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "Commemoration of the visit of Our Lord Christ to Bethany", ar: "دخول المخلص بيت عنيا" } },
      { kind: 'reading', text: { en: "On this day also we commemorate the visit of Our Lord, God, and Savior Jesus Christ with his disciples to Bethany, which is near by Jerusalem. Lazarus, who had been dead, and Jesus raised him, sat at the table with Him, and Martha his sister served those who were present. Then Mary took a pound of very costly oil of spikenard, anointed the feet of Jesus, and wiped His feet with her hair, and the Lord praised her. He pointed out to His death by saying: “She has kept this for the day of My burial.” (John 12:1-8)", ar: "فى مثل هذا اليوم نعيد بتذكار حضور ربنا وإلهنا ومخلصنا يسوع المسيح مع تلاميذه الى بيت عنيا القريبة من أورشليم ، حيث كان لعازر الذي أقامه من بين الأموات أحد المتكئين معه كانت مرثا أخته تخدم الجمع الحاضر ، ومريم تدهن قدمي المسيح بالطيب ، وتمسحهما بشعرها ، فمدحها الرب. . وأشار عن موته بقوله أنها ليوم تكفيني قد حفظته &quot; (1 يو 12 : 1-8)" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "Consultation of the Chief Priests to put the righteous Lazarus to death", ar: "تشاور عظماء الكهنة على قتل لعازر الصديق الذي أقامه الرب" } },
      { kind: 'reading', text: { en: "On this day also was the consultation of the chief Priests to put the righteous Lazarus to death, whom the Lord raised from the dead. For many, because of the greatness of this sign, had believed in Our lord Jesus christ.", ar: "في مثل هذا اليوم تشاور عظماء الكهنة على قتل لعازر الصديق الذي أقامه المسيح من الأموات ، لأن الكثيرين - بسبب عظم هذه الآية آمنوا بربنا يسوع المسيح . الذي له المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "To Him is the Glory forever. Amen.", ar: "" } },
      { kind: 'reading', text: { en: "May his intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "", ar: "نياحة انبا فريج" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة انبا فريج (أنبا رويس ) . صلاته تكون معنا و لربنا المجد دائما ابديا امين ." } }
    ],
  },
  {
    id: "synax-baramhat-22",
    title: { en: "Baramhat 22", ar: "22 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Kyrellos (Cyril), Bishop of Jerusalem.", ar: "نياحة أنبا كيرلس أسقف أورشليم" } },
      { kind: 'reading', text: { en: "On this day of the year 386 A.D. the holy father Anba Kyrellos (Cyril), Bishop of Jerusalem, departed. This father was chosen in the year 348 A.D. as a successor for Anba Maximus, Bishop of Jerusalem, for his knowledge and righteousness. He did not stay long on his Chair, until a contention arose between him and Acacius Bishop of Caesarea about who had the right to be in primacy over the other. Kyrellos argument in that he was the successor of \r\n.", ar: "فى مثل هذا اليوم من سنة 386 ميلادية تنيح الأب القديس الأنبا كيرلس أسقف أورشليم . وكان هذا الأب قد اختير فى سنة 348 م خلفا للأنبا مكسيموس أسقف أورشليم ، نظرا نعلمه وتقواه ولم يلبث على كرسيه طويلا حتى حصلت منازعات بينه وبين أكاكيوس أسقف قيصرية نحو من منهما له حق التقدم على الآخر، وكانت حجة كيرلس فى ذلك أنه خليفة القديس يعقوب أحد الاثنى عشر رسولا . وحدث أن انتهز أكاكيوس فرصة بيع الأنبا كيرلس لآواني الكنيسة وتوزيع ثمنها على المعوزينء على أثر مجاعة شديدة حصلت فى فلسطين المساعي حتى حصل على أمر بنفيه من البلاد . فنفى ولم يستمع أحد لدعواه . وفى ستة 359 م استأنف دعواه أمام مجمع سلوكية ، فدعا المجمع أكاكيوس ، فيسمع منه حجته فلم يحضر فحكم عليه بالعزل ، وطلب إعادة كيرلس الى كرسيه فعاد ، ولكنه لم يمكث طويلا لأن أكاكيوس عاد فأغرى الملك قسطنس بعقد مجمع فى القسطنطينية . وشايعه الأساقفة الاريوسيون فعقد هذا .المجمع فى سنة 360 م، وأصدر أمره بعزل هذا القديس مرة ثانية ولما مات قسطنس وخنفه يوليانوس أمر بعودة الأساقفة المنفيين الى كراسيهم . فعاد هذا القديس الى كرسيه فى سنة 362 م وأخذ يرعى شعبه بأمانة واستقامة ، ولكنه كان يقاوم الاريوسيين فسعوا الى الملك فالنز الاريوسى حتى أبطل أمر يوليانوس سلفه ، القاضي بعودة الأساقفة المنفيين الى كراسيهم . وهكذا عزل هذا القديس للمرة الثالثة . فبقى منفيا الى أن مات فالنز فى سنة 379 م ولما تملك تاؤدوسيوس الكبير وجمع مجمع المئة والخمسين على مكدونيوس ( وهو المجمع المسكونى الثاني) حضر فيه هذا الأب ، وقاوم مكدونيوس وسابليوس ، وغيرهما من المبتدعين -. وقد ألف القديس كتبا وعظات كثيرة مفيدة فى عقائد الإيمان والتقليدات القديمة ثم تنيح بسلام . صلاته تكون معنا . آمين .." } },
      { kind: 'reading', text: { en: "Anba Kyrellos had sold some of the church vessels and distributed the money on the needy because of a famine that befell the land of Palestine. Acacius took this chance and made an effort to obtain an order to exile him from the country. Anba Kyrellos was exiled without any one listening to his case. In the year 359 A.D., he appealed his case before the council of Seleucia. The council called Acacius to hear from him his argument, but he did not attend, so they judged by removing him from his office, and the return of Kyrellos to his Chair (Parish). He did not stay long for Acacius went and enticed emperor Constans to assemble a council at Constantinople and the Arian bishops agreed with him. This council convened in the year 360 A.D. and ordered to exile this saint once more.", ar: "" } },
      { kind: 'reading', text: { en: "When Constans died, and was succeeded by Julian who ordered the return of all the exiled bishops to their chairs. This saint returned to his chair in the year 362 A.D. and shepherded his people faithfully and honestly, but he resisted the Arians. They went to emperor Valens the Arian who invalidated the order of his predecessor Julian stating the return of the exiled bishops to their chairs. This way St. Kyrellos was exiled for the third time, where he remained until the death of Valens in the year 379 A.D. When Theodosius the great reigned and assembled the one hundred fifty in a council against Macedonius (The second universal council), this father attended, and opposed Macedonius, Sabilius and other heretics. This Saint composed many Homilies and Exhortations, exceedingly profitable, in the Doctrines of faith and old traditions then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Michael, Bishop of Naqadah.", ar: "نياحة القديس ميخائيل أسقف نقاده" } },
      { kind: 'reading', text: { en: "On this day also the honored father, and the unblemished bishop Anba Michael bishop of the Chair of Naqadah, departed.", ar: "فى مثل هذا اليوم تنيح الأب الأسقف المكرم الكامل صاحب الشيخوخة الحسنة والذكر الجميل الأنبا ميخائيل أسقف كرسى نقاده . رحمنا الله بصلواته . ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "With his prayers may the Lord have mercy on us, and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-23",
    title: { en: "Baramhat 23", ar: "23 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of the Great Prophet Daniel.", ar: "نياحة دانيال النبى" } },
      { kind: 'reading', text: { en: "On this day of the last year of king Cyrus King of Babylon, the great righteous prophet Daniel Departed. This prophet was from the tribe of Judah, and from the posterity of\n. He was taken captive along with the Israelites by Nebuchadnezzar, king of Babylon when he captured Jerusalem in the year 3398 of the world. He stayed in babylon for seventy years. This prophet was very young in age, however, he conducted himself in virtuous life, the Holy Spirit filled him and he prophesied in Babylon.", ar: "في مثل هذا اليوم من السنة الأخيرة لملك قورش تنيح الصديق العظيم دانيال النبى . كان هذا النبى من سبط يهوذا ومن نسل داود الملك . وسباه نبوخذ نصر ملك بابل مع الشعب ،الإسرائيلي عندما استولى على أورشليم سنة 3398 للعالم ، ولبث فى بابل مدة سبع سنين . وكان هذا النبى صغير السن . ومع هذا سلك سيرة فاضلة كاملة ، وحل عليه روح الله وتنبأ فى بابل" } },
      { kind: 'reading', text: { en: "In the fourth year of the exile, Nebuchadnezzar the king saw a dreadful dream and was extremely frightened. When he woke up, he forgot the detail of his dream. He gathered all the wise men of Babylon to tell the king his dream and its meaning. If they failed to tell the king the dream and its interpretation they would all be killed, among those also were Daniel and\nthe three young men. Daniel and the young men prayed to God with supplications to reveal to them the King's dream. God answered their prayers and revealed to Daniel the dream and its interpretation. Daniel went to the king and told him his dream and its interpretation. He also told him about the kings that they are about to rule after him, and what would happen to every one of them. Nebuchadnezzar was pleased with Daniel, and fell on his face before him. The king presented Daniel with great gifts and appointed him over the wise men of Babylon.", ar: "" } },
      { kind: 'reading', text: { en: "After some time had passed, Nebuchadnezzar saw another dream, and Daniel interpreted the dream for him. Daniel told the king that because of his arrogance, God would drive him from among men, to dwell among the beasts of the wild and would eat grass like oxen for seven years, and then God would bring him back to his kingdom, and all that happened to Nebuchadnezzar. Daniel also explained to Belshazzar, the son of Nebuchadnezzar, what the\nangel of the Lord had written on the wall, when king Belshazzar drank wine in the gold and silver vessels of the temple of the Lord. Daniel told the king: \" O king, the Most High gave Nebuchadnezzar your father, a kingdom and majesty, glory and honor... But when his heart was lifted up in pride, he was deposed from his kingdom and thrown from his throne into among the animals. And you, Belshazzar, although you knew all what happened to your father, yet you also lifted your heart against the Lord of heaven. They brought the vessels of the house of the Lord before you, and you , your lords, wives and concubines (mistresses) drank wine from these vessels... Then the fingers of a Hand were send from the Lord, and His writing was written: \"Mene, Mene, Tekel, and Upharsin..which meant:", ar: "" } },
      { kind: 'reading', text: { en: "Mene means: God has numbered your days as a king and terminated you rule. Tekel means: You have been weighed in the balances of the Lord and was found wanting. Upharsin means: your kingdom has been divided and given to the Medes and Persians after you. All of them came to pass and the king was killed with all his lords and the kingdom of the Chaldeans ended. Darius, king of Persia, ruled after him.", ar: "" } },
      { kind: 'reading', text: { en: "There was an idol in Babylon named \"Bael\" which king Darius worshiped. When Daniel was asked why he did not worship it, Daniel answered: \"I do not worship something that has no life in it.\" The king said to him: \"He is alive for he eats and drinks every day.\" Daniel told him that could not be true. The king was angry and wanted to check the matter for himself. He put the food and the drinks in the temple of the idol and closed the door and sealed it. On the next day, he went to the temple, opened the door and did not find the food nor the drinks. But Daniel with the help of some of his companions, covered the floor of the temple with fine ashes, found the feet tracks of those who entered the temple by night and stole the food and drinks.", ar: "" } },
      { kind: 'reading', text: { en: "The king arrested the seventy priests of the idol Bael, together with their wives and children and tortured them until they told him about the secret entrance to the temple. The king then ordered them all to be killed and allowed Daniel to destroy the idol and its altar. The people rebelled against the king and asked him to deliver Daniel to their hands. The king surrendered to their demands and Daniel was cast into the den of lions. However God kept Daniel safe and destroyed his enemies.", ar: "" } },
      { kind: 'reading', text: { en: "Daniel saw in a\nvision the kingdoms and the kings to come after him to rule the world to the end of time. He also saw the glory of God and the Divinity of Christ the Savior. He prophesied about His coming and His death, the destruction of Jerusalem, and the abolition of the sacrifice and the offerings, and all has been fulfilled.", ar: "" } },
      { kind: 'reading', text: { en: "This great prophet remained in Babylon for seventy years, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us, and glory be to God for ever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-24",
    title: { en: "Baramhat 24", ar: "24 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of Anba Macarius, the Fifty-Ninth Pope of Alexandria.", ar: "نياحة البابا مقاريوس ال 59" } },
      { kind: 'reading', text: { en: "On this day also of the year 668 A.M. (May 20th. 952 A.D.) St. Macarius the fifty ninth Pope of Alexandria, departed. He was born in the city of Shoubra. He rejected the world since his youth and he desired the monastic life. He went to the monastery of St. Macarius at the wilderness of Sheahat (Scetis). He lived in virtues and good conduct made him worthy to be chosen a Patriarch, and a successor for Pope Cosma. He was enthroned on the\nfirst of Baramouda 648 A.M. (March 27th. 932 A.D.).", ar: "فئ مثل هذا اليوم من سنة 668 ش ( 0 2 مايو سنة 1952 م ) تنيح الأب القديس الأنبا مقاريوس التاسع والخمسون من باباوات الكرازة المرقسية . وقد ولد فى بلدة شبرا وزهد العالم منذ صغره واشتاق الى السيرة الرهبانية . فقصد جبل شيهيت بدير القديس مقاريوس ، وسار فى سيرة صالحة أهلته لانتخابه بطريركا خلفا للبابا قزما . فاعتلى الكرسي المرقسى فى أول برمودة سنة 648 ش ( 27 مارس سنة 932 م ) ." } },
      { kind: 'reading', text: { en: "When he went forth from Alexandria going to visit the monasteries in the desert of Scetis according to the custom of his predecessors, he passed by his home town to visit his mother who was a righteous woman. When his mother heard that he had arrived she did not go out to meet him. When he had come to the house, he found her sitting down weaving and she did not greet him or paid attention to him. He thought that she did not know him. He told her: \"Don't you know that I am your son Macarius who was elevated to a great position and became a head for a great nation?\" She answered him with tears in her eyes: \"I did not ignore you and I know what became of you, but I would have rather seen you dead than seen you as a Patriarch. Before, you were responsible only for your own soul but now your are responsible about the souls of all your flock: Now remember you are in danger and it is difficult to escape it.\" She said that and went on weaving as she did before.", ar: "وحدث لما خرج من الإسكندرية قاصدا زيارة الأديرة ببرية شيهيت كعادة أسلافه ، أن مر على بلدته لافتقاد والدته . وكانت امرأة بارة صالحة . فلما سمعت بقدومه لم تخرج إليه . ولما دخل البيت وجدها جالسة تغزل فلم تلتفت إليه ، ولا سلمت عليه . فظن أنها لم تعرفه . فقال لها : ( ألا تعلمين أنى أنا ابنك مقاريوس الذي رقى درجة سامية ، ونال سلطة رفيعة ، وأصبح سيدا لامة كبيرة ؟ ) فأجابته وهى دامعة العين : &quot; أنى لا أجهلك وأعرف ما صرت إليه ، ولكنى كنت أفضل يا أبني أن يؤتى بك الى محمولا على نعش ، خير من أن أسمع عنك أو أراك بطريركا . ألا تعلم أنك قبلا كنت مطالبا بنفسك وحدها . أما ألان فقد صرت مطالبا بأنفس رعيتك . فاذكر انك أمسيت فى خطر ، وهيهات أن تنجو منه &quot; . . قالت له هذا وأخذت تشتغل كما كانت." } },
      { kind: 'reading', text: { en: "The father the Patriarch left her sad, and attended to his office with delegant and care. He instructed his people with preaching and sermons. He did not touch any of the church revenue, and did not lay his hand on any one without people consent. He commanded the bishops and the priests to watch their flock and to protect them with homilies and admonitions. He sat on the throne of\nSt. Mark twenty years in peace and tranquility, then departed in peace.", ar: "أما الأب البطريرك فخرج من عندها حزينا ، وباشر شئون وظيفته ، منبها الشعب بالوعظ والإرشاد ، ولم يتعرض لشيء من أموال الكنائس ، ولا وضع يده .على أحد إلا بتزكية . وكان مداوما على توصية الأساقفة والكهنة برعاية الشعب وحراسته بالوعظ والتعليم ، وأقام على الكرسي الرسولى تسع عشرة سنة واحد عشر شهرا وثلاثة وعشرين يوما فى هدوء وطمأنينة . ثم تنيح بسلام . صلاته تكون معنا . ولربنا المجد دائما -. آمين ." } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Apparition of the Pure Lady the Virgin in the church of Zeiton.", ar: "تجلى العذراء بالزيتون" } },
      { kind: 'reading', text: { en: "On the eve of this day of the year 1684 A.M. which coincide with tuesday the 2nd. of April 1968 A.D., during the papacy of\n, our Lady and the pride of our faith started to transfigure in luminous spiritual forms in and around the domes of the church dedicated to her immaculate name in Zeiton, a suburb of Cairo.", ar: "في مساء مثل هذا اليوم من سنة 1684 للشهداء الموافق الثلاثاء الثاني من شهر أبريل سنة 1968 لميلاد المسيح ، فى عهد البابا كيرلس السادس المائة والسادس عشر من باباوات الإسكندرية ، بدأت سيدنا كلنا وفخر جنسنا مريم العذراء تتجلى فى مناظر روحانية نورانية فى وعلى قباب الكنيسة المدشنة باسمها الطاهر فى حدائق الزيتون من ضواحي مدينة القاهرة" } },
      { kind: 'reading', text: { en: "This transfiguration continued in following nights in a manner that was never known in the East or the West. This transfiguration in some nights was as long as many hours, without stop, in front of tens of thousands of people from every race and religion, with every one seeing her, pointing at her and interceding to her with songs, hymns, tears, prayers and hails and She was looking to them in a compassionate way raising her hand at times to bless them in all directions.", ar: "وقد توالى هذا التجلي فى ليال متعاقبة بصورة لم يعرف لها نظير فى الشرق أو فئ الغرب ، ويطول هذا التجلي فى بعض الليالي الى بضع ساعات دون توقف أمام عشرات الألوف من البشر من جميع الأجناس والأديان ، والكل يراها بعيونهم ، ويشيرون إليها ويستشفعون بها فى ترتيل وابتهال ودموع وتهليل وصلاة وهى تنظر الى الجماهير نظرة حانية ، ترفع أحيانا كلتا يديها لتباركهم من جميع الاتجاهات . وأول من لاحظ هذا التجلي هم عمال مؤسسة النقل العام بشارع طومان باى الذي تطل عليه الكنيسة وكان الوقت مساء ، فرأى الخفير عبد العزيز على ، المكلف بحراسة الجراج ليلا ، جسما نورانيا متألقا فوق القبة فأخذ يصيح بصوت عال &quot; نور فوق القبة &quot; ونادى على عمال الجراج فأقبلوا جميعا وشهدوا أنهم أبصروا نورا وهاجا فوق القبة الكبرى للكنيسة وأحدقوا النظر فرأوا فتاة متشحة بثياب بيضاء جاثية فوق القبة وبجوار الصليب الذي يعلوها . ولما كان جدار القبة مستديرا وشديد الانحدار فقد تسمرت أقدامهم وهم يرقبون مصير الفتاة . مضت لحظات شاهدوا بعدها الفتاة .الجاثية وقد وقفت فوق .القبة فارتفعت صيحاتهم إليها مخافة أن تسقط ، وظنها بعضهم يائسة تعتزم الانتحار فصرخوا لنجدتها وأبلغ بعضهم شرطة النجدة ، فجاء رجالها على عجل وتجمع المارة من الرجال والنساء ، وأخذ منظر الفتاة يزداد وضوحا ويشتد ضياء. وظهرت الصورة واضحة لفتاة جميلة فى غلالة من النور الأبيض السماوي تتشح برداء أبيض وتمسك فى يدها بعض من أغصان شجر الزيتون ،وفجأة طار سرب الحمام الأبيض الناصع البياض فوق رأسها وحينئذ أدركوا أن هذا المنظر روحاني سماوي . ولكي يقطعوا الشك باليقين سلطوا أضواء كاشفة على الصورة النورانية فازدادت تألقا ووضوحا، ثم عمدوا الى تحطيم المصابيح الكهربائية القائمة بالشارع والقريبة من الكنيسة فلم تختف الصورة النورانية فأطفأوا المنطقة كلها فبدت الفتاة فى ضيائها السماوي وثوبها النوراني أكثر وضوحا ، وأخذت تتحرك فى داخل دائرة من النور يشع من جسمها الى جميع الجهات المحيطة بها .ء عندئذ أيقن الجميع بأن الفتاة التى أمامهم هى دون شك مريم العذراء ، فعلا التصفيق والصياح والتهليل حتى شق عنان السماء هى العذراء . . هى أم النور . -. . &quot; ثم انطلقت الجموع تنشد وترتل وتصلى طوال الليل حتى صباح اليوم التالي . . ومنذ هذه الليلة والعذراء الطاهرة تتجلى فى مناظر روحانية مختلفة أمام الألوف وعشرات الألوف من الناس مصريين و أجانب ، مسيحيين وغير مسيحيين ، رجالا وسيدات وأطفالا ، ويسبق ظهورها ويصحبه تحركات لأجسام روحانية تشق سماء الكنيسة وبصورة مثيرة جميلة ترفع الإنسان الطبيعي فوق مستوى المادة وتحلق به عاليا فى جو من الصفاء الروحي" } },
      { kind: 'reading', text: { en: "The first one to notice this transfiguration was the workmen at the garage of the Public Transit System which was across the street from the church. The watchman Abdel-Aziz Aly, who was in charge of guarding the garage at that night, saw a luminous body over the dome of the church. He started shouting: \"light over the dome\" and he called the other workers in the garage. They all came and saw the bright light over the large dome of the church. When they looked closely, they saw a young lady in white, kneeling by the cross at the top of the dome. Because the dome had a round, smooth, and very sloping surface, it held the men as though they were nailed in their places watching the fate of the lady. Few seconds passed then they saw the kneeling lady as she stood over the dome. They gave out a cry of fear that she might fall down. They thought she was a girl in despair trying to commit suicide and they cried warning that person not to jump down and some of them called the police. The pedestrians, men and women started to gather around. The view of the lady was getting more clear and she appeared as a beautiful girl in a bright gown of light and had branches of olive tree in her hand, and around her flew white doves. Then they realized that they were seeing a heavenly spiritual view. They directed flood light to the luminous picture to remove all doubt from their minds, but instead it became more clear and bright. They cut the electricity off all the area but the lady remained in her heavenly illumination and her bright gown of light became more clear. She started moving around in a circle of light radiating from her body to all the directions around her. All the people then realized that this lady in front of them, without no doubt is the\nVirgin Mary. They started to shout and cry saying: \"She is the Virgin ... She is the Mother of Light ... \" They prayed with songs, hymns and hails all the night until the next morning.", ar: "ومن أهم المناظر التى تجلت فيها أم النور أمام جميع الناس . منظرها بين القبة القبلية الغربية للكنيسة والقبة الوسطى .وهى تبدو فى جسم نوراني كامل فى الحجم الطبيعي لفتاة شابة وأحيانا أكبر من الحجم الطبيعي ، رأسها فى السماء وكأنها شقت السماء ونزلت منها ، وقدماها فى الفضاء واقفة على أصابعها ، تحيط رأسها المقدس وجسمها المضيء طرحة فضية بهية ، وأحيانا زرقاء سماوية داكنة ، والجسم كله نور من نور يبدو فى الغالب فوسفوريا يميل الى الزرقة الفاتحة ، وأحيانا يبدو الرداء من تحت الطرحة نورانيا أبيض ناصعا ، والرأس من تحت الطرحة منحنية الى أسفل فى صورة العذراء الحزينة ونظراتها نحو الصليب الذي يعلو القبة الكبرى فى منتصف سطح الكنيسة ،. والمنظر يثبت على هذا الوضع حينا ويتحرك حينا فى هدوء وبطء ، وينحنى أمام الصليب حينا آخر والصليب نفسه يضئ ويشع نورا مع أنه من المسلح وهو جسم معتم . ويشع من جسم العذراء نور ينتشر فى تدرج يضئ سماء الكنيسة فى محيط يشغل معظم مساحة السطح . وقد ترفع العذراء يديها ثم تخفضهما وقد تعقدهما على صدرها كمن يصلى ، وهى ملفوفة فى طرحتها البيضاء فى نظرات الهدوء والسكينة والوقار . وأحيانا يظهر من خلفها ملاك فارع الطول فاردا جناحيه وقد يطول المنظر الى بضع ساعات. ومن أهم المناظر أيضا منظر أم النور فى وقفة ملكة عظيمة فى صورة روحانية جميلة تفيض جلالا وبهاء وكرامة ، فى نور أبهى لمعانا من إي نور طبيعي ، تحيط بوجهها هالة بلون أصفر فاتح . وأما أسفل العنق وأعلى الصدر فبلون داكن نوعا ما ، وعلى رأسها تاج ملكي كأنه من الماس مرصع ويلمع. وأحيانا يبدو فوق التاج صليب صغير مضيء ، وقوامها المشرق يرتفع فى السماء فوق شجرة بالجهة القبلية من الكنيسة وفى موقفها السابق تبدو حاملة المسيح له المجد فى صورة طفل على يدها اليسرى. وعلى رأسه تاج --. وتارة تظهر ويداها تضمان أطراف ثوبها ، وتارة أجرئ ترفع كلتا يديها وكأنها تبارك العالم وهى تتجه الى اليمين والى الأمام والى اليسار فى حركة وقورة متزنة يجللها سمو روحاني لا يعبر عنه ولا ينطق به ، ورداؤها الأبيض يهفهف من ذيله وكأنها تظهر ذاتها لجميع الناس فى جميع الاتجاهات مشفقة على الذين لم يستطيعوا لكثرة الزحام أن يصلوا الى زاوية الرؤيا المواجهة لمدخل الكنيسة فى الحارة الضيقة المسماة -حارة خليل . وفى هذا المنظر تبدو العذراء الطاهرة فى الحجم الطبيعي لعذراء شابة فى قامة صحية مثالية وجسم فارع رقيق تكسوه غلالة -من نسيج نوراني حتى القدمين ويزداد المنظر روعة عند انحناءة الرأس المقدس فى شبه إيماءة حانية ." } },
      { kind: 'reading', text: { en: "Since that night the pure Virgin had transfigured in different spiritual views in front of thousands and ten of thousands of masses, Egyptian and foreigners, Christians and non-christians, men, women and children. Spiritual beings formed like doves would appear before, during and after the transfiguration zooming through the sky in a way raising the human from a materialistic to a heavenly atmosphere.", ar: "ولعل أكثر المناظر ظهورا تجليها عديدا من المرات فى شكل فتاة ترتدى طرحة بيضاء تطل من طاقة فى القبة الشرقية البحرية بين طاقات هذه القبة تومىء برأسها الملكي أو ترفع كلتا يديها وكأنها تحيى أو تبارك . وتارة تبدو حاملة المسيح له المجد فى صورة طفل" } },
      { kind: 'reading', text: { en: "This transfiguration was in different forms. One of the most significant ways this apparition took place was that; the head of St. Mary under the vail looking down as in the picture of the sad Virgin and she was looking toward the Cross and that view would stay like this at times or slowly bow before the Cross at other times. The Cross itself will shine and illuminate although it was made of concrete. And some times an angel would appear standing behind her spreading his wings. That view might stay as long as many hours.", ar: "على يدها اليسرى وأحيانا تبدو وفى إحدى يديها غصن زيتون والملاحظ أنه قبل أن تتجلى العذراء فى إحدى طاقات هذه القبة - وهى عادة مظلمة حالكة الظلام لأنها مغلقة تماما من أسفل سقف الكنيسة بحيث لاتصل أتليها أنوار الكنيسة من الداخل عندما تكون مضاءة يظهر.أولا فى القبة نور خافت لا يلبث أن يكبر شيئا فشيئا حتى يصير فى حجم كروى تقريبا ولونه أبيض مائل الى الزرقة كلون قبة السماء الزرقاء عندما تكون الشمس مشرقة ساطعة . وبعد قليل يتحرك هذا النور فى اتجاه طاقة القبة من الخارج . وفى أثناء تحركه البطيء يتشكل رويدا رويدا بشكل العذراء مريم فى منظر نصفى من الرأس حتى منتصف الجسم ، والرأس تحيط به الطرحة التى تبدو بلون أزرق سماوي متدلية على كتفها ويبرز هذا الجسم النوراني متمثلة فيه العذراء ويطل من طاقة القبة ويخرج بعض الشيء وخارج القبة الى فضاء الكنيسة ، وأحيانا يقف على سطح القبة المنحدر. وقد يبقى هذا المنظر دقائق وقد يبقى من ربع الى نصف ساعة . وفى أحيان أخرى يتكون المنظر ويبرز خارج القبة نحو دقيقتين ، ثم يتحرك الى داخل القبة وحينئذ يبهت شكله ويعود الى شكله الكروي ثم ينطفئ أو يختفي بضع دقائق ثم يبدأ أن يظهر من جديد فى شكل ضوء خافت ثم يكبر حتى يصير فى حجم كروى ، ثم يتحرك تجاه طاقة القبة وفى حركته يتشكل بشكل العذراء مريم وهى تطل على الجماهير . وهكذا عديدا من المرات كما حدث هذا مثلا فى ليلة عيد دخول العائلة المقدسة الى مصر ( 24،، بشنس الموافق أول يونية 1968 ) فقد توالى تجلى العذراء فى القبة البحرية الشرقية مرات لا يحصيها العد من الساعة العاشرة مساء حتى بزوغ نور الصباح ، وهو أكثر المناظر التى تتكرر مرات ومرات فى ليال عدة لا حصر لها ، وهو المنظر المتواتر الظهور الذي تمتع به أكبر عدد من الناس . ومن بين المناظر الرائعة جدا هذا المنظر الذي تبدو فيه العذراء جسما بلوريا مضيئا ناصعا جدا وهى واقفة وقفة ملكية فى قامة" } },
      { kind: 'reading', text: { en: "Another view was the view of the Mother of Light standing as a great Queen in a beautiful spiritual portrait radiating dignity, elegance and beauty. On her head was a crown of a queen as if it were made of diamonds and some times there appeared on the top of the crown a small luminous cross. And some times she appeared in the same way but carrying Christ, to Him is the Glory, in the form of a child on her hand and on His head a crown. And on other times she raised her both hands as She was blessing the world moving to the right, to the front, and to the left in a dignified way.", ar: "منتصبة ممشوقة تملأ إحدى طاقات القبة البحرية الغربية فى حجم صغير متناسق وكأنها.تمثال من النور الوضاء المشع الأبيض الناصع البياض يمتد كاملا من الرأس الى القدمين فى كل طاقة القبة بشكل يريح القلب والنفس ويشيع الآمن والسكينة فى كل الإنسان حتى ينسى وجوده أمامه من فرط ما يتولاه من انبهار وانجذاب ." } },
      { kind: 'reading', text: { en: "Many spiritual signs appeared before, during, and after the apparition of the Virgin the mother of the Lord's transfiguration. The appearance of tongues of yellowish flame would flash over the church and then subside and that repeated several times. Another form of the signs were the spiritual beings formed like doves, larger than the doves that we know, appear about midnight or after, flying in the middle of darkness illuminating in a fast speed, appeared suddenly from no where, and also disappeared suddenly. These spiritual beings appeared in different formations and in varying numbers. A fact we should be aware of that pigeons do not fly during the night. Another sign was the shooting stars which were constantly falling and were seen very close to the apparition on many occasions as if coming down to glorify her from heaven. Another sign was the fragrance of incense. The smoke of the incense poured out of the domes in large quantities. Substance resembling clouds, thick fog or smoke would roll in toward the church and completely cover the church.", ar: "هذا ويصاحب تجليات أم النور ظهور كائنات روحانية مضيئة تشبه الحمام ، وهى عادة أكبر منه حجما وتظهر نحو منتصف ، الليل أو بعده نحو الثانية أو الثالثة صباحا والمعروف أن طائر الحمام العادي لا يطير ليلا . ثم أن هذه الكائنات بيضاء لامعة مشعة بصورة لا يوجد لها نظير فى عالم الطيور ، خاصة وأنها تظهر فى وسط الظلام الحالك متوهجة منيرة من كل جانب من فوق ومن أسفل ثم أنها تتحرك أو تطير فاردة جناحيها من غير رفرفة فى الغالب ، أنها تنساب بسرعة كبيرة وكأنها سهم يشق سماء الكنيسة وتظهر فجأة من حيث لا يعرف الإنسان من أين جاءت وتختفي أيضا فجأة وهى فى مدى الرؤية . ويحدث الاختفاء وتكون السماء صحوا ، وأحيانا ترى وكأنها خارجة من القبة الكبرى وتتجه نحو القبة البحرية الشرقية تختفي لتعود بعد ثوان فى الاتجاه المضاد تماما . على أن هذه الكائنات الروحانية بشكل الحمام تظهر فى تشكيلات وأعداد مختلفة فتارة تظهر حمامة واحدة وتارة حمامتان ، وتارة 3 حمامات فى شكل مثلث متساوي الأضلاع منتظم المسافات وتحتفظ بهذا الشكل فى كل فترة الطيران . وتارة يظهر سرب من سبع حمامات أو عشر حمامات أو اثنتي عشر حمامة وقد تتخذ شكل صليب فى طيرانها وأحيانا فى تشكيل من صفين متوازيين . ومن بين الظواهر الروحية المصاحبة لتجليات العذراء أم النور ظهور نجوم فى غير الحجم الطبيعي تهبط من فوق فى سرعة خاطفة س القبة الوسطى أو على سطح" } },
      { kind: 'reading', text: { en: "Also the illuminated cloud that appeared over the domes of the church in large volume and often proceeded the transfiguration of the Virgin or at times the cloud slowly formed in the shape of the virgin. Sometimes the apparition of the Virgin would appear from the clouds.", ar: "ومضيئة وبراقة . وفى بعض الأحيان يظهر النجم فى حجم كرة منيرة تهبط من فوق الى أسفل وقد يتخذ النجم شكل مصباح مضىء فى حجم متوسط- ومن بين الظواهر المتكررة نور برتقالي اللون يغمر القبة البحرية الشرقية للكنيسة من فوقها ومن جميع الاتجاهات ، وبعد دقائق من ظهوره يتحرك فى اتجاه القبة الكبرى ويغمرها من فوق ومن جميع الاتجاهات وفى أحيان كثيرة ينبعث من داخل القبة البحرية الشرقية خصوصا نور ساطع أبيض مشرب بشيء من الزرقة بحيث يبدو بلون قبة السماء عندما تكون الشمس ساطعة يظهر فى وسط القبة وأحيانا يتحرك من أسفل الى أعلى فيبدو كما لو كان معلقا فى الجزء الأعلى من القبة ،. وفى أحيان أخرى يظهر فى وسط القبة فى شكل كروى أو بيضاوي ثم يتحرك ببطء شديد الى خارج إحدى طاقات أو منافذ القبة المطلة على الخارج قبيل أن يتشكل فى صورة نصفية للسيدة العذراء تطل من طاقة القبة ." } },
      { kind: 'reading', text: { en: "This transfiguration and all the spiritual signs were a forerunner and announcement for serious or important events to come in the near and far future. Or it might be a spiritual gesture from heaven to indicate the Lord's caring for His church and His people and our country.", ar: "- ومن بين الظواهر أيضا نور كبير يظهر على القبة القبلية الغربية أو القبة البحرية الشرقية أو القبة الوسطى فى هيئة صليب يتساوى الأضلاع فى منظر يبلغ حد الإبداع والروعة والجمال . وفى بعض الليالي يغمر القبة الوسطى كمية من بخور أبيض ينتشر فوق سطح الكنيسة كلها ويصعد الى فوق نحو السماء الى مسافة 30 أو 40 مترا ، علما بأن القبة الوسطى وان كانت مفتوحة من داخل الكنيسة لكنها ليست مفتوحة من خارج بحيث ولو صعد بخور من داخل الكنيسة فانه لا ينفذ الى خارج القبة . ثم أن كمية البخور التى تنتشر فوق القبة وسطح الكنيسة كمية ضخمة لا يكفى لتصعيدها ألف ألف مبخرة . ولولا أن هذا البخور عطري ،الرائحة وأبيض اللون وناصع البياض لكان يظن أنه ناجم من حريق كبير ." } },
      { kind: 'reading', text: { en: "May the mercy of God be upon us all. May the Lord keep His people and church in peace, with the intercession of Our Lady and the pride of our race the pure Virgin St. Mary. Amen.", ar: "وهناك أيضا السحاب النوراني الذي يظهر فوق قباب الكنيسة مباشرة تارة بحجم كبير وغالبا ما يسبق تجليات العذراء إذ لا يلبث السحاب قليلا حتى يتشكل رويدا رويدا فى منظر العذراء أم النور. وأحيانا ينبلج منظر العذراء من بين السحاب كما ينبلج نور لمبات النيون الكهربائية فجأة . وأحيانا يتحرك وفى كل الأحوال يتحرك فوق القباب فجأة بحيث تكون السماء صحوا ومن دون أن يجئ من مصدر معروف ." } },
      { kind: 'reading', text: { en: "", ar: "تلك بعض المناظر التى تجلت بها السيدة العذراء على وفى قباب الكنيسة المدشنة باسمها فى ضاحية الزيتون ، والظواهر الروحانية المصاحبة لتلك التجليات . وكلها بشير ونذير بأحداث جليلة خطيرة فى المستقبل القريب والبعيد . ولعلها نفحة روحانية من السماء تشير الى رعاية الله لكنيستنا وشعبنا وبلادنا ، وعنايته بنا مما نعتز به ونفخر متهللين ، وبانسحاق وندامة على خطايانا نتوب الى الله راجعين تائبين . ولعلنا بهذه &quot; العلامات العظيمة من السماء &quot; ( لوقا 21 : 11 ) نكون قد دخلنا مرحلة هامة من مراحل الأيام الأخيرة وربما كانت بداية النهاية . فلتدر كنا مراحم الله . وليحفظ الرب شعبه وكنيسته ، وليحطم قوة المعاندين لنا بشفاعة ذات الشفاعات معدن الطهر والجود والبركات سيدنا كلنا وفخر جنسنا العذراء البتول الزكية مريم ، ولإلهنا المجد دائما أبديا آمين ." } },
      { kind: 'heading', text: { en: "", ar: "نياحة ميخا النبى" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة ميخا النبى . صلاته تكون معنا و لربنا المجد دائما ابديا امين ." } }
    ],
  },
  {
    id: "synax-baramhat-25",
    title: { en: "Baramhat 25", ar: "25 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "", ar: "نياحة القديس أنيسوفورس أحد السبعين رسولا" } },
      { kind: 'reading', text: { en: "", ar: "في هذا اليوم تذكار نياحة القديس أنيسوفورس أحد السبعين رسولا. صلاته تكون معنا و لربنا المجد دائما ابديا امين ." } },
      { kind: 'heading', text: { en: "", ar: "نياحة القديس فريسكا أحد السبعين رسولا" } },
      { kind: 'reading', text: { en: "", ar: "في مثل هذا اليوم تنيح القديس العظيم فريسكا أو (نيسيفور ) أحد السبعين رسولا هذا الرسول كان من بنى إسرائيل من سبط بنيامين ، ابنا لأبوين حافظين للناموس . وكان من الذين تبعوا المخلص وسمعوا تعاليمه وشاهدوا آياته ومعجزاته" } },
      { kind: 'reading', text: { en: "", ar: "فلما أقاما السيد المسيح له المجد ابن الأرملة بمدينة نايين من الموت ، كان هذا القديس حاضرا ، فتقدم بلا تردد الى الرب يسوع تاركا الاستضاءة بسراج الناموس اليهودي ليستنير بشمس البر. وأمن به من كل قلبه ، ثم تعمد وصار أحد السبعين رسولا . وكان مع التلاميذ فى علية صهيون وقت حلول الروح المعزى . وقد بشر بالإنجيل فى بلاد كثيرة . ثم رسم أسقفا على خورانياس . فعلم أهلها وأنارهم بتعليمه ووعظه ، ثم عمدهم . وبعد أن أكمل سعيه المقدس تنيح بسلام ، ونال إكليل المجد السماوي وعمره سبعون سنة . منها تسع وعشرون سنة يهوديا . وإحدى وأربعون سنة مسيحيا ، وقد ذكره القديس بولس فى رسالتا الثانية الى تيموثاوس (2 تى 4 :19 ) . صلاته تكون معنا . آمين" } },
      { kind: 'heading', text: { en: "", ar: "نياحة البابا متاؤس" } },
      { kind: 'reading', text: { en: "", ar: "فى مثل هذا اليوم من سنة 1362 ش ( 31 مارس 1646 م ) ، فى يوم سبت لعازر ، تنيح البابا متاوس الثالث البطريرك المائة وهو يعرض باسم متى الطوخى . وهو ابن أبوين مسحيين من ناحية طوخ النصارى بإقليم المنوفية . وكانا خائفين من (الله محبين للغرباء ، محسنين للفقراء والمحتاجين . رزقهم الله" } },
      { kind: 'reading', text: { en: "", ar: "بالابن تادرس فأحسنا تربيته وأدباه بكل أدب روحاني وعلماه كتب البيعة المقدسة وحلت نعمة الله علي هذا الابن المبارك فانكب على الدرس والتعليم المسيحى الى أن حركته نعمة الله الى السيرة الملائكية والحياة النسكية فخرج من بلده وترك أهله وأقاربه وتبع قول المسيح له المجد ومضى الى برية شيهيت ميزان القلوب وترهب بكنيسة القديس العظيم أبى مقار فجاهد في النسك والعبادة جهادا بليغا. فرسموه قسا ، فتزايد فى التقشف ، ونما في الفضيلة فأقاموه قمصا ورئيسا علي الدير المذكور ." } },
      { kind: 'reading', text: { en: "", ar: "وبعد قليل تنيح البابا يؤانس الخامس عشر البطريرك التاسع والتسعون ، فاجتمع الآباء الأساقفة وجماعة الكهنة والاراخنة لاختيار من يصلح لاعتلاء الكرسى المرقسى الإسكندري وواظبوا علي الصلاة طالبين من السيد المسيح له المجد أن يقيم لهم راعيا صالحا لكي يحرس شعبه وبإرادة السيد المسيح ، راعى الرعاة ، اتفق رأى الجميع على تقديم الأب تادرس قمص دير أبى مقار بطريركا . فتوجهوا إلى الدير وامسكوه قهرا وكرسوه بطريركا باسم متاوس فئ يوم 4 النسيء سنة 1347 ش ( 7 سبتمبر سنة 1631 م ) . وكان المتقدم في تكريسه الأنبا يؤنس مطران السريان" } },
      { kind: 'reading', text: { en: "", ar: ". فلما جلس هذا البابا علي الكرسى الرسولى رعى رعية المسيح أحسن رعاية ، وكان هدوء وسلام على المؤمنين فى أيامه ، وارتاحت البيع من الشدة التى كانت فيها فحسده إبليس عدو الخير وحرك عليه أعوان السوء فذهبوا إلى الوالي بمصر وأعلموه أن الذي يعتلى كرسى البطريركية كان يدفع للوالى مالا كثيرا ." } },
      { kind: 'reading', text: { en: "", ar: "وأستمع الوالى لوشايتهم ، واستدعى البابا إليه لهذأ الغرض . فقام جماعة الاراخنة وقابلوا الوالى ، فلم يسألهم عن عدم حضور البابا ، بل تكلم معهم في شأن الرسوم التى يدفعها البطريرك وألزمهم بإحضار أربعة آلاف قرش فنزلوا من عنده وهم في غم من جراء فداحة الغرامة ولكن الله عز وجل شأنه الذي لا يشاء هلاك أحد وضع الحنان فى قلب رجل إسرائيلي فقام بدفع المبلغ المطلوب الى الوالى ، وتعهد له الاراخنة برده ووزعوه عليهم ثم سددوه للاسرإئيلى . وجعلوا على البابا شيئا يسيرا من هذه الغرامة الفادحة . فنزل الى الوجه القبلي لجمع المطلوب منه ، ولشدة أيمانه وقوة يقينه فى معونة الله تحنن قلب الشعب عليه وأعطوه (المطلوب عن طيب خاطر وبعد قليل حضر الى الوجه البحري لكي يفتقد رعيته ، فنزل بناحية برما . وأتى إليه هناك أهالي مدينة طوخ بلده ، ودعوه لزيارة الناحية ليتباركوا منه ، فأجاب الطلب . وفى زمن هذا البطريرك وقع غلاء عظيم فى كل أرض مصر ، لم يصل مثله قط ، حتى وصل ثمن إردب القمح الى خمسة دنانير ولم يتمكنوا من شرائه . ولم يتيسر الحصول عليه إلا عند القليل من الناس ، حتى أكل الأهالي الميتة ، ومنهم من أكلوا لحم الدواب فتورموا وماتوا ، ومنهم من دقوا العظم وأكلوه ، ومنهم من كانوا يبحثون عن الحب فى الكيمان ليلتقطه فتسقط عليهم ويموتون ومات خلق كثير لا يحصى عدده ، وذلك فى سنة 1347 ش 0( 1631 م ) ثم استمر الغلاء سنتين ، وكان والى الصعيد وقتئذ حيدر بك . وفي سنة 1350 ش ( 1634 م ) أتى النيل بفيضان عال غمر كل ألا راضى وتولى الصعيد فى ذاك الحين الأمير على بك الدفتردارى وحضر إليه فى شهر بابه سنة 1350 ش ، وزرعت البلاد واطمأن الناس ، وزال كابوس الغلاء ، وانخفضت الأسعار" } },
      { kind: 'reading', text: { en: "", ar: ". وفى تلك السنة أرسل السلطان مراد الرابع مراكب موسوقة نحاس أقراص مختومة بصورة خاتم سليمان ، وذكروا أنهم عثروا عليها فى خزانة قسطنطين الملك ، وبلغ وزنها 12 ألف قنطار . وأمر الوالى بسكها نقدية وإرسال عوضها ثلاثمائة ألف درهم ، فقام الوالى بتوزيع هذا النحاس بالقوة على أهالي مصر والصعيد بسعر كل قنطار ثمانين قرشا . ووقع بسبب ذلك ضرر عظيم على الأهالي،كما حصل ضيق عظيم فى البلد ، وخسارة كبيرة في ثروة البلاد ، مما لم يكن له مثيل حتى أضطر أغلب الناس إلى بيع ممتلكاتهم . وحصل الوالى من النحاس المذكور على أموال طائلة أرسلت الى الآستانة" } },
      { kind: 'reading', text: { en: "", ar: "ولما بلغ السلطان أن الباشا الوالى استعمل الظلم والقسوة فى توزيع النحاس المذكور غضب عليه واستدعاه من مصر . ولما حضر أمر بضرب عنقه وولى غيره على مصر ." } },
      { kind: 'reading', text: { en: "", ar: "وفى تلك السنة أرسل ملك أثيوبيا يطلب مطرانا . فرسم له البابا متاوس مطرانا من أهالي أسيوط وأرسله إليه . وقد حلت بهذا المطران أحزان وشدائد كثيرة أثناء وجوده هناك ، حتى عزلوه ورسموا بدلا منه . ." } },
      { kind: 'reading', text: { en: "", ar: "وبعد إتماما البابا زيارته الرعوية لشعب الوجه البحري ، وقبوله دعوة أهالي طوخ لزيارة بلدهم ، قام معهم من برما ميمما شطر طوخ النصارى . وعندما اقترب من الناحية استقبله جماعة الكهنة وكافة الشعب المسيحى ، وتلقوه بالإكرام والتبجيل والتراتيل الروحية التى تليق بكرامته ، وأدخلوه الى البيعة بمجد وكرامة . وأقام عندهم سنة كاملة وهز يعظ الشعب ويعلمهم" } },
      { kind: 'reading', text: { en: "", ar: "ولما كان يوم السبت المبارك ذكرى اليوم الذي أقام فيه الرب لعازر من بين الأموات اجتمع بالكهنة والشعب بعد إقامة القداس ، وأكل معهم وودعهم قائلا بالهام الروح القدس ان قبره سيكون فى بيعة هذه البلدة وانه لا يبرح طوخ وصرف الشعب وقام ليستريح فى منزل أحد الشمامسة . فلما حضر الشماس ودخل حجرة البابا وجده راقدا علي فراشه ، وهو متجه ناحية المشرق ويداه على صدره مثال الصليب المقدس ، وقد أسلم روحه بيد الرب . فاعلموا جماعة الكهنة والشعب ، فحضروا مسرعين ووجدوه قد تنيح ولم يتغير منظره بل كان وجهه يتلألأ كالشمس فأحضروا جسده المبارك الى البيعة وصلوا عليه بما يليق بالأباء البطاركة ودفنوه" } },
      { kind: 'reading', text: { en: "", ar: "بالبيعة بناحية طوخ بلده . . وقد أقام على الكرسى الرسولى مدة 14 سنة و 6 أشهر و 23 يوما لم يذق فيها لحما ، ولم يشرب خمرا . وتتيح بشيخوخة صالحة حسنة وكاملة . لتكن صلواته وبركاته معنا ولربنا المجد دائما . آمين" } },
      { kind: 'heading', text: { en: "The Commemoration of the Crucifixion of Our Lord Jesus Christ.", ar: "" } },
      { kind: 'reading', text: { en: "On this day the great St. Friska or Onesiphorus, one of the seventy apostles departed. This apostle was an Israelite of the tribe of Benjamin. His parents kept the Law of Moses and were of those who followed the Savior, listened to His teachings, and witnessed His wonders and miracles.", ar: "" } },
      { kind: 'reading', text: { en: "When Our Lord raised the son of the widow of the city of Nain, this saint was present. He went without delay to the Lord Christ at once forsaking the light of the lamp of the Jewish Law, to be enlightened by the Sun of righteousness. He believed on Him heartily, was baptized, became one of the seventy apostles, and was present with the disciples in the upper room of Zion at the time of the coming of the Holy Spirit.", ar: "" } },
      { kind: 'reading', text: { en: "He preached the Gospel in many countries. He was ordained bishop for Khoranias, where he preached it's people and enlightened them with his teachings and sermons then baptized them. And having finished his holy strife he departed in peace. He received the crown of heavenly glory and he was seventy years old, twenty nine years of it as Jewish and forty one years as Christian. St. Paul mentioned him in his Second Epistle to Timothy (2 Tim. 4:19).", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Macarius the Great.", ar: "" } },
      { kind: 'reading', text: { en: "On this day also of the year 1362 A.M. (March 31st. 1646 A.D.) on Lazarus' Saturday, Pope Mattheos III, the one hundredth Patriarch departed. He was known by the name Matthew El- Toukhy, a son of Christian parents from the city of Toukh El-Nasarah, El-Monofiah province. They feared God, caring for the strangers and charitable to the poor and the needy. God granted them a son, they called him Tadros, and they raised him well. They disciplined him with every spiritual discipline, and taught him the holy church books. The grace of God filled this blessed son, so he devoted himself to study and teach Christian education. The grace of God moved him to the angelic and ascetic life, so he went forth from his town, left his family and kinfolks and followed the commandments of the Lord Christ and went to the wilderness of Sheahat. He became a monk in the monastery of the great St. Macarius, and he fought a great fight in asceticism and worship. They ordained him a priest so he increased in asceticism and grew in virtues then they promoted him archpriest and head for the monastery.", ar: "" } },
      { kind: 'reading', text: { en: "Shortly after, Pope Yoannis XV, the ninety-ninth Patriarch departed, the fathers the bishops, the priests and the notables gathered to choose who would fit to be elevated to the Chair of St. Mark. They continued on praying asking the Lord Christ, to Him is the glory, to chose for them a good shepherd to guard His flock from the ravenous wolves. With the Will of the Lord Christ, the Shepherd of the shepherds, everyone agreed on choosing father Tadros the hegumen of St. Macarius monastery. They went to the monastery and forcibly seized him and enthroned him a Patriarch by the name Mattheos on the 4th. of El-Nasi (The intercalary days) year 1347 A.M. (September 7th. 1631 A.D.) and Anba Yoanis, the metropolitan of the Syrian monastery, headed the enthronement service.", ar: "" } },
      { kind: 'reading', text: { en: "When this Pope sat on the Apostolic Chair, he cared for Christ's flock with the best of care, and at the beginning of his days, there was peace and tranquility for the believers. The churches rested from the tribulations that they were under. Satan the enemy of the good envied him, he moved some evil doers against the Pope, so they went to the Governor in Cairo and told him that whomever sat on the Patriarchal Chair paid much money to the Governor. The Governor listened to their accusations and called the Patriarch to collect the dues. The notables went to meet the Governor who did not ask about the absence of the Patriarch but rather discussed the dues that the Patriarch pay. He forced them to bring four thousands Dinars. They left him with sadness and grief because of the heavy fine. But God, to Him is the glory, who does not wish anyone to parish had put mercy in the heart of a Jewish man who paid the required fine to the Governor. The notables promised that man to pay him back, they divided the fine among them and allocated a small portion of this heavy fine for the Pope to pay. He went to Upper Egypt to collect the sum of money required from him, and because of his faith and his strong belief in God's help, the people with compassionate heart and willingly gave him what he asked them. Shortly after, he came to Lower Egypt to visit his flock, he went to the city of Berma, and the people of the city of Toukh his home town came to him and invited him to come to visit the city so they be blessed by him, and he fulfilled their request.", ar: "" } },
      { kind: 'reading', text: { en: "During the days of this Patriarch a great famine befell all the land of Egypt, nothing like it happened before, the people suffered much and many died. King of Ethiopia sent to the Patriarch asking for a Metropolitan. Pope Mattheos ordained for them a Metropolitan from the people of the city of Assiut and sent him to them. Much tribulations and sorrows befell this Metropolitan while he was there, until they removed him and ordained another one instead of him.", ar: "" } },
      { kind: 'reading', text: { en: "After the Pope had finished his pastoral visit to the people of Lower Egypt and his acceptance to the invitation of the people of Toukh to visit their city, he left Berma with them on their way to Toukh El-Nasarah. When he drew near from the city, the priests and the Christian mass received him with reverence, veneration, and spiritual hymns to befit his honor. He entered the church with honor and glory and stayed with them one year preaching and teaching the people.", ar: "" } },
      { kind: 'reading', text: { en: "On the blessed Saturday, the commemoration of the day in which the Lord raised Lazarus from the dead, he met the priests and the people after the liturgy, ate with them, and he bade them farewell saying, with the guidance of the Holy Spirit, that his tomb will be in the church of this city and that he will not depart Toukh. He dismissed the people and went to rest in the house of one of the deacons. When the deacon returned home, he knocked on the door of the Pope's room, when he did not get any answer he entered the room and found the Patriarch laying on his bed, looking toward the east, his hand over his chest as the Holy Cross and his spirit had departed in the Hands of the Lord. The priests and the people came in haste and found him departed and his look did not change, but his face was shining as the sun. They took his blessed body to the church, and prayed over him as worthy of the fathers the Patriarchs, and buried him in the church in the city of Toukh his home town. He stayed on the Apostolic Chair for fourteen years, six month and 23 days did not eat meat or drink wine in it, and departed in a good old age.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-26",
    title: { en: "Baramhat 26", ar: "26 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of St. Euphrasia (Eupraxia), the virgin.", ar: "نياحة القديسة براكسيا العذراء" } },
      { kind: 'reading', text: { en: "On this day the blessed St. Euphrasia (Eupraxia) the virgin departed. She was the daughter of a noble family in the city of Rome, who was related to Emperor Honorius. Before her father's departure, he asked the Emperor to care for her.", ar: "فى مثل هذا اليوم تنيحت القديسة الطوباوية براكسية العذراء وهذه كانت ابنة لوالدين من عظماء مدينة رومية ومن عائلة الملك أنوريوس . وعند نياحة والدها أوصى الملك بها واتفق أن أتت والدتها الى مصر لتحصيل أجرة الأملاك والبساتين التى تركها لها زوجها فأحضرت ابنتها معها وكان عمرها وقتئذ تسع سنين ونزلتا بأحد أديرة العذارى . وكانت راهبات ذلك على غاية النسك والتقشف فلا يأكلن المأكولات الدسمة ولا زيتا ولا فاكهة ، ولا يذقن خمرا ، وينمن على الأرض فأحبت هذه الصبية الدير واستأنست بالخادمة التى فيه . فقالت لها الخادمة : &quot; عاهدينى أنك لا تتركين هذا الدير &quot; فعاهدتها على ذلك ولما أنهت والدتها عملها الذي كانت قد أتت لا جله امتنعت ابنتها عن العودة معها قائلة &quot; أنى قد نذرت نفسي للمسيح ولا حاجة بي الى هذا العالم ، لان عريسى الحقيقي هو السيد المسيح ، . فلما عرفت والدتها ذلك منها وزعت كل مالها على المساكين وأقامت معها في الدير عدة سنين ثم تنيحت بسلام. وسمع أنوريوس هذا الخبر فأرسل يطلبها . فأجابته قائلة بأنها نذرت نفسها للسيد المسيح ولا تقدر أن تخلف نذرها فتعجب الملك من تقواها على صغر سنها وتركها أما هي فسارت سيرة فاضلة وتعبدت تعبدا زائدا فكانت تصوم يومين يومين ثم ثلاثة فأربعة فأسبوعا وفي صوم الأربعين لم تكن تأكل شيئا مطبوخا . فحسدها الشيطان وضربها في رجلها ضربة آلمتها زمانا طويلا إلى أن تحنن الرب عليها وشفاها وقد أنعم الرب عليها بموهبة شفاء المرضى . وكانت محبوبة من الأخوات والآم الرئيسة لطاعتها العظيمة لهن ." } },
      { kind: 'reading', text: { en: "Her mother went to Egypt to collect the revenues and rent of her estates and orchards, which her husband had left her. She took her daughter, who was nine years of age, with her, and they lodged in one of the houses of virgins. The nuns of that convent were on high degree of asceticism, piety and devoutness, they never ate food with meat, oil, fruits, at no time drank wine and slept on the floor.", ar: "وفى إحدى الليالي رأت الرئيسة أكاليل معدة . فسألت لمن هذه ؟ فقيل لها : &quot; لابنتك بركسية &quot; وهى ستجيء الينا بعد قليل &quot; وقصت الام الرؤيا علي الأخوات وأوصتهن ألا يعلمن براكسية بها . ولما حانت أيامها لتترك هذا العالم اعترتها حمى بسيطة فاجتمع عندها الام والأخوات والخادمة وطلبن منها أن تذكرهن أمام العرش الإلهي ثم تنيحت بسلام ." } },
      { kind: 'reading', text: { en: "Eupraxia loved the life in that convent, and she was pleased with the nun that served her. That nun told her: \"Promise me that you will not leave this convent\"; and she promised her that. When her mother finished her work that she came to achieve, her daughter refused to return with her and she said to her mother: \"I have vowed myself to Christ, and I have no need for this world, for my true Bridegroom is the Lord Christ.\" When her mother knew that, she gave all her money and goods to the poor and needy, and she lived with her daughter in the convent for many years, then departed in peace.", ar: "ثم تنيحت بعدها الخادمة صديقتها وبعدها بقليل مرضت الأم فجمعت الأخوات وقالت لهن &quot; تدبرن في من تقمنها عليكن لاني ذاهبة إلى الرب &quot; وفي صباح اليوم التالي افتقدنها فوجدن أنها قد تنيحت . صلا’ الجميع تكون معنا . آمين .." } },
      { kind: 'reading', text: { en: "When Emperor Honorius heard that, he sent asking for her. She answered back saying that she had vowed her self to the Lord Christ, and she can not break her covenant. The Emperor marvelled at her wisdom and righteousness and allowed her to stay.", ar: "" } },
      { kind: 'reading', text: { en: "Eupraxia contended strenuously in the ascetic life, she fasted two days at a time, then three, then four, and afterwards she fasted for a week at a time, and during the Holy Lent she did not eat anything which was cooked. Satan was jealous of her, and he smote her with an illness in her feet, gave her pain for a long time, until God had compassion on her and healed her. God granted her the gift of healing the sick, and she was beloved by all the sisters and the abbess for her humility and obedience to them.", ar: "" } },
      { kind: 'reading', text: { en: "One night the abbess saw in a vision crowns which had been prepared, and she asked: \"Who are these for?\", and she was told: \"These crowns for your daughter Eupraxia, she will be coming to us after a short while.\" The abbess told the nuns of the vision which she had seen, and commanded them not to tell Eupraxia about it. When her time came to depart of this world, she fell sick of a slight fever. The abbess and the nuns gathered around St. Eupraxia and asked her to remember them before the Divine Throne, then she departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "Then right after her departure the nun her friend departed, and shortly after, the abbess fell sick, so she gathered the nuns and told them: \"Choose whom will be abbess over you, for I am going to the Lord.\" When they came on the following morning to visit her, they found that she had departed.", ar: "" } },
      { kind: 'reading', text: { en: "May their prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of Pope Peter VI, the One Hundred and Fourth Pope of Alexandria.", ar: "نياحة البابا بطرس السادس ال104" } },
      { kind: 'reading', text: { en: "On this day also the church commemorates the departure of Pope Peter VI (Petros), the one hundred and fourth Patriarch in the year 1442 A.M. (April 2nd., 1726 A.D.). This blessed father and spiritual angel was the son of pure and Christian parents from the city of Assiut. They raised him well, educated him with ecclesiastic subjects and manners and he excelled in them. His name was Mourgan, but later on he became known by the name Peter El-Assuity. The grace of God was on him since his young age, and when he came to the age of maturity, he forsook the world and what in it, and longed to the monastic life. He went to the monastery of the great St. Antonios in the mount of El-Arabah, he dwelt there, became a monk and put on the monastic garb. He exerted himself in worship, and when he achieved the ascetic life, purity, righteousness, and humility, the fathers the monks chose him to be a priest. They took him against his will to Cairo, and he was ordained a priest, for the monastery of the great Saint Anba Paula the first hermit, among others, by the hand of Pope Yoannis El-Toukhy (103), in the church of the Lady the Virgin in Haret El-Roum. He increased in virtues and he became well known among the people.", ar: "فى مثل هذا اليوم تعيد الكنيسة تذكار نياحة البابا بطرس السادس البطريرك 104 في سنة 1442 ش ( 2 أبريل سنة 1726 م ) وكان هذا الأب الطوباوى والملاك الروحانى ابنا لأبوين مسيحيين طاهرين من المدينة المحبة لله أسيوط . فربياه أحسن تربية وثقفاه بالعلوم والآداب الكنسية حتى برع فيها . وكان اسمه مرجان ولكنه اشتهر باسم بطرس الاسيوطى فيما بعد" } },
      { kind: 'reading', text: { en: "When Pope Yoannis, the above mentioned, departed, the Chair became vacant after him for two month and six days. They went on looking for whom was fit for this honorable rank so they chose some priests and monks. They wrote their names on pieces of papers, placed them over the alter and celebrated the Divine Liturgy. On the third day after asking and supplicating God to raise the one He chooses, the lot fell on this father, so they realized that he was the chosen one by God. He was ordained Patriarch for the See of St. Mark on sunday the 17th. of Mesra 1434 A.M. (August 21st., year 1718 A.D.) at the church of\nin Old Cairo. It was a great joy for his enthronement, which was attended by the Christian mass, foreign dignitaries, Catholics, Greeks, Armenians, and the military.", ar: "وكانت نعمة الله حالة عليه من صغره فلما بلغ أشده زهد العالم وكل ما فيه واشتاق إلى سيرة الرهبنة . فمضى إلى دير القديس العظيم أنطونيوس بالعربة فمكث فيه وترهب ولبس الزي الرهباني وأجهد نفسه في العبادة ولما نجح في الفضيلة والحياة النسكية والطهارة والتواضع اختاره الآباء الرهبان قسا . فأخذوه رغم أرادته وقاموا به إلى مصر ورسم قسا علي دير القديس العظيم أنبا بولا أول السواح . هو وكهنة آخرون من يد البابا يؤنس الطوخي البطريرك ( 103 ) في بيعة السيدة العذراء بحارة الروم فزاد في الفضيلة وشاع ذكره بين الناس" } },
      { kind: 'reading', text: { en: "Afterwards, Pope Peter went to visit the cities of Lower Egypt, visited the churches, and at the end he arrived to Alexandria to visit the church of\nSt. Mark the evangelist in the\n11th. of Baramouda year 1438 A.M. He kissed the pure holy head of St. Mark, and he did extensive renovation inside the church. When he was about to return he was informed that a group in Alexandria planning to steal the holy head so he hid it in the monastery since that time. Then he gave a lamb made of silver as a gift and lit it over the tomb of the Evangelist, and he encircled it by a partition with windows looking inside. He went to Lower and Upper Egypt and the people of Egypt rejoiced.", ar: "ولما تنيح البابا يؤنس المذكور وخلا الكرسى بعده مدة شهرين وستة أيام لبثوا يبحثون عمن يصلح لهذه الرتبة الجليلة فاختاروا بعض الكهنة والرهبان وكتبوا أسماءهم في وريقات وضعوها علي المذبح وأقاموا القداس . وفي ثالث يوم وقعت القرعة على هذا الأب بعد الطلبة والتضرع إلى الله أن يقيم لهم المختار من عنده . فتحققوا بذلك أنه مختار من الله . ورسم بطريركا علي الكرسى المرقسى في يوم الأحد 17 مسرى سنة 1434 ش ( 21 أغسطس سنة 1718 م ) في بيعة القديس مرقوريوس أبى سيفين بمصر القديمة وكان فرح عظيم بإقامته . وحضر رسامته الشعب المسيحي وبعض من الإفرنج والروم والأرمن وطائفة من العسكر." } },
      { kind: 'reading', text: { en: "During the days of this father, a group of priests and deacons came, delegated by the Emperor of Ethiopia, with extravagant gifts and a letter from the Emperor, asking for a Metropolitan. He deliberated the subject with Mr. Lotf-Allah Abu-Yousif a prominent notable of Cairo and others, and they all agreed on the honorable father Khristozolo bishop of Jerusalem. He was a blessed father, and knowledgeable teacher, so Pope Peter ordained him Metropolitan, and called him Khristozolo III. They went with him to Ethiopia happy and joyful, and he cared for that parish from 1720 - 1742 A.D. Pope Peter ordained Anba Athanasius bishop for Jerusalem.", ar: "ثم بعد ذلك مضى إلى بلاد الوجه البحري وافتقد الكنائس ووصل الإسكندرية لزيارة بيعة مار مرقس الانجيلى لها في 11 برمودة سنة 1438 ش واهتم هناك بإصلاحات معمارية داخل الكنيسة وقبل الرأس المقدسة الطاهرة . ولما أراد الرجوع علم أن جماعة بالإسكندرية تكلموا علي الرأس المقدسة فأخفاها في الدير من ذلك الوقت . ثم قدم قنديلا من الفضة هدية وأسرجه علي قبر البشير . كما أحاطه بحجاب له طاقات تطل علي الداخل ومضى آلي الوجهين البحري والقبلي وفرح به أهل كوره مصر" } },
      { kind: 'reading', text: { en: "During the papacy of this Pope many churches were built and consecrated with his blessed hand. Among those churches, the church of St. Mary on the Nile in the district of El-Maady, the church of Michael the archangel in Babylon, and the church of St. Mina the wonder worker in Fum El-Khalig - Cairo. The last two churches were built by the noble and charitable Mr. Lotf-Allah Abu-Yousif by his private funds, also he built the church of the Apostles in the monastery of St. Antonios, and also assumed and paid the cost of the enthronement festivals of the Patriarch.", ar: "وفى أيام هذا البابا حضر جماعة من الكهنة والشمامسة من قبل سلطان أثيوبيا ومعهم هدايا فاخرة مع مرسوم من الملك يطلب مطرانا فتشاور في الآمر مع المعلم لطف الله أبو يوسف كبير الأراخنة في القاهرة وباقي أراخنة الشعب علي أبينا المكرم خرستوذلو أسقف القدس الشريف فامسكوه ورسموه مطرانا لانه كان خبيرا كاملا ومعلما عالما وحبرا فاضلا فمضوا به فرحين مسرورين . ودعى خرستوذلو الثالث وتولى هذه الابرشية من سنة 1720 م إلى 1742 م ورسم الأنبا اثناسيوس اسقفا علي أورشليم وقد شيدت في مدة رئاسة هذا البابا كنائس كثيرة وكرست بيده المباركة ومن بينها كنيسة دير العدوية علي البحر جهة المعادى التى جددها المعلم مرقورة الشهير بديك أبيض وكنيسة الملاك ميخائيل القبلي بجهة بابلون وكنيسة مارمينا العجايبى بفم الخليج بمصر عمرهما الثرى الشهير والارخن الكبير المعلم لطف الله يوسف من جيبه الخاص . وبسبب هذا التجديد غرمه الوزير أربعين كيسا من المال دفعها له من ماله كما قام هذا المحسن الكريم أثناء نظارته علي دير القديس أنطونيوس ببناء كنيسة آبائنا الرسل وكرسها مع كنيسة أنبا مرقس بالدير المذكور لأنه كان مملوءا غيرة واهتماما بشئون أمته وكنيسته القبطية وقام أيضا بتحمل مصاريف حفلة إقامة تنصيب البطريرك علي نفقته الخاصة" } },
      { kind: 'reading', text: { en: "The days of this Pope were peaceful and tranquil, and he worked on implementing the church cannons especially he stopped the divorce, for whatever the reason. For that purpose he went to the Governor Ebn-Eiwaz and discussed the subject with the Muslim scholars, so they gave him a formal legal opinion and a decree that the No Divorce only apply to the Christians, and no one can object him for that in courts. He ordered the priests not to wed except in his presence. That was because a man, who was the son of a priest, protested against him. The man had divorced his wife and married another without the Patriarch's knowledge in the church. He ordered them to come before him so he might dissolve the illegal marriage, but the man refused and did not come. The Pope excommunicated the man, his wife and his father the priest for he had married them. This man died after sever illness in his mouth, and his father the priest went to the Pope, asked for his forgiveness, the Pope absolved him and shortly after he died.", ar: "وانقضت أياما هذا البابا في هدوء واطمئنان وكان يعمل علي تنفيذ القوانين الكنسية فأبطل الطلاق لآي سبب ومضى لهذا الغرض إلى الوالى ابن ايواز وباحث علماء الإسلام فكتبوا له فتاوى وفرمانا من الوزير بأن عدم الطلاق لا يسرى إلا علي الدين المسيحي دون غيره وانه ليس لأحد أن يعارضه في أحكامه فأمر الكهنة أن لا يعقدوا زواجا إلا علي يده في قلايته بعدما اعترضه رجل ابن قسيس كان طلق امرأته وتزوج غيرها بدون علمه فأمر بإحضاره فيفصل بينهما فأبى ولم يحضر فحرمه هو وزوجته وأبيه القمص فمات هذا الرجل بعد أن تهرأ فمه وذاب لسانه وسقطت أسنانه . أما أباه فاستغفر وأخذ الحل من البابا ومات" } },
      { kind: 'reading', text: { en: "This pope shepherded the flock of Christ with the best of care, and when he completed his strife, he fell sick for a short sickness and departed on the 26th. of Baramhat, year 1442 A.M. in the Holy Lent. His body was placed in the tomb of the Patriarchs in the church of St. Marcurius in Old Cairo. He remained on the Chair for 7 years, 7 month and 11 days. He was charitable, generous and merciful to his people as his predecessor. Pope Peter (Petros) El-Assuity was approximately forty six years old, and he was a contemporary of Sultan Ahmed III the Ottoman. The Chair remained vacant for 9 month and 11 days after him.", ar: "رعى هذا البابا رعية المسيح رعاية صالحة . ولما أكمل سعيه مرض قليلا وتنيح فى يوم 26 برمهات سنة 1442 ش في الصوم الكبير ووضع جسده في مقبرة الآباء البطاركة ببيعة مرقوريوس أبى سيفين بمصر القديمة . وأقام علي الكرسى مدة 7 سنين و7 أشهر و 11 يوما . وكان عمره ستة وأربعين سنة تقريبا وعاصر السلطان احمد الثالث العثماني وخلا الكرسى بعده تسعة أشهر واحد عشر يوما." } },
      { kind: 'reading', text: { en: "The year this pope departed, there was an outbreak of Plaque in the land along with severe drought, many bishops and priests departed and death befell the people from Alexandria to Aswan.", ar: "وفئ سنة نياحة هذا البابا وقع وباء الطاعون فى البلاد مع قحط شديد وتنيح قسوس كثيرون وأساقفة ووقع الموت علي الناس من الإسكندرية إلى أسوان واضطر الناس إلى ترك الزرع حتى صاروا يدفنون في الحصر من قلة الأكفان . وفي تلك السنة تلفت زراعة القمح في وادي النيل ولم يسد حاجة البلاد ووقع القحط والغلاء . لطف الله بعباده ونفعنا ببركات وصلوات المثلث الرحمة البابا البطريرك بطرس الاسيوطى . ولربنا المجد دائما . آمين" } },
      { kind: 'reading', text: { en: "May the lord have mercy on his people and benefit us with the prayers and blessings of Pope Petros El-Asuity, and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-27",
    title: { en: "Baramhat 27", ar: "27 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Crucifixion of Our Lord Jesus Christ.", ar: "تذكار صلب مخلصنا الصالح" } },
      { kind: 'reading', text: { en: "On this day is the commemoration of the Crucifixion of Our Lord Jesus Christ Incarnate, to Him is the Glory, for the salvation of the world. The Holy Bible mentioned that: \"From the sixth hour until the ninth hour there was darkness over all the land.\" (\n27:45) The sun had hidden its light when it saw its creator incarnated, hanging with His own free will on the wood of the Cross, inclined His head, and yielded up His spirit.", ar: "في هذا اليوم تذكار صلب ربنا يسوع المسيح له المجد بالجسد من أجل خلاص العالم . وقد ذكر الكتاب المقدس انه حدثه ظلمة عظيمة عن وجه الأرض كلها من الساعة السادسة إلى الساعة التاسعة إذ أخفت الشمس شعاعها عندما رأت خالقها محتجبا بالجسد المرئي ومعلقا بإرادته على خشبه الصليب . وقد أمال الرأس وأسلم الروح وتعلمنا الكنيسة المقدسة أن لاهوته لم يفارق ناسوته لحظة واحدة ولا طرفة عين وأنه نزل إلى الجحيم من قبل الصليب ليخلص المعتقلين فيه . وعلي هذا قال بطرس الرسول : &quot; مماتا في الجسد ولكن محيى في الروح . الذي فيه أيضا ذهب فكرز للأرواح التى في السجن &quot; ( 1 ) 1 بط 3 : 18 و 19 ففي السموات كان متعاليا ، وفي الأرض مخلصا سبحانه جلت قدرته . لا يخلو منه مكان . الذي فدانا بذاته وفتح لنا باب ملكوته له المجد والقدرة والسلطان إلى الأبد . آمين" } },
      { kind: 'reading', text: { en: "The Holy Church teaches us that: \" His Divinity parted not from His Humanity for a single moment, nor a twinkle of an eye, and He descended to the hades from the cross to save those in bondage therein.\" St. Peter also said: \"For Christ also suffered once for sins, the just for the unjust, that He might bring us to God, being put to death in the flesh but made alive by the Spirit, by whom also He went and preached to the spirits in prison.\" (1 Peter 3:18-19) In the heavens He was in His might, and on earth He was a savior. Praise the Lord, the omnipotent God, Who is in every place, He saved us by giving Himself up, and opened to us the door of His kingdom.", ar: "" } },
      { kind: 'reading', text: { en: "To Him is the Glory, Power and Dominion forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Departure of St. Macarius the Great.", ar: "نياحة القديس مكاريوس الكبير اب الرهبان" } },
      { kind: 'reading', text: { en: "On this day also, of the year 392 A.D. the blessed father, the lamp of the wilderness and the father of all the monks the great saint Anba Macarius, departed. This Saint was born in the village of Shabsheer - Menuf, from good and righteous parents. His father's name was Abraham and his mother's name was Sarah and they had no son. In a vision at night he saw the angel of the Lord and told him that God was about to give him a son, and his name will be known all over the earth, and he will have a multitude of spiritual sons.", ar: "في مثل هذا اليوم من سنة 8 . ش ( سنة 392 م ) تنيح الأب المغبوط سراج البرية أب جميع الرهبان القديس العظيم الأنبا مقاريوس . ولد هذا القديس فى شبشير من أعمال منوف من أبوين صالحين بارين واسم أبيه القس إبراهيم ولم يكن له ولد فحدث في إحدى الليالي أن أبصر فى رؤيا شخصا من قبل الرب يقول له : ان الله سيرزقه ولدا يكون ذكره شائعا في أقطار الأرض ويرزق بنينا روحانيين وبعد زمن رزق هذا القديس ولدا فسماه مقارة آي الطوباوى وكان مطيعا لوالديه وحلت عليه نعمة الله منذ صغره . ولما كبر زوجه والداه بغير أرادته فتظاهر بالمرض أياما ثم استسمج أباه أن يمضى إلى البرية لتبديل الهواء فسمح له ، فمضى وصلى إلى الرب يسوع أن يساعده علي عمل ما يرضيه فلما صار في البرية أبصر رؤيا كأن كاروبا ذي أجنحة ثم أمسك بيده وأصعده على رأس الجبل وأراه كل البرية شرقا وغربا وشمالا وجنوبا وقال له أن الله قد أعطاك هذا الجبل ميراثا لك ولبنيك من بعدك ولما عاد من البرية وجد زوجته قد ماتت وهي بعد عذراء فشكر السيد المسيح كثيرا وبعد ذلك مات أبواه فوزع كل ما خلفاه له علي المساكين ورأى أهل شبشير طهره وعفافه فأخذوه إلى أسقف أشمون فرسمه قسا عليهم وبنوا له موضعا خارج البلد وكانوا يأتون إليه ويتقربون منه وعينوا له خادما ليبيع له شغل يديه وقضاء ما يحتاج إليه" } },
      { kind: 'reading', text: { en: "Shortly after, this holy man had a son and called him Macarius which means \"Blessed.\" He was obedient to his parents, and the grace of God was upon him since his young age. When he grew up his father forced him to get married against his will, so he pretended that he was sick for several days. Then he asked his father if he might go to the wilderness to relax and that may make him recover from his illness speedily. He went to the wilderness and prayed to the Lord Christ to direct him to do what is pleasing to Him. While he was in the wilderness he saw a vision, and it seemed that one of the Cherubim, with wings, took his hands, and ascended up to the top of the mountain, and showed him all the desert, east and west, and north and south. The Cherub told him: \"God has given this desert to you and your sons for an inheritance.\" When he returned from the wilderness he found that his wife, who was still virgin, had died, and Macarius thanked the Lord Christ. Shortly after, his parents departed, and he gave all what they had left to the poor and the needy. When the people of Shabsheer saw his chastity and purity, they took him to the bishop of Ashmoun who ordained him a priest for them. They built a place for him outside the city, and they went to him to confess and to partake from the Holy Mysteries. They appointed a servant to take care of his needs and to sell for him the work of his hands.", ar: "ولما رأى الشيطان سموه في الفضيلة جلب عليه تجربة شديدة وذلك أنه أوعز إلى فتاة كانت قد ارتكبت شرا مع شاب بأن تدعى أن القديس مقاريوس هو الذي أتى معها هذا الشر . فلما علم أهلها بذلك أهانوه وضربوه ضربا موجعا فتحمله وهو صامت . ولما داهم الطلق هذه الامرأة لتلد لبثت أربعة أيام معذبة ولم تلد حتى اعترفت بكذبها علي القديس وذكرت اسم الشاب الذي أغواها ." } },
      { kind: 'reading', text: { en: "When Satan saw St. Macarius growth in virtues, he brought on him a severe temptation. He inspired a girl that had defiled herself with a man to claim that St. Macarius is the one who had defiled her. When her family heard that, they went to him, insulted and beat him severely, inflicting much pain on him, which he endured silently. Macarius reproached himself saying \"O Macarius now you have a wife and a child, and it is meet for you to work day and night for your own food and for that of your child and your wife.\" He worked continually at weaving mats and baskets, and he gave them to the man who ministered unto him; and he sold them and gave the money to the woman. When the day of her delivery drew near her labor was exceedingly difficult, she continued to suffer for four days and did not deliver until she confessed her false accusation against the Saint and named the man that defiled her.", ar: "فلما رأى ذلك أهل الفتاة رجعوا إليه يستغفرونه عما حصل منهم له . فهرب منهم للابتعاد عن مجد العالم وكان له من العمر وقتئذ 30 عاما وأذ فكر في نفسه ألا يعود إلى قريته ظهر له ملاك الرب وسار معه يومين حتى وصلا إلى وادي النطرون ثم قال له القديس &quot; حدد لي يا سيدي مكانا أسكن فيه &quot; فأجابه : &quot; لا لئلا تخرج عنه فيما بعد فتكون مخالفا لقول الرب . بل البرية كلها لك فأي موضع أردت أسكن فيه &quot; . فسكن في البرية الداخلية حيث الموضع الذي فيه دير القديسين مكسيموس ودوماديوس وهو المعروف الآن بدير البرموس" } },
      { kind: 'reading', text: { en: "When the family of the girl heard that, they decided to go to ask for his forgiveness for what happened from them. When St. Macarius heard that, he fled away from them running from the vain glory of this world.", ar: "ولما ذهب لزيارة القديس أنطونيوس قال عنه حينما رآه &quot; هذا إسرائيلي حقا لا غش فيه &quot; ثم ألبسه الاسكيم المقدس وعاد مكانه ولما تكاثر عنده الاخوة بنى لهم كنيسة حسنة . وذاع صيته وسمع الملوك بكثرة العجائب التى كان يعملها وظهر له ملاك الرب وأتى به إلى رأس الجبل عند البحيرة الغربية المالحة الماء وأعلمه أن يتخذ له هذا المكان مسكنا وبنى له قلاية وكنيسة لأن شعبا كثيرا سيجيء إليه (1) وهو المعروف الآن بدير القديس مقاريوس" } },
      { kind: 'reading', text: { en: "At that time he was 30 years old, and the angel of the Lord appeared to him and walked with him for two days until they came to Wadi El-Natroun and the Saint asked the angel: \"Appoint for me O master a place to live in.\" The angel replied: \"I have not marked out a place for you to live, lest you leave it in the future and transgress the commandment of God. Behold all the wilderness is yours, so wheresoever you wish, live there.\" St. Macarius dwelt in the Inner Desert, in the place of the monastery of Sts. Maximus and Domadius which is known now by the monastery of El-Baramous. He went to visit St. Antonios, who said about St. Macarius when he saw him: \"This is an Israelite in whom there is no guile.\" St. Antonios put on him the Holy Eskeem, then St. Macarius returned to his place. When the number of monks increased around him he built a church for them. His fame was known all over the country and many kings and Emperors heard about the miracles that God performed on his hands. He healed the daughter of the king of Antioch that was possessed by an unclean spirit. The angel of the Lord appeared to him and took him to a place and told him to make this place his abode, for many people will come to him in that place. He built a cell for himself and a church.", ar: "وظن يوما أن العالم خلا من الناس الأتقياء فجاءه صوت من السماء قائلا : اعلم أن هناك امرأتين في مدينة الإسكندرية تخافان الرب &quot; فتناول عصاه وزاده وقصد إلى الإسكندرية وسأل حتى وصل إلى منزلهما فلما دخل رحبتا به وغسلتا قدميه بماء دافئ ولما سألهما عن سيرتهما قالت له إحداهما : لم تكن بيننا قرابة جسدية . ولما تزوجنا هذين الأخوين طلبنا منهما أن يتركانا نترهب . فلم يسمحا لنا . فعاهدنا أنفسنا أن تقضى حياتنا بالصوم إلى المساء والصلاة الكثيرة وقد رزقت كل منا بولد متى بكى أحدهما تحتضنه الأخرى وترضعه حتى وان لم يكن ولدها ونحن في عيشة واحدة . وحدة الرأي رائدنا والاتحاد غايتنا وعمل زوجينا رعاية الغنم . ونحن فقراء نكتفي بقوت يومنا وما يتبقى نوزعه علي الفقراء والمساكين &quot; فحينما سمع القديس هذا الكلام هتف قائلا &quot; حقا ان الله ينظر إلى استعداد القلوب ويمنح نعمة روحه القدوس لجميع الذين يريدون أن يعبدوه &quot; . فودعهما وانصرف راجعا إلى البرية" } },
      { kind: 'reading', text: { en: "He thought one day that the world had no more righteous people, so a voice came to him from heaven saying: \"In the city of Alexandria there are two women who feared God.\" He took his staff, his provisions, and went to Alexandria and he asked around until he reached their house. When he entered, they welcomed him, washed his feet with warm water, and when he asked them about their life, one of them told him: \"There is no kinship between us and when we married these two brothers we asked them to leave us to be nuns but they refused. So we committed ourself to spent our life fasting till evening with often prayers. When each of us had a son, whenever one of them cry, any one of us would carry and nurse him even if he was not her own son. We are in one living arrangement, the unity in opinion is our model, and our husbands work is shepherding sheep, we are poor and only have our daily bread and what is left over we give it to the poor and the needy.\" When the Saint heard these words he cried saying: \"Indeed God looks to the readiness of the heart and grant the grace of His Holy Spirit for all those who wish to worship him.\" He bade them farewell and left returning to the wilderness.", ar: "وكان في أوسيم راهب أضل قوما بقوله انه لا قيامة للأموات فحضر أسقف أوسيم إلى القديس مقاريوس وشكا إليه أمر هذا الراهب فذهب إليه ولم يزل به حتى أرجعه عن ضلاله وفي يوم نياحته رأى القديسين أنطونيوس وباخوميوس وجماعة من القديسين والملائكة وأسلم الروح بالغا من العمر سبعا وتسعين سنة" } },
      { kind: 'reading', text: { en: "There was an erring monk who strayed many by his saying that there was no resurrection of the dead. The bishop of the city of Osseem went to St. Macarius and told him about that monk. Abba Macarius went to that monk and stayed with him until the monk believed and returned from his error.", ar: "وكان قد أوصى تلاميذه أن يخفوا جسده ولكن قوما من شبشير آتوا وسرقوا جسده وبنوا له كنيسة ووضعوه بها حوالي مائة وستين سنة إلى أيام مملكة العرب وبناء القلالى حيث أرجعوه إلى ديره" } },
      { kind: 'reading', text: { en: "On the day of his departure, he saw Sts. Antonios and Pachomius, and a company of the saints, and he delivered up his soul. He was ninety-seven years old.", ar: "وقد ورد في مخطوط بشبين الكوم أن القديس ببنوده تلميذه رأى نفس الصديق عند صعوده إلى السماء ، والشياطين يصيحون خلفه قائلين : &quot; قد غلبتنا يا مقاريوس &quot; فأجابهم : &quot; لم أغلبكم بعد &quot; فلما وصل باب السماء صاحوا ثانية : &quot; قد غلبتنا &quot; . فرد عليهم كالأول . ولما دخل باب السماء صاحوا : &quot; قد غلبتنا يا مقاريوس &quot; فقال لهم : تبارك الرب يسوع المسيح الذي خلصني من أيديكم &quot;.صلاته تكون معنا . آمين" } },
      { kind: 'reading', text: { en: "St. Macarius had commanded his disciples to hid his body, but some of the natives of the city of Shabsheer came and stole his body,\nfor around one hundred and sixty years until the Arab conquest and the rebuilding of his monastery,\nthey returned the body to it.", ar: "" } },
      { kind: 'reading', text: { en: "In a manuscript in Shebeen El-Koum, was mentioned that St. Babnuda, his disciple, saw the soul of St. Macarius ascending to heaven, and he heard the devils crying out and calling after him, \"You have conquered us O Macarius.\" The Saint replied \"I have not conquered you yet.\" When they came to the gates of heaven they cried again saying \"You have conquered us\", and he replied as the first time. When he entered the gate of heaven they cried \"You have overcome us O Macarius.\" He replied \"Blessed be the Lord Jesus Christ who has delivered me from your hands.\"", ar: "" } },
      { kind: 'reading', text: { en: "May his blessing be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Martyrdom of St. Domicos.", ar: "استشهاد القديس دوميكيوس" } },
      { kind: 'reading', text: { en: "On this day also St. Domicos was martyred during the reign of the infidel Emperor Julian. Sapor (Shapur) Arsakis II king of Persia was in peace with the Roman Empire, and he paid tribute to the lover of God\n. A dispute took place between\nEmperor Julian and Sapor king of Persia, and the later prepared an army to fight the Romans. Julian offered the sacrifices to his idols in the city of Casius which was about six miles from Antioch where was the idol Apollon. The enemy of God went along with the magicians, sorcerers, and the army to meet the Persians. On his way he passed by an isolated place, where he saw a multitude of men, women, and children.", ar: "في مثل هذا اليوم استشهد القديس دوميكيوس . ومن أمره أنه في أيام الإمبراطور يوليانوس الكافر انقض عليه شابور ارساكيس الثاني ملك الفرس الذي كان مسالما للدولة الرومانية وكان يدفع الجزية للإمبراطور قسطنطين حبيب الله وأعد جيشا لمحاربة الرومان . وفى ذاك الحين نال القديس دوميكيوس إكليل الشهادة لأنه بعد أن قدم يوليانوس الذبائح لأوثانه في مدينة كاسيوس التي تبعد عن إنطاكية ستة أميال حيث يوجد الصنم أبوللون توجه عدو الله مصحوبا بالعرافين والسحرة وزحف الجيش الروماني لمقابلة الفرس وعند مروره علي مكان منعزل شاهد جمهورا كثيرا من الرجال والنساء والأطفال لأن المرضى كانوا ينالون الشفاء بصلوات دوميكيوس خادم الله" } },
      { kind: 'reading', text: { en: "When he asked about this multitudes they told him: \"A monk who live in a cave in this place, perform miracles and heal the sick, and the multitudes that you see are the Christians that came to get his blessing and be cured from their illnesses.\" Julian became raged and sent a soldier to St. Domicos who talked to him in a threatening way saying: \"If you are living in this cave to please God so why you are seeking the gratitude of men? and why don't you hide your self from them?\" The Saint replied saying: \"I have given my soul and body to the hands of God, the God of heaven and earth the Lord Jesus Christ, and spent many years in seclusion in this cave, as for those who come to me with a strong faith, I can not dismiss them.\" When the Emperor heard his answer, he ordered his soldiers to seal the mouth of the cave with a wall and the Saint was inside where he delivered his soul therein.", ar: "" } },
      { kind: 'reading', text: { en: "Thus this Saint ended his pure life and received the crown of martyrdom on the 27th. of Baramhat, year 78 A.M. (March 23rd., year 362 A.D.).", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us and Glory be to God forever. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-28",
    title: { en: "Baramhat 28", ar: "28 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Departure of the righteous Emperor Constantine the Great.", ar: "نياحة الملك البار قسطنطين الكبير" } },
      { kind: 'reading', text: { en: "On this day of the year 53 A.M. (337 A.D.) the righteous Emperor Constantine the great departed. His father's name was Constantius I Chlorus which means (Green), and his mother's name was Helena. Constantius reigned over Byzantium, Maximianus reigned over Rome, and Diocletian reigned over Antioch and Egypt. Constantius was pagan, but he was honorable, loved to do good, compassionate and merciful. He went to the city of El-Ruha (Urfa - Gr. Edessa) and there he saw Helena, liked her and he married her. She was a Christian, and she conceived Constantine. Constantius left her in El-Ruha and returned to Byzantium. She brought forth Constantine and raised him up very piously, taught him every kind of learning, sowed in his heart mercy and compassion for the Christians, but she did not dare to have him baptized.", ar: "في مثل هذا اليوم من سنة 53 ش ( 337 م ) تنيح الإمبراطور البار القديس قسطنطين الكبير . وكان اسم أبيه قونسطا (1) قسطنديوس خلورس ( الأخضر) وأمه هيلانه وكان أبوه ملكا علي بيزنطية ومكسيميانوس علي رومه ودقلديانوس علي إنطاكية ومصر وكان والد قونسطا وثنيا إلا أنه كان صالحا محبا للخير رحوما شفوقا . واتفق أنه مضي إلى الرها وهناك رأي هيلانة وأعجبته فتزوجها وكانت مسيحية فحملت منه بقسطنطين هذا . ثم تركها في الرها وعاد إلى بيزنطية فولدت قسطنطين وربته تربية حسنة وأدبته بكل أدب وكانت تبث في قلبه الرحمة والشفقة علي المسيحيين ولم تجسر أن تعمده ولا تعلمه أنها مسيحية فكبر وأصبح فارسا وذهب إلى أبيه ففرح به لما رأي فيه من الحكمة والمعرفة والفروسية وبعد وفاة أبيه تسلم المملكة ونشر العدل والأنصاف . ومنع المظالم فخضع الكل له وأحبوه وعم عدله سائر البلاد . فأرسل إليه أكابر رومه طالبين أن ينقذهم من ظلم مكسيميانوس . فزحف بجنده إلى إنقاذهم وفي أثناء الحرب رأي في السماء في نصف النهار صليبا مكونا من كواكب مكتوبا عليه باليونانية الكلمات التي تفسيرها &quot; بهذا تغلب &quot; . وكان ضياؤه يشع أكثر من نور الشمس فأراه لوزرائه وكبراء مملكته فقرأوا ما هو مكتوب . ولم يدركوا السبب الموجب لظهوره . وفي تلك الليلة ظهر له ملاك الرب في رؤيا وقال له : اعمل مثال العلامة التي رأيتها وبها تغلب أعداءك ففي الصباح جهز علما كبيرا ورسم عليه علامة الصليب كما رسمها أيضا علي جميع الأسلحة واشتبك مع مكسيميانوس في حرب دارت رحاها علي الأخير الذي ارتد هاربا وعند عبوره جسر نهر التيبر سقط به فهلك هو وأغلب جنوده . ودخل قسطنطين روما فاستقبله أهلها بالفرح والتهليل وكان شعراؤها يمدحون الصليب وينعتونه بمخلص مدينتهم . ثم عيدوا للصليب سبعة أيام واصبح قسطنطين ملكا علي الشرق والغرب ." } },
      { kind: 'reading', text: { en: "Constantine grew up, and he was a bold and skilful horseman. He went to his father who rejoiced in him when he saw that he was full of wisdom, knowledge, and he was a skilful horseman. After his father's death he received the kingdom and he reigned with justice and integrity, and stopped all unfair practices. All the people were subject to him and they loved him and his righteous judgement spread throughout the Empire. The nobles of Rome sent asking him to come and save them from the injustice of Maximianus. Constantine marched with his army toward Rome to save them. During the war he saw in the heaven, in the middle of the day, a Cross made of stars, and on it was written in Greek words which being interpreted as \"With this you shall conquer.\" The light of the Cross was more shinning than the sun, and he shewed it to his ministers and the nobles of his kingdom. They read what was written, marvelled and they did not know for what reason that cross had appeared. That night the angel of the Lord appeared to him in a vision and told him: \"Make a sign for yourself like that sign which you had seen, and with it you shall conquer your enemies.\" The next morning, he prepared a large flag with the sign of the cross on it, and made the sign of the cross on all the armaments. He engaged with Maximianus in a battle and fought. Constantine overcame Maximianus who withdrew with his army, and while crossing the bridge over the Tiber river, the bridge broke and he and most of his men perished. Constantine entered Rome and its people welcomed him with joy and gladness, and its learned men praised the Honorable Cross and called it the Savior of their city. Then they celebrated for the Cross seven days and Constantine became the Emperor of the East and the West.", ar: "ولما استقر به المقام بروما تعمد وأغلب عسكره من سلبسطرس البابا في السنة الحادية عشرة من ملكه والرابعة من ظهور الصليب المجيد . ثم أصدر أمرا إلى سائر أنحاء المملكة بإطلاق المعتقلين وأمر ألا يشتغل أحد في أسبوع الآلام كأوامر الرسل وأرسل هيلانة إلى بيت المقدس فاكتشفت الصليب المقدس . وفي السنة السابعة عشرة من ملكه اجتمع المجمع المقدس الثلاثمائة وثمانية عشر بنيقيا في سنة 325 م . ورتب أمور المسيحيين علي أحسن نظام وأجوده ثم جدد بناء بيزنطية ودعاه باسمه القسطنطينية وجلب إليها أجساد كثيرون من الرسل والقديسين وتنيح بنيقوميدية . فوضعوه في تابوت من ذهب وحملوه إلى القسطنطينية . فاستقبله البطريرك والكهنة بالصلوات والقراءات والتراتيل الروحية ووضعوه في هيكل الرسل القديسين . وكانت مدة حياته خمسا وسبعين سنة ولربنا المجد والقوة والعظمة وعلينا رحمته ونعمته إلى الأبد . آمين" } },
      { kind: 'reading', text: { en: "When Constantine established himself in Rome, he and most of his soldiers were baptized by the Pope of Rome, in the eleventh year of his\nreign, which is the fourth year after\n. He sent throughout the kingdom and commanded to set free all those who were imprisoned for the sake of faith, and that they should not work during the Passion week as the Apostles commanded.", ar: "" } },
      { kind: 'reading', text: { en: "Then he sent his mother Helena to Jerusalem where she discovered the Holy Cross of Our Lord Christ. In the seventeenth year of his reign the Holy Council of the Three Hundred and Eighteen bishops assembled at Nicea in the year 325 A.D. which arranged the affairs of the Christians and put down the cannons of the church. He rebuilt the city of Byzantium and called it after his name \"Constantinia\" and he brought to it many of the bodies of the apostles and holy martyrs. He departed in the city of Nicomedia, they laid him in a gold sarcophagus, carried him and brought him to Constantinia. The Patriarch, bishops, priests, and all the people received him with prayers, psalms, and spiritual hymns, and laid him in the sanctuary of the holy apostles. All the days of his life were seventy five years.", ar: "" } },
      { kind: 'reading', text: { en: "To Our God is the glory, might, and dominion and may His mercy and grace be upon us forever. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The commemoration of Anba Sarapamon, known as \"The Veiled\" Bishop of El-Monofia.", ar: "نياحة القديس صرابامون أبو طرحة" } },
      { kind: 'reading', text: { en: "On this day also is the commemoration of Anba Sarapamon, known as \"The Veiled\" Bishop of El-Monofia. This blessed and great Saint was contemporary of Pope Petros El-Gawly and one of his famous bishops. God had granted him the gift to heal the sick, and to cast out evil spirits.", ar: "كان الطوباوي العظيم والقديس الكبير أنبا صرابامون مطران المنوفية الشهير بأبي طرحه من أشهر الأساقفة التي قام برسامتهم البابا بطرس السابع البطريرك ال 109 ، وقد منحه الله موهبة شفاء المرضى وأخراج الأرواح النجسة . وقد أخرج روحا نجسة من الأميرة زهرى هانم كريمة محمد على باشا الكبير والى مصر ، ولم يرغب في شئ مما قدمه إليه الأمير العظيم ، واكتفى بطلب بعض المؤونة والكسوة لرهبان الأديرة وإرجاع الموظفين إلى الدواوين كما كانوا في سالف الزمان فأعجب به الوالي وأجاب طلبه ، في أثناء وجوده في الأسقفية عمل عجائب كثيرة منها إخراج الشياطين ، وشفاء المرضى بكل بلدة يحل فيها ، مسلمين ونصارى، وقد شاهده كثيرا القمص سيداروس روفائيل عم القمص سيداروس اسحق مؤسس كنيسة المطرانية بشبين الكوم فقال : &quot; كان يؤتي إليه بالمصابين بالأرواح النجسة ، ويضعونهم أمامه وخلفه ، فكان يأخذ بيده قلة ماء ، ويتلو على كل واحد منهم مزمور &quot;خاصم يارب مخاصمي &quot; . فلا يفرغ من قراءة ربعه ، أو نصفه حتى يصرخ الروح النجس بحالة إزعاج شديد &quot; في &quot;عرضك في عرضك &quot;، فيقول بلغته الصعيدية &quot;همله يا أبوي &quot; . ثم يصب جانبا من ماء القلة ، ويرش به المصاب في وجهه ثلاث مرات ، وفى كل مرة يقول إيسوس بي إخرستوس ( يسوع المسيح ) . ففي الحال يخرج الروح النجس . وذات مرة كان بالبتانون في أيام القمص منصور فرج ، وعند زيارة البلدة سأل القمص منصور فرج ،- وكان الأسقف لا يميل إلى خلفة البنات - &quot; عندكش وليدات اليوم يا أبوي منصور &quot; ؟ فأجابه &quot; عندي بنت &quot; فقال : بنت كبه &quot; . وقبل أن يفارق الأسقف البلدة ماتت البنت . وتكرر هذا في زيارة ثانية . ثم أعطاه الله بنتا ثالثة . وعند ذهابه إلى مصر ذهب القمص منصور لزيارته – وكان يصلى في كنيسة حارة زويلة – فسأله الأسقف &quot; عندكش وليدات فأجابه القمص بحزن وصعوبة &quot; ما باقولش يا اخوي &quot; قال الأسقف &quot; ليه يا أبوي &quot; أجابه &quot; أقول تقولي كبه وآنا في احتياج لظفر بنت . الله يجيب وآنت تودي . قال له الأسقف &quot; ما عدتش أقول يا أبوي &quot; وأوقفه أمام الهيكل وقال &quot; يا يسوع الناصري ولدين لأبوي منصور . وأجاب الله طلبه الأسقف وخلف أربعة أولاد هم القمص منصور خليفته وفرج رئيس حسابات المديرية وتوما الذي توظف بالمديرية ومرقس . كما يذكر تاريخه عجائب وتصرفات حكيمة وقد كتبت هذه فقط علي سبيل المثال ( انظر كتاب نوابغ الأقباط في القرن التاسع عشر. توفيق اسكاروس ج 1 ) ." } },
      { kind: 'reading', text: { en: "He was called Salib. When he was a young man, some evil women seized him and accused him of murdering a young man they had killed in the market. In the court, he lifted up his heart to God and with tears he asked the help of St. Mary and other saints. He looked to the slain person and asked him to confess before the judge who killed him. The slain person rose up and told the judge about the murderesses. The judge was astonished and set Salib free. Salib left the court and went immediately to St. Antonios monastery to become a monk, and later on, the Pope chose him a Bishop for El-Monofia.", ar: "وقد أجرى الله عجائب كثيرة على. يدي البابا بطرس السابع ، اشهرها حادثة وفاء النيل فقد حدث أن النيل لم يف بمقداره المعتاد لآرواء البلاد في إحدى السنين ، فخاف الناس من وطأة الغلاء وشده الجوع إذا أجدبت الأرض ، واستعانوا بالباشا طالبين منه أن يأمر برفع الأدعية والصلوات إلى الله تعالي لكي يبارك مياه النيل ويزيدها فيضانا حتى تروي الأراضي فتأتي بالثمار الطيبة ولا تقع المجاعة علي الناس فاستدعي البابا بطرس السابع رجال الاكليروس وجماعة الأساقفة وخرج بهم إلى شاطئ النهر واحتفل بتقديم سر الشكر وبعد إتمام الصلاة غسل أواني الخدمة المقدسة من ماء النهر وطرح الماء مع قربانة البركة في النهر فعجت أمواجه واضطرب ماؤه وفاض فأسرع تلاميذ البابا إلى رفع أدوات الاحتفال خشية الغرق فعظمت منزلة البطريرك لدي الباشا وقربه إليه وكرم رجال أمته وزادهم حظوة ونعمة ." } },
      { kind: 'reading', text: { en: "When Mohammed Ali Basha asked the Pope's help concerning his daughter Zahra Hanem who was possessed by evil spirit, he sent Anba Sarapamon who healed her by praying over her. Mohammed Ali offered him money, but he refused saying that God's gifts are free. When the Governor insisted he asked for supplies and clothes for the monks in the monasteries, and to reinstate the Copts to their jobs in the government.", ar: "ومن هذه العجائب المدهشة أيضا حادثة النور في القدس الشريف فقد حدث أن الأمير إبراهيم باشا نجل محمد علي باشا بعد أن فتح بيت المقدس والشام سنة 1832 م أنه دعا البابا بطرس السابع لزيارة القدس الشريف ومباشرة خدمة ظهور النور في يوم سبت الفرح من قبر السيد المسيح بأورشليم كما يفعل بطاركة الروم في كل سنة ، فلبي البابا الدعوة ولما وصل فلسطين قوبل بكل حفاوة وإكرام ودخل مدينة القدس بموكب كبير واحتفال فخم اشترك فيه الوالي والحكام ورؤساء الطوائف المسيحية." } },
      { kind: 'reading', text: { en: "May his prayers be with us, and glory be to God forever. Amen.", ar: "ولما رأي بحكمته أن انفراده بالخدمة علي القبر المقدس يترتب عليه عداوة بين القبط والروم اعتذر للباشا لإعفائه من هذه الخدمة فطلب إليه أن يشترك مع بطريرك الروم – علي أن يكون هو ثالثهم لأنه كان يرتاب في حقيقة النور . وفي يوم سبت النور غصت كنيسة القيامة بالجماهير حتى ضاقت بالمصلين فأمر الباشا بإخراج الشعب خارجا بالفناء الكبير . ولما حان وقت الصلاة دخل البطريركان مع الباشا إلى القبر المقدس وبدأت الصلاة المعتادة . وفي الوقت المعين انبثق النور من القبر بحالة ارتعب منها الباشا وصار في حالة ذهول فأسعفه البابا بطرس حتى أفاق . أما الشعب الذي في الخارج فكانوا أسعد حظا ممن كانوا بداخل الكنيسة فان أحد أعمدة باب القيامة الغربي انشق وظهر لهم منه النور ، وقد زادت هذه الحادثة مركز البابا بطرس هيبة واحتراما لدي الباشا وقام قداسته بإصلاحات كبيرة في كنيسة القيامة." } },
      { kind: 'reading', text: { en: "", ar: "وفي أيام هذا البابا أراد محمد علي باشا ضم الكنيسة القبطية إلى كنيسة روما بناء علي سعي أحد قادته البابويين وذلك مقابل خدمات القادة والعلماء الفرنسيين الذين عاونوا محمد علي باشا في تنظيم المملكة المصرية . فاستدعي الباشا المعلم غالي وابنه وابنه باسيليوس وعرض عليهما الموضوع فأجابا الباشا بأنه سيترتب علي هذا الضم ثورات وقلاقل بين أفراد الآمة القبطية وحقنا للدماء وتشجيعا لأمر الضم . سيعتنق هو وأولاده المذهب البابوي بشرط أن لا يكرهوا علي تغيير طقوسهم وعوائدهم الشرقية فقبل الباشا منهما هذا الحل وأعلنا بناء علي ذلك اعتناقهما المذهب البابوي . ولم ينضم إليهما سوي بعض الاتباع واستمروا جميعا مع ذلك يمارسون العبادة في الكنائس القبطية" } },
      { kind: 'reading', text: { en: "", ar: "وفي أيامه نبغ بين رهبان القديس أنطونيوس الراهب داود وتولي رئاسة الدير فظهرت ثمرات أعماله في تنظيم الدير وترقية حال رهبانه فاختار البابا بطرس - لفرط ذكائه وحسن تدبيره -في مهمة كنيسة في بلاد أثيوبيا فأحسن القيام بها وكانت عودته لمصر بعد نياحة البابا بطرس ." } },
      { kind: 'reading', text: { en: "", ar: "ومما يخلد ذكر البابا بطرس أن إمبراطور روسيا أوفد إليه أحد أفراد عائلته ليعرض عليه وضع الكنيسة تحت حماية القيصر فرفض العرض بلباقة قائلا : أنه يفضل أن يكون حامي الكنيسة هو راعيها الحقيقي . الملك الذي لا يموت فأعجب الأمير بقوة إيمان البابا وقدم له كل إكرام وخضوع وتزود من بركته وأنصرف من حضرته مقرا بأنه حقيقة الخليفة الصالح للملك الأبدي المسيح الفادي" } },
      { kind: 'reading', text: { en: "", ar: "ولما أتم هذا البابا رسالته واكمل سعيه تنيح بسلام وصلوا عليه باحتفال عظيم في يوم اثنين البصخة أشترك فيه رؤساء الطوائف المسيحية بالكنيسة المرقسية بالأزبكية ودفن بها بجانب البابا مرقس سلفه ومعهما الأنبا صرابامون أسقف المنوفية في الجهة الشرقية القبلية من الكاتدرائية الكبرى بالأزبكية" } },
      { kind: 'reading', text: { en: "", ar: "وأقام علي الكرسي البطريركي 42 سنة و 3 شهور و 12 يوما وخلي الكرسي بعده سنة واحدة و 12 يوما . صلاته تكون معنا ولربنا المجد دائما آمين ." } },
      { kind: 'heading', text: { en: "The Departure of Pope Peter (Petros) VII, the One Hundred and Ninth Patriarch.", ar: "نياحة البابا بطرس السابع البطريرك ال 109" } },
      { kind: 'reading', text: { en: "On this day also of the year 1568 A.M. (April 5th., year 1852 A.D. the holy father Pope Peter (Petros) VII, the 109th. Pope of Alexandria, departed. This father was born in the village of Gawli - Manfalout, and his name was Mankarius. He forsake the world since his young age, and the Divine grace led him to the monastery of the great St. Antonios where he became a monk. He immersed in worship, asceticism and purity as he occupied himself by reading the ecclesiastic books and learned the theological and liturgical subjects. He was ordained priest for the monastery, he surpassed his fellows in the practice of virtues and performing the religious duties, and was called Fr. Marcurius. Then he was promoted to archpriest (Hegumen) for his asceticism, zeal, and the purity of his heart.", ar: "فى مثل هذا اليوم من سنة 1568 ش ( 5أبريل سنه 1852 م ) تنيح القديس البابا بطرس السابع البطريرك ال 109 ولد هذا الأب بقرية الجاولى مركز منفلوط ، وكان اسمه أولا منقريوس . زهد العالم منذ صغره فقادته العناية الإلهية إلى دير القديس العظيم أنطونيوس فترهب فيه وتعمق في العبادة والنسك والطهارة كما تفرغ إلى مطالعة الكتب الكنسية وتزود بالعلوم الطقسية واللاهوتية الآمر الذي دعا إلى رسامته قسا علي الدير ففاق أقرانه في ممارسة الفضائل وتأدية الفرائض وقد دعي القس مرقوريوس ، ثم رقي قمصا لتقشفه وغيرته وطهارة قلبه" } },
      { kind: 'reading', text: { en: "When his news reached Pope Marcus (Mark) VIII, he called him. A group of the Ethiopians had come, delegated from the king of Ethiopia asking for a Metropolitan instead of Anba Yousab their predecessor one who had departed. The Pope searched for an honorable, learned and just man, and he found these virtues in the Archpriest Marcurius, so he chose him to be a Metropolitan for Ethiopia. During the ordination, instead he ordained him a bishop without a parish and called him Theophilus and ordained Anba Macarius II a Metropolitan for the kingdom of Ethiopia in the year 1808 A.D.", ar: "ولما وصلت أخباره إلى مسامع البابا مرقس الثامن استدعاه إليه . وكان قد حضر جماعة من الأثيوبيين من قبل ملك أثيوبيا يطلبون مطرانا بدل المتنيح الأنبا يوساب مطرانهم السابق ومعهم خطابات إلى حاكم مصر والي البابا مرقس الثامن فبحث البابا عن رجل صالح وعالم فاضل فلم ير أمامه إلا القمص مرقوريوس فاختاره لمطرانية أثيوبيا فرسمه مطرانا إلا أنه في وقت الرسامة لم يقلده علي أثيوبيا بل جعله مطرانا علي بيعة الله المقدسة وسماه ثاوفيلس ورسم بدلا منه الأنبا مكاريوس الثاني مطرانا لمملكة أثيوبيا في سنة 1808" } },
      { kind: 'reading', text: { en: "After ordaining Anba Theophilus a bishop at large the Pope kept him with him in the patriarchate to help him in managing the church business and the affairs of the Coptic people.", ar: "وبعد رسامة الأنبا ثاوفيلس مطرانا عاما استبقاه البابا معه في القلاية البطريركية ، يعاونه في تصريف أمور الكنيسة وشؤون الأمة القبطية ." } },
      { kind: 'reading', text: { en: "When Pope Marcus VIII departed on the\nyear 526 A.M. (December 21st., year 1809), the bishops were present in Cairo met with the notables of the people and unanimously agreed to chose Anba Theophilus to be his successor. They ordained him Patriarch in\nSt. Mark church in El-Azbakiah three days after the departure of Pope Marcus, on sunday the 16th. of Kiahk, year 1526 A.M. (December 24th., year 1809), and they called him Peter VIII and he was known by Petros El-Gawly. He was a gentle, meek, wise, greatly intelligent, outstandingly smart father with a nobel policy in caring for the people. He devoted himself to studying, reading and learning the ecclesiastic subjects and the holy books. He wrote a valuable text to defend the church and its teachings, and he provided the patriarchal library with valuable and rare texts. His era was a peaceful time in the land, so the church had a complete serenity and total freedom in worship, and the churches were renovated in Upper and Lower Egypt.", ar: "ولما تنيح البابا مرقس الثامن في يوم 13 كيهك سنة 526 ش ( 21 ديسمبر سنة 1809 م ) وكان الاساقفه موجودين بمصر فاجتمعوا مع أراخنة الشعب وأجمع رأيهم علي أن يكون خليفة له فرسموه بطريركا في الكنيسة المرقسية بالازبكية بعد ثلاثة أيام من نياحة البابا مرقس أي في يوم الأحد 16 كيهك سنة 1526 ش ( 24 ديسمبر سنة 1809 م ) . ودعي أسمه بطرس السابع واشتهر باسم بطرس الجاولي وكان أبا وديعا متواضعا حكيما ذا فطنه عظيمة وذكاء فائق وسياسة سامية لرعاية الشعب والكتب المقدسة . وقد وضع كتابا قيما دافع فيه عن الكنيسة وتعاليمها كما قام بتزويد المكتبة البطريركية بالكتب النفيسة وفي عهده رفرف السلام علي البلاد فنالت الكنيسة الراحة التامة والحرية الكاملة في العبادة وتجددت الكنائس في الوجهين القبلي والبحري" } },
      { kind: 'reading', text: { en: "During his Papacy the Chair of El-Nuba and Sudan returned to the Chair of Alexandria after separation for five hundred years. The governor of Egypt Muhammad Ali Basha conquered Sudan and took over its land and consolidated it to the land of Egypt. Many of the people of Sudan returned to the Christian faith and many of the christian government employees and army men lived in Sudan. They built churches, then they asked Pope Petros to send them a bishop to shepherd the Christian people in these countries. He ordained for them a bishop who was nominated by the people of Sudan from among the monks called Damianus. This bishop departed during the days of Pope Petros so he ordained for them another.", ar: ". وفى مدة رئاسته عاد الى الكرسى الإسكندري كرسى النوبة والسودان ، بعد أن انفصل مدة خمسمائة عام . ويرجع فضل عودة النوبة الى الحظيرة المرقسية الى أن عزيز مصر محمد على باشا الكبير فتح السودان وامتلك أراضيه وضمها الى الأقطار المصرية فعاد كثيرون من أهل السودان الى الدين المسيحى ، كما استوطن فيه الكثيرون من كتاب الدولة النصارى ورجال الجيش وبنوا الكنائس . ثم طلبوا من البابا بطرس أن يرسل لهم أسقفا ليرعى الشعب المسيحى بهذه الأقطار فرسم لهم أسقفا زكاه شعب السودان من بين الرهبان اسمه داميانوس . وقد تنيح هذا الأسقف فى أيام البابا بطرس فرسم لهم أسقفا غيره . ومن ذلك الحين تجدد كرسى النوبة الذي هو السودان . وقام هذا البابا فى مدة توليه الكرسى الإسكندري برسامة خمسة وعشرين أسقفا على أبرشيات القطر المصري والنوبة ، كما رسم مطرانين لأثيوبيا : الأول الأنبا كيرلس الرابع فى سنة 1820 والثاني فى سنة 1833 م ." } },
      { kind: 'reading', text: { en: "This Pope, during his papacy, ordained twenty five bishops for the different parishes of Egypt and Nuba, and he ordained two Metropolitans For Ethiopia, the first was\nin the year 1820, and the second in the year 1833 A.D.", ar: "" } },
      { kind: 'reading', text: { en: "God had performed many wonders through the hands of Pope Peter VII the most famous of them is the incident of the Nile Inundation. One year the flood of the Nile was not enough to water people, land and animals. The masses were worried about famine, inflation and high prices if the land could not be cultivated. They went to the Governor of Egypt asking to order the clergy to pray and supplicate God almighty that He might bless the water of the Nile and increase the flood water to be able to water the land to bring forth a plenteous crop and to avoid a famine that might befall the people. Pope Peter VII called the bishops and the clergy and went with them to the banks of the river where he celebrated the Divine Liturgy and after the service he washed the Holy Service utensils with water from the river, then he threw the water and the blessed Kourbana (Blessed Bread) in the river. The waves of the river roared, the water was disturbed and flooded, the deacons in haste removed all the elements used in the celebration, fearing of drowning. This incident glorified the Patriarch position before the Basha the Governor who made him close to him, and honor the men of his nation, and increased their authority and grace.", ar: "" } },
      { kind: 'reading', text: { en: "From these remarkable wonders also was the incident of the Holy Sepulcher light in Jerusalem. After prince Ibrahim Basha, Mohammed Ali Basha's son, had conquered Jerusalem and Syria year 1832 A.D., he invited Pope Peter VII to visit Jerusalem and attend to the service of the appearance of the light on Bright Saturday from the Sepulcher of the Lord Christ in Jerusalem as the Greek Orthodox Patriarchs did every year. The Pope accepted the invitation, and when he arrived, he was received with honor and reverence and he entered Jerusalem with a great procession and a splendid celebration, in which the governor, the rulers and the heads of the different Christian denominations participated. He realized with his wisdom that if he minister alone in the Holy sepulcher that would cause animosity between the Copts and the Greeks. The Pope asked the Basha to relieve him from this service, but he asked him to participate with the Greek Patriarch on the condition that he will be their third, for he doubted the authenticity of the light. On Bright Saturday the church of the holy sepulcher was crowded with the worshipers, the Basha ordered the people to evacuate the church to the spacious outer courtyard. When the time to start the service came the two Patriarchs and the Basha entered the Holy Sepulcher to pray the customary prayers. In the specific time, the light burst out of the Sepulcher in a way that terrified the Basha, who became in a daze and confusion, and the Pope attended to him until he recovered. The people outside in the courtyard were not deprived from the blessing of the light since one of the pillars of the western gate of the church split and the light appeared to them from the pillar. This incident increased the reverence and respect of the Pope before the Basha. His holiness the Pope made many repairs and renovations in the church of Resurrection.", ar: "" } },
      { kind: 'reading', text: { en: "During the days of this Pope, Mohammed Ali Basha wanted to join the Coptic church with the church of Rome because of the efforts of one of his catholic army generals, in return of the services of the French scientists and army leaders who offered the Governor to organize the Egyptian government. The Governor (Basha) called the master Ghali and his son Basilius and presented the subject to them, and they replied saying that this merge would cause revolt and unrest among the Coptic people so to avoid shedding of blood and to encourage the topic of unity, his family and himself would join the Catholic church, on a condition that they would not be forced to change their rituals or Eastern custom. The Basha accepted that solution and accordingly they declared their joining the Catholic faith, and only few followed them, nevertheless they all continued to worship in Coptic churches.", ar: "" } },
      { kind: 'reading', text: { en: "During his time, the monk Daoud (David) excelled among the monks of St. Antonios monastery, and was promoted to be the head of the monastery. The fruits of his effort became obvious, in organizing the monastery and improving the condition of the monks. Pope Peter chose him for his intelligence and good management and sent him to Ethiopia in an official church duty which he took care of it well, and his return to Egypt was after the departure of Pope Peter.", ar: "" } },
      { kind: 'reading', text: { en: "History will exalt the memory of Pope Peter (Petros), because the Russian Caesar sent his delegates to offer putting the Coptic Church under the protection of Caesar. The Pope refused the proposal graciously by asking: \"Does your Caesar live forever?\" When the envoy answered that he would die like all human beings, the Pope told him that he preferred the protector of the church would be her true shepherd, the King that does not die. The prince admired the Pope's faith and patriotism, and he left after taking the blessings from the Pope stating that he is truly the good successor for the Eternal King, Christ the Savior.", ar: "" } },
      { kind: 'reading', text: { en: "When this Pope finished his course and completed his strife, he departed in peace. They prayed over him in a great celebration on Paschal Monday, participated in it all the heads of the Christian denominations in St. Mark church in El-Azbakiah. He was buried beside his predecessor Pope Marcus, and Anba Sarapamon bishop of El-Menofia in the eastern side of the great cathedral in El-Azbakiah. He stayed on the Patriarchal Chair for 42 years, 3 month, and 12 days and the Chair remained vacant after him one year and 12 days.", ar: "" } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-29",
    title: { en: "Baramhat 29", ar: "29 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Life giving Annunciation.", ar: "عيد البشارة المجيد" } },
      { kind: 'reading', text: { en: "On this day the church commemorates the Annunciation of our Lady, the Theotokos, the\nVirgin St. Mary. When the appointed time by God since eternity for the salvation of the human race had come, God sent\nto the\nVirgin St. Mary, who is from the tribe of Judah the house of\n, to announce her with the Divine conception and the Glorious Birth as the Holy Scriptures testifies: \" Now in the sixth month the\nangel Gabriel was sent by God to a city of Galilee named Nazareth, to a virgin betrothed to a man whose name was Joseph, of the house of David. The virgin's name was Mary. And having come in, the angel said to her, \"Rejoice, highly favored one, the Lord is with you; blessed are you among women!\" But when she saw him, she was troubled at his saying, and considered what manner of greeting this was. Then the angel said to her, \"Do not be afraid, Mary, for you have found favor with God. \"And behold, you will conceive in your womb and bring forth a Son, and shall call His name JESUS. \"He will be great, and will be called the Son of the Highest; and the Lord God will give Him the throne of His father David. \"And He will reign over the house of Jacob forever, and of His kingdom there will be no end.\" Then Mary said to the angel, \"How can this be, since I do not know a man?\" And the angel answered and said to her, \"The Holy Spirit will come upon you, and the power of the Highest will overshadow you; therefore, also, that Holy One who is to be born will be called the Son of God.", ar: "في هذا اليوم تحتفل الكنيسة بتذكار بشارة أمنا والدة الإله العذراء القديسة مريم وذلك أنه لما جاء الوقت المعين منذ الأزل من الله لخلاص البشر . أرسل الله رئيس الملائكة جبرائيل إلى القديسة مريم البتول التي من سبط يهوذا ومن قبيلة داود الملك ليبشرها بالحبل الإلهي والميلاد المجيد . كما شهد بذلك الكتاب المقدس بقوله : في الشهر السادس أرسل جبرائيل الملاك من الله إلى مدينة من الجليل اسمها ناصرة إلى عذراء مخطوبة لرجل من بيت داود اسمه يوسف واسم العذراء مريم فدخل إليها الملاك وقال : سلام لك آيتها الممتلئة نعمة . الرب معك مباركة أنت في النساء فلما رأته اضطربت من كلامه وفكرت ما عسي أن تكون هذه التحية فقال لها الملاك &quot; لا تخافي يا مريم لأنك قد وجدت نعمة عند الله وها أنت ستحلبين وتلدين أبنا وتسمينه يسوع هذا يكون عظيما وابن العلي يدعي ويعطيه الرب الإله كرسي داود أبيه ويملك علي بيت يعقوب إلى الأبد و لا يكون لملكه نهاية’ &quot; فقالت مريم للملاك &quot; كيف يكون هذا وأنا لست أعرف رجلا ؟ &quot; فأجاب الملاك وقال لها &quot; الروح القدس يحل عليك وقوة العلي تظللك فلذلك أيضا القدوس المولود منك يدعي ابن الله &quot;" } },
      { kind: 'reading', text: { en: "Then the angel gave her the proof of the validity of his massage: \"Now indeed,\nyour relative has also\nin her old age; and this is now the sixth month for her who was called barren. \"For with God nothing will be impossible.\" Then Mary said, \"Behold the maidservant of the Lord! Let it be to me according to your word.\" And the angel departed from her. (Luke 1:26-36)", ar: "ثم قدم لها دليلا علي صدق بشارته قائلا : &quot; هوذا اليصابات نسيبتك هي أيضا حبلي بابن في شيخوختها وهذا هو الشهر السادس لتلك المدعوة عاقرا , لأنه ليس شيء غير ممكن لدي الله &quot; فقالت مريم &quot; هودا أنا أمة الرب . ليكن لي كقولك &quot; فمضي من عندها الملاك (لو 1 : 26 – 38 )" } },
      { kind: 'reading', text: { en: "When she had accepted this Divine Annunciation, the Only Begotten Son, the Word of God, who is One of the Three eternal Persons, came and dwelt in her womb, a dwelling, the human race can not comprehend. And straightway He united with perfect humanity a complete unity inseparable and unchangeable after the unity.", ar: "وعند قبولها هذه البشارة الإلهية نزل الابن الوحيد قوة الله الكلمة أحد الثلاثة الأقانيم الأزلية وحل في أحشائها حلولا لا يدرك البشر كيفيته واتحد للوقت بإنسانية كاملة اتحادا كاملا لم يكن بعده افتراق ." } },
      { kind: 'reading', text: { en: "This day then is the first-born of all feasts, for in it was the beginning of the salvation of the world which was fulfilled by the Holy Resurrection of our Lord, saving Adam and his offspring from the hands of Satan.", ar: "فهذا اليوم آذن هو بكر الأعياد . لأن فيه كانت البشري بخلاص العالم وفي مثله تم الخلاص بالقيامة المجيدة لآدم وبنيه من أيدي الشيطان نسأل إلهنا وفادينا أن يتفضل فيغفر لنا آثامنا ويتجاوز عن خطايانا . أمين" } },
      { kind: 'reading', text: { en: "We ask Our God and Savior graciously to forgive our transgressions and excuse our sins. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Resurrection of the Lord Christ from the dead.", ar: "تذكار قيامة مخلصنا الصالح من الاموات" } },
      { kind: 'reading', text: { en: "On this day also the salvation was completed by the holy Resurrection, for Our Lord when he had finished His work upon earth, during a period of thirty three years, suffered of His own free will on the eve of the twenty-seventh day of this month, and He rose from the dead on this very day. As it was on this very day the incarnation of Christ was announced to the people of the world who were awaiting Him. On friday, the living and the dead rejoiced in their Salvation, and on sunday the living became certain of it, and they knew of their resurrection by the Resurrection of the body of Christ, Who was the first-fruits of the dead as the apostle Paul Said: \"But now Christ is risen from the dead, and has become the firstfruits of those who have fallen asleep.\" (1 Corinthians 15:20)", ar: "في هذا اليوم تحتفل الكنيسة بتذكار كمال الخلاص بالقيامة المجيدة لأن ربنا له المجد لما أكمل تدبيره على الأرض ، و فى مدة ثلاث وثلاثين سنة وتألم بإرادته في ليلة السابع والعشرين من هذا الشهر قام من بين الأموات في مثل هذا اليوم الذي فيه بشر أهل العالم بتجسد المسيح الذي كانوا ينتظرونه واليوم الذي بشر فيه الأحياء والأموات ووثقوا بالخلاص كان في يوم الجمعة إلى أن تحقق ذلك في يوم الأحد للأحياء وتيقنوا من قيامتهم بقيامة جسد المسيح الذي هو رأسهم كما يقول الرسول أن المسيح هو الذي أقام المضجعين نسأله كعظم رأفته وسعة رحمته أن يتفضل علينا بمغفرة خطايانا له المجد الدائم إلى الأبد . آمين ." } },
      { kind: 'reading', text: { en: "We ask Him according to His great mercy and His compassion that He may grant us the forgiveness of our sins. Amen.", ar: "" } }
    ],
  },
  {
    id: "synax-baramhat-30",
    title: { en: "Baramhat 30", ar: "30 برمهات" },
    blocks: [
      { kind: 'heading', text: { en: "The Commemoration of the Transfer of the Relies of St. James, known as the Mangled.", ar: "تذكار القديس يعقوب المقطع" } },
      { kind: 'reading', text: { en: "On this day also, is the commemoration of the relocation of the relics of \r\n. His biography and martyrdom are mentioned under the", ar: "تذكار نقل أعضاء القديس يعقوب الشهير بالمقطع وتجد ترجمة حياته وشهادته تحت البوم السابع والعشرين من شهر هاتور . صلاته تكون معنا ولربنا المجد دائما . آمين ." } },
      { kind: 'reading', text: { en: "May his prayers be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of the Archangel Gabriel the Announcer.", ar: "تذكار الملاك غبريال" } },
      { kind: 'reading', text: { en: "On this day, the church commemorates of the \r\nthe announcer, for his honor is great with God, he was worthy to \r\nto the \r\nVirgin St. Mary. He also foretold \r\nabout the return of the people of Israel from exile, about the first coming of Christ, to Whome is the glory, for the salvation of the world, and also about the end of the animal sacrifices. For what God had done for us through him it is meet for us to honor and venerate him.", ar: "في هذا اليوم تعيد الكنيسة بتذكار رئيس الملائكة جبرائيل المبشر الذي لعظم منزلته لدي الله استحق أن يحمل البشارة بابنه الوحيد إلى القديسة مريم البتول . وهو الذي سبق فأنبا دانيال النبي عن عودة الشعب الإسرائيلي من السبي وعن مجيء السيد المسيح له المجد لخلاص العالم وعن أبطال الذبائح آمين" } },
      { kind: 'reading', text: { en: "May his intercession be with us. Amen.", ar: "" } },
      { kind: 'heading', text: { en: "The Commemoration of Samson, One of the Judges of Israel.", ar: "نياحة شمشون أحد قضاة بنى إسرائيل" } },
      { kind: 'reading', text: { en: "On this day also, is the commemoration of Samson, one of the Judges of Israel. The name of the father of this righteous was Manoah from the tribe of Dan, and his mother was barren. The angel of the Lord appeared to her and announced her of his birth, and commanded her not to drink wine nor to eat unclean food all the days of her pregnancy. The angel also commanded her that no razor should come on his head, for the child was to be a Nazirite (dedicated) unto God from the womb, and that he would deliver Israel out of the hands of the Philistines.", ar: "في هذا اليوم تذكار شمشون أحد قضاة بني اسرائيل وكان اسم والد هذا البار منوح من سبط دان وكانت أمه عاقرا فأتاها ملاك الرب وبشرها بميلاده وأمرها أن تتجنب النجاسات من الأطعمة وشرب المسكرات ما دامت حاملة به . وأن لا تحلق شعر رأسه لأنه يكون نذيرا لله . وعلي يديه يتم خلاص بني اسرائيل من أهل فلسطين فلما أخبرت بعلها بما كان سأل الله أن يريه الملاك فظهر له وقال &quot; أوص امرأتك أن تحافظ علي تنفيذ ما قلته له &quot; . فحبلت وولدت هذا الصديق وباركه الرب وحل فيه روح الله فوثب تارة علي أسد وشقه وتارة قتل من أهل فلسطين ثلاثين رجلا وأحرق زرعهم فقاموا علي بني يهوذا ليحاربوا ويعطوهم شمشون فأعلمه بنو يهوذا بالأمر فقال لهم &quot; احلفوا أنتم أنكم لا تسلموني لهم ولا تقتلوني &quot; ولما حلفوا له سلم ذاته فأوثقوه بسلسلتين وسلموه لأهل فلسطين فوثبوا عليه ليقتلوه . فحل عليه روح القوة من عند الرب القوي وقطع السلسلتين كخيط الكتان المحترق ثم وجد فك حمار فأخذه وحارب به فقتل ألفا من راكبي الخيل ولما عطش وأشرف علي الموت سأل الله تعالي أن يتجنن عليه وينبع له عين ماء عذب فشرب وتقوي ولما راقبوه وهو داخل غزة ليمسكوه قام في الليل وفك باب غزة وحمله علي كتفيه وسار حتى راس الجبل" } },
      { kind: 'reading', text: { en: "When she told her husband about what the angel had said to her, her husband asked God to allow the angel to appear to him. The angel appeared, and said to him: \"All that I commanded your wife let her observe.\" The woman conceived, and gave birth to Samson, and God blessed him and the Spirit of God filled him. At one time, he tore a lion apart as one would tear a young goat, and on another time, he killed thirty men and burned their fields. The Philistines rose against the tribe of Judah to fight and seize Samson, but Samson told the men of Judah: \"Swear to me that you will not deliver me to them or kill me yourselves.\" They said to him: \"No, but we will tie you securely and deliver you into their hands. We surely shall not kill you.\" They bound him with two new cords and brought him to the Philistines, who jumped upon him to kill him. The Spirit of the Lord came mightily upon him, and the strong cords that were on his arms became as flax that were burnt with fire, and his bonds broke loose off his hands. He found a fresh jaw-bone of an ass, reached out and took it with his hand and killed a thousand men with it. Then he became very thirsty, he cried out to the Lord and said: \"You have given this great deliverance by the hands of you servant, and now shall I die from thirst... ?\" The all mighty God then split a hollow place and water came out. He drank and his spirit returned, and he survived. When he was in Gaza, the Philistines surrounded the place and laid wait for him all the night at the gate of the city to capture and kill him. Samson arose at midnight, took hold of the doors of the gate, pulled them up, put them on his shoulders, and carried them to the top of the hill. The Philistines came to his wife, Delilah, and asked her to entice Samson to find out the secret of his strength. When Samson told her that the secret was in his hair, for he was a Nazirite Dedicated unto God). She told his enemies, lulled him to sleep on her knees, and called for a man to shave off the seven locks of hair off his head. She began to afflict him, as his strength went from him. The Philistines took him to their city, insulted him, and plucked out his eyes.", ar: "وبعد ذلك أرسلوا إلى زوجته ووعدوها بعطايا جزيلة لتستعلم منه عن سر قوته ولما أعلمها أن قوته في شعره لأنه نذير لله قامت وأعلمت أعداءه فكمنوا له ولما نام دخلوا عليه وحلقوا رأسه فضعفت قوته فقيدوه ومضوا به إلى بلادهم وأهانوه وقلعوا عينيه وبعد هذا نبت شعره ثانية وعادت إليه قوته فدخل إلى هيكل الوثن في يوم عيد الصنم وكان مجتمعا فيه جميع أهل غزة فوقف في وسط الهيكل وأحاط عمودا بيمينه وأخر بيساره ثم جمع يديه وقال &quot; علي وعلي أعدائي &quot; فسقط العمودان وسقط الهيكل بسقوطهما فمات كل من كان فيه وكان عدد الذين ماتوا في هذا الوقت أكثر من الذين قتلهم طول عمره ثم مات هو أيضا في جملتهم وكانت مدة حكمه في بني اسرائيل عشرين سنة ثم تنيح بسلام ولربنا المجد دائما آمين" } },
      { kind: 'reading', text: { en: "His hair grew again, and his strength came back to him. He went to the temple of their idol, and took hold of the two middle pillars which supported the temple. Samson leaned with all his strength on the two pillars and said: \"Let me die with the Philistines.\" The temple fell on three thousands of the Philistine people and their lords killing them all. So the dead that he killed on his death were more than he killed in his life. He judged for the people of Israel twenty years, then departed in peace.", ar: "" } },
      { kind: 'reading', text: { en: "To our God is the glory for ever, Amen.", ar: "" } }
    ],
  }
];
